GR_SC.g01_01=[{w:null,t:"まっ暗な石の通路。"},{w:null,t:"つきあたりの壁のあたりから、大きな生き物の寝息のような、低い音。"},{w:null,t:"世界のどこかの地面の下では、大昔の生き物が、まだ眠っている。",v:"01_0024"},{w:null,t:"2100年の地球。"},{w:null,t:"西暦2100年。",v:"01_0026"},{w:null,t:"研究所で生まれた生き物「テリオン」は、世界じゅうの町で、人と暮らしている。",v:"01_0027"},{w:null,t:"大きな街のビルの壁に、テリオンどうしの勝負の配信。"},{w:null,t:"日本の地図。"},{w:null,t:"日本を、のぞいて。",v:"01_0030"}];
GR_SC.g01_02=[{w:null,t:"ギリシャ。オリーブの村、オリーヴァ。",v:"01_0033"},{w:null,t:"青い海。白い家の坂道に、屋台が並ぶ。"},{w:null,t:"坂の上から、スーツケースを引いた男の子が下りてくる。"},{w:null,t:"オリーブの屋台のおばさん（日差しで色が変わるうすい上着の、2100年の普段着）が、ヤマトに声をかける。"},{w:"x",n:"屋台のおばさん",t:"あんた、ひとりかい？　そんな大きな荷物引いて、どこから来たの。",v:"01_0037"},{w:"hero",t:"日本から。",v:"01_0038"},{w:"hero",t:"じいちゃんと一緒に来たんだけど。",v:"01_0039"},{w:"hero",t:"空港でおれがトイレに行ってるあいだに、いなくなった。",v:"01_0040"},{w:"x",n:"屋台のおばさん",t:"いなくなった？　置いていかれたのかい。",v:"01_0041"},{w:"hero",t:"メッセージは「村で待ってろ」って、これだけ。",v:"01_0042"},{w:"hero",t:"ホテルの名前のとこで切れてるし。",v:"01_0043"},{w:"hero",t:"三時間前から、返事もこねーんだよ。",v:"01_0044"},{w:"x",n:"屋台のおばさん",t:"あらまあ。ほら、オリーブお食べ。",v:"01_0045"},{w:"x",n:"屋台のおばさん",t:"腹がへってると、よけい腹が立つからね。",v:"01_0046"},{w:null,t:"ヤマト、オリーブを一つつまむ。"},{w:"x",n:"屋台のおばさん",t:"あっ、また、あの泥棒！　こらー！　今日はいくつ持ってった！",v:"01_0048"},{w:"hero",f:"surprised",t:"なにあれ！？　しっぽ、燃えてんじゃん！",v:"01_0049"},{w:null,t:"坂の下で、急ブレーキの音。"},{w:null,t:"車から、二人組が降りてくる。"},{w:null,t:"市場の人たちが、さっと道をあける。"},{w:"x",n:"八百屋のおじさん",t:"ヴィクター一味だ……。",v:"01_0053"},{w:"x",n:"屋台のおばさん",t:"あんた、こっちに下がってな。",v:"01_0054"},{w:"x",n:"屋台のおばさん",t:"あいつら、テリオンをさらっていく連中だよ。",v:"01_0055"},{w:"x",n:"屋台のおばさん",t:"先週は、パン屋の猫の子が連れていかれた。",v:"01_0056"},{w:null,t:"マルコ、鳥の子の店番がいる屋台の前を通りかかる。"},{w:"marco",t:"これも、もらっとくっす。",v:"01_0058"},{w:"x",n:"八百屋のおじさん",t:"おい、それはうちの——！",v:"01_0059"},{w:"nina",t:"なんか言った？　おじさん。",v:"01_0060"},{w:null,t:"ニーナ、おじさんの屋台のトマトの山を、足でけとばす。"},{w:"hero",t:"（小声で）なんで、だれも止めねーの？",v:"01_0062"},{w:"x",n:"屋台のおばさん",t:"（小声で）車に国の札がついてるでしょ。",v:"01_0063"},{w:"hero",t:"（小声で）札がついてたら、なにしてもいいのかよ。",v:"01_0064"},{w:"x",n:"屋台のおばさん",t:"（小声で）国の仕事って、しるしだからね。",v:"01_0065"},{w:"x",n:"屋台のおばさん",t:"（小声で）手を出したら、こっちが捕まるのさ。",v:"01_0066"},{w:"nina",t:"あたしらの用は、あの狐。",v:"01_0067"},{w:"nina",t:"ああいう、だれにもなつかない野良が、いちばん高く売れるのよ。",v:"01_0068"},{w:"nina",t:"ね、マルコ。",v:"01_0069"},{w:"marco",t:"そうっす。今日こそ、つかまえるっす。",v:"01_0070"},{w:null,t:"ニーナ、手首の画面を動かす。"},{w:"nina",t:"右！　右から回って！",v:"01_0072"},{w:null,t:"マルコ、あわてて画面をはじく。"},{w:null,t:"ニーナ、だまってマルコを見る。"},{w:null,t:"狐、マルコの頭を踏み台にして、まっすぐ坂の上へ。"},{w:null,t:"狐が、ヤマトの顔に正面からぶつかる。"},{w:null,t:"狐、ヤマトのおなかの上に着地する。目と目が合う。"},{w:"hero",f:"hurt",t:"うわっ、熱っ……！",v:"01_0079"},{w:null,t:"狐、ヤマトの顔を踏んで、跳んでいく。"},{w:null,t:"ヤマト、起き上がる。ふてくされた顔が、どこにもない。"},{w:"hero",f:"smile",t:"すっげー！！　おばちゃん、荷物見てて！",v:"01_0082"},{w:"x",n:"屋台のおばさん",t:"ちょっと、あんた！　ヴィクターの前に出ちゃだめだって！",v:"01_0083"},{w:null,t:"ヤマト、服を散らかしたまま、走りだす。"},{w:null,t:"第1話　テリオン・ワールド",v:"01_0086"}];
GR_SC.g01_03=[{w:null,t:"狐。そのうしろにドローン三機。"},{w:"marco",t:"ニーナさん、なんか、子どもがついてきてるっす。",v:"01_0093"},{w:"nina",t:"子どもなんか、ほっときな。狐をつかまえるのが先だよ。",v:"01_0094"},{w:"hero",t:"おーい、待てよー！　ちょっとさわるだけだって！",v:"01_0095"},{w:"x",n:"子ども1",t:"あの子、ヴィクター一味より速いよ！",v:"01_0096"},{w:null,t:"ドローンが網を落とす。狐、ふり向きざまに、しっぽから小さな火をとばす。"},{w:"marco",t:"あー！　また網、燃やされたっす！　これで今週、五枚目っすよ！",v:"01_0098"},{w:"nina",t:"だから、上から落とせって言ってんでしょ！",v:"01_0099"},{w:null,t:"狐のしっぽが、今度はヤマトに向く。"},{w:"hero",f:"hurt",t:"あちっ！　……すげえ、今の見た！？　火、とばした！",v:"01_0101"},{w:"x",n:"子ども2",t:"前髪、焦げてるよ！",v:"01_0102"},{w:"hero",t:"いいって、前髪なんか！　それより、今の火、見たかよ！",v:"01_0103"},{w:null,t:"狐の口から、半分焦げたオリーブが一つ落ちる。"}];
GR_SC.g01_04=[{w:null,t:"村の上の、古い神殿のあと。",v:"01_0107"},{w:null,t:"坂のてっぺん。"},{w:null,t:"狐、その木の根もとに逃げこむ。くわえてきたオリーブを、しっぽの火の上に乗せる。"},{w:null,t:"根もとに入ったとたん、しっぽの火が、ぼっと一回りふくらむ。"},{w:null,t:"ヤマト、息を切らして追いつく。"},{w:null,t:"狐が、根もとから一歩だけ枯れ草の上へ出る。"},{w:null,t:"ヤマト、目をまるくして、それを見ている。……が、すぐ顔がゆるむ。"},{w:"hero",t:"おまえ、ここが好きなのか？",v:"01_0114"},{w:"hero",t:"大丈夫、おれ、あいつらの仲間じゃないから。",v:"01_0115"},{w:"hero",t:"ほら、なんにもしないって。",v:"01_0116"},{w:"hero",t:"よーし、いい子だ。そのまま、そのまま……。",v:"01_0118"},{w:"hero",f:"hurt",t:"いってえええ！！　なんでだよ！　今、いい感じだったじゃん！",v:"01_0120"}];
GR_SC.g01_05=[{w:null,t:"石段の下から、ごろごろと音。"},{w:"elly",t:"あ、いたいた！　ねえ、これ、きみのでしょ？",v:"01_0126"},{w:"elly",t:"オリーブのおばさんから預かってきたよ。",v:"01_0127"},{w:"hero",t:"あ……ありがと。わざわざ持ってきてくれたの？",v:"01_0128"},{w:"elly",t:"おばさん、大さわぎしてたんだもん。",v:"01_0129"},{w:"elly",t:"「男の子が荷物置いて、狐を追っかけてった」って。",v:"01_0130"},{w:"elly",t:"……って、ちょっと、その右手！　赤くなってるじゃない！",v:"01_0131"},{w:"hero",t:"ああ、これ？　なでようとしたら、狐にガブッとやられた。",v:"01_0132"},{w:"elly",t:"やられたのに、なんでそんな、うれしそうなの！　ほら、すわって！",v:"01_0133"},{w:null,t:"ヤマト、木の根もとに座らされる。エリー、ヤマトの右手を取って、カバンを開ける。"},{w:"elly",t:"しみるよ。がまんしてね。",v:"01_0135"},{w:"hero",t:"いっ……！　しみる、しみる！",v:"01_0136"},{w:"elly",t:"あの子、フォルンっていうの。この丘に住んでる野良の狐の子。",v:"01_0137"},{w:"elly",t:"村の人はみんなそう呼んでる。だれにもさわらせないんだよ。",v:"01_0138"},{w:"elly",t:"わたしなんか、三年、毎日クッキー持ってきてるんだよ。",v:"01_0139"},{w:"elly",t:"なのに、一回もなでさせてもらったことないんだから。",v:"01_0140"},{w:null,t:"根もとの石のくぼみに、クッキーが一枚。"},{w:"hero",t:"フォルンか。かっこいい名前じゃん。",v:"01_0142"},{w:null,t:"木の上で、フォルンの耳が、ぴくっとこっちを向く。"},{w:"elly",t:"さっきの黒い車の二人、見た？　あれが、ヴィクター一味。",v:"01_0144"},{w:"elly",t:"持ち主のいないテリオンを、つかまえて売ってるの。",v:"01_0145"},{w:"elly",t:"フォルン、何回もねらわれてるんだよ。",v:"01_0146"},{w:"hero",t:"だれも守ってやんねーの？",v:"01_0147"},{w:"elly",t:"みんな、自分の子で自分を守るので、せいいっぱいなの。",v:"01_0148"},{w:"elly",t:"で、きみは？　観光？",v:"01_0150"},{w:"hero",t:"観光っていうか、テリオン見に来たんだよ。日本にはいねーし。",v:"01_0151"},{w:null,t:"エリーの手が止まる。"},{w:"elly",t:"ちょっと待って。日本から来た男の子って……。",v:"01_0153"},{w:"elly",t:"きみ、もしかして、ヤマト？",v:"01_0154"},{w:"hero",t:"え、なんでおれの名前知ってんの。",v:"01_0155"},{w:"elly",t:"わたし、エリー！　うち、ホテルやってるの！",v:"01_0156"},{w:"elly",t:"きみのおじいちゃんに頼まれて、空港まで迎えに行ったの！",v:"01_0157"},{w:"elly",t:"三時間待ったんだからね、三時間！",v:"01_0158"},{w:"hero",t:"じいちゃん、それ、おれにひと言も言ってない。",v:"01_0159"},{w:null,t:"ヤマト、手首の画面をつける。"},{w:"elly",t:"名前のとこで切れてるけど、このホテル、うちのことだよ。",v:"01_0161"},{w:"hero",t:"なんで、そこで切れるんだよ……。",v:"01_0162"},{w:"elly",t:"で、おじいちゃんは？",v:"01_0163"},{w:"hero",t:"知らない。",v:"01_0164"},{w:"hero",t:"空港でトイレに行って、もどったら、もういなかったんだ。",v:"01_0165"},{w:"elly",f:"surprised",t:"ええっ！？　それ、すっごく大変なことじゃない！",v:"01_0166"},{w:"hero",t:"いつものことだよ。じいちゃん、急に消えるの、得意だから。",v:"01_0167"},{w:null,t:"ヤマトは、話しながらも、木の上のフォルンばかり見ている。"},{w:"elly",t:"もう。心配してるの、わたしだけみたいじゃない。",v:"01_0169"}];
GR_SC.g01_06=[{w:null,t:"ヤマト、ポケットをさぐる。"},{w:"hero",t:"これ、さっきあいつが落としたやつ。",v:"01_0176"},{w:"elly",t:"それで、どうするの？",v:"01_0177"},{w:"hero",t:"今度は、こっちから手を出さない。",v:"01_0178"},{w:null,t:"ヤマト、オリーブを手のひらに乗せて、ひざの上に置く。"},{w:null,t:"フォルン、木から下りてくる。"},{w:"elly",t:"（小声で）ほら、やっぱり食べない。",v:"01_0181"},{w:"hero",t:"（小声で）しっ。",v:"01_0182"},{w:null,t:"フォルン、オリーブをくわえて、自分のしっぽの火の上に落とす。"},{w:null,t:"くわえ直して、ヤマトの手のひらの上で、かりっと食べる。"},{w:"hero",t:"食った。おれの手の上で、食った！",v:"01_0185"},{w:"elly",f:"surprised",t:"うそでしょ……。焦がしたのが好きだったの？",v:"01_0186"},{w:"elly",t:"わたし、三年間、クッキーだったんだけど！",v:"01_0187"},{w:"hero",t:"クッキーは焦がせねーもんな。",v:"01_0188"},{w:"elly",t:"焦がせるよ！　オーブンで！",v:"01_0189"},{w:null,t:"エリー、カバンの中のクッキーの箱を見る。"}];
GR_SC.g01_07=[{w:null,t:"ブーンと、羽の音。"},{w:"marco",t:"はあ、はあ……坂、長すぎっす……。",v:"01_0194"},{w:"nina",t:"いた。……なんで子どもが、狐にエサやってんのよ。",v:"01_0195"},{w:null,t:"フォルン、身がまえる。耳がうしろに倒れる。"},{w:"nina",t:"おい、おチビちゃん。その狐、よこしな！",v:"01_0197"},{w:"hero",t:"嫌だ！　おまえら、誰だ？",v:"01_0198"},{w:"nina",t:"あたしらは、ヴィクター一味。",v:"01_0199"},{w:"nina",t:"痛い目見る前に、さっさとよこしな。",v:"01_0200"},{w:"elly",t:"ヤマト、こいつら、テリオンをさらっていく人たちなの！",v:"01_0201"},{w:"elly",t:"村の子も、何びきも連れていかれたんだから！",v:"01_0202"},{w:"marco",t:"人聞き悪いっすね。おれら、ちゃんと売って——",v:"01_0203"},{w:null,t:"ニーナがふり向く。マルコ、口を閉じる。"},{w:"nina",t:"マルコ、しゃべってないで、囲みな！",v:"01_0205"},{w:null,t:"三機のドローンが、フォルンを三方から囲む。"},{w:"elly",t:"ヤマト！",v:"01_0207"},{w:null,t:"ヤマトの肩ごしに、フォルンの目が、網と二人組を見る。"},{w:"marco",t:"あー！　六枚目っす！",v:"01_0209"},{w:null,t:"ヤマト、立ち上がる。"},{w:"hero",t:"フォルンは、おれの友達だ！　ぜってー渡さねー！",v:"01_0211"},{w:"nina",t:"友達ねえ。その手のばんそうこう、狐にやられたんでしょ。",v:"01_0212"},{w:"nina",t:"しょうがないね。",v:"01_0213"},{w:"nina",t:"じゃあ、力ずくでもらうよ。",v:"01_0214"},{w:null,t:"オリーブの林の中から、がさがさと音。"},{w:"nina",t:"林に先回りさせといて正解だったね。やれ、クマッパ！",v:"01_0216"},{w:null,t:"フォルン、ヤマトの足もとから、すっと前に出る。二本のしっぽを立てて、クマッパをにらむ。"},{w:"hero",f:"smile",t:"いっしょにやってくれんのか？　よし、望むところだ！",v:"01_0218"},{w:"hero",t:"いっけー、フォルン！",v:"01_0219"},{w:null,t:"ヤマトとエリー、神殿の石の床まで下がる。"},{w:null,t:"神殿の柱のかげに、市場の子どもたちが三人、しゃがんで並ぶ。"}];
GR_SC.g01_09=[{w:null,t:"柱のかげから、市場の子どもたちが走ってくる。"},{w:"x",n:"子ども1",t:"ヴィクター一味に、勝っちゃった！",v:"01_0273"},{w:"x",n:"子ども3",t:"泥棒狐、すげー！",v:"01_0274"},{w:"x",n:"子ども2",t:"でも、オリーブは返してくんないよ。",v:"01_0275"},{w:null,t:"ニーナ、ひっくり返ったクマッパを抱き上げる。目を回したまま。"},{w:"nina",t:"よくやったよ。休みな。",v:"01_0277"},{w:null,t:"ニーナ、目を回したクマッパを、両腕でかかえ直す。"},{w:"nina",t:"覚えときな、おチビちゃん。",v:"01_0279"},{w:"nina",t:"ヴィクター一味に逆らって、ただで済んだやつはいないんだから。",v:"01_0280"},{w:"hero",t:"何回来たって、同じだ！　なあ、フォルン！",v:"01_0281"},{w:null,t:"フォルン、ヤマトの前を素通りして、マルコの前へ。しっぽを、ぴんと立てる。"},{w:"marco",t:"あ。",v:"01_0283"},{w:null,t:"ぽっ。マルコのお尻に、小さな火。"},{w:"marco",t:"あちちちちっ！　ニーナさーん！",v:"01_0285"},{w:"nina",t:"バカ、走るな！　置いてくよ！",v:"01_0286"},{w:null,t:"二人組、石段を転げるように逃げていく。子どもたちが、声をそろえて笑う。"},{w:null,t:"ヤマト、にやにやしながら、フォルンに手をのばす。"},{w:"hero",f:"smile",t:"やったな、フォルン！　ほら、ちょっとだけ——",v:"01_0289"},{w:null,t:"フォルン、喉の奥で、ぐるる。ヤマト、手を引っこめる。"},{w:"elly",t:"まだ、なでさせてはくれないみたいね。",v:"01_0291"},{w:"hero",t:"ちぇっ。いいよ、そのうちな。",v:"01_0292"},{w:null,t:"エリー、スーツケースを持ち上げる。"},{w:"elly",t:"さ、ホテル行こ。お姉ちゃん、ずっと待ってるから。",v:"01_0294"},{w:null,t:"二人、坂を下りはじめる。"},{w:null,t:"坂の下の道に、黒塗りのロボタクシーが止まっている。"},{w:null,t:"ヤマトは、うしろのフォルンばかり見ていて、気づかない。"}];
GR_SC.g01_10=[{w:null,t:"坂の下に止めた黒塗りのロボタクシー。"},{w:"marco",t:"ボスに、なんて言うっすか？",v:"01_0301"},{w:"marco",t:"狐、とれませんでしたって言うんすか？",v:"01_0302"},{w:null,t:"ニーナ、手首の画面に、ドローンが撮った写真を出す。少年の前に立って、しっぽを立てる狐。"},{w:"nina",t:"だれにもなつかない野良が、会ったばっかりの子どもをかばった。",v:"01_0304"},{w:"nina",t:"そんな話、聞いたことないよ。",v:"01_0305"},{w:"marco",t:"それ、まずいやつっすか。",v:"01_0306"},{w:"nina",t:"まずいどころか。ボスが一番ほしがる話だよ。",v:"01_0307"},{w:"nina",t:"これなら、手ぶらでも怒られないよ。",v:"01_0308"},{w:null,t:"ニーナ、送り先を選ぶ。"}];
GR_SC.g01_11=[{w:null,t:"その夜。坂の上の、小さなホテル。",v:"01_0312"},{w:null,t:"ホテルの一階のはしの、小さな部屋。"},{w:null,t:"ヤマト、戸を開ける。"},{w:"elly",t:"その図鑑、お姉ちゃんが置いといてくれたの。",v:"01_0315"},{w:"elly",t:"「日本の子なら、きっと読むから」って。",v:"01_0316"},{w:"hero",t:"お姉ちゃんって、さっき受付にいた人？",v:"01_0317"},{w:"elly",t:"そう、アナ。このホテル、お姉ちゃんが一人でやってるの。",v:"01_0318"},{w:null,t:"ヤマト、図鑑をひらく。"},{w:null,t:"ヤマト、色のぬってある国を、指で一つずつ、なぞっていく。ギリシャで、指が一度止まる。"},{w:"elly",t:"日本って、テリオン、いないんでしょ？",v:"01_0321"},{w:"hero",t:"いない。画面でしか見たことなかった。",v:"01_0322"},{w:"hero",t:"さわったのも、ガブッとやられたのも、今日が初めて。",v:"01_0323"},{w:null,t:"窓の外。ぶどう畑の柵の上に、フォルンが丸くなっている。"},{w:"elly",t:"見て。あの子、ここまでついてきてる。",v:"01_0325"},{w:"hero",t:"友達だからな。",v:"01_0326"},{w:"elly",t:"なでさせてもらえないのに？",v:"01_0327"},{w:"hero",f:"angry",t:"うっせ。",v:"01_0328"},{w:null,t:"エリー、笑って戸を閉める。"},{w:null,t:"スーツケースの中身を、ベッドにあける。"},{w:null,t:"ヤマト、戸を開けて、ろうかのエリーを呼びとめる。"},{w:"hero",t:"エリー、ちょっと見て。",v:"01_0332"},{w:"hero",t:"おれの画面に、知らないアプリが入ってる。",v:"01_0333"},{w:"elly",t:"知らないアプリ？　自分で入れたの、忘れてるだけじゃないの？",v:"01_0334"},{w:"hero",t:"入れてないって。こんなの、見たこともない。",v:"01_0335"},{w:"hero",t:"……じいちゃんかな。空港で、おれの画面いじってたし。",v:"01_0336"},{w:null,t:"アイコンを押しても、何も開かない。"},{w:null,t:"柵の上のフォルンの耳が、ヤマトではなく、手首の画面の方へ、ぴんと向く。"}];
GR_SC.g01_12=[{w:null,t:"窓のない暗い部屋。"},{w:null,t:"並びの中に、パンの棚の前で丸くなった、猫の子の写真。"},{w:null,t:"そのとなりが、一つだけ、空いている。"},{w:null,t:"空いたすき間に、写真が一枚、すっと入る。少年の前に立って、しっぽを立てる狐。"},{w:null,t:"写真から細い線がのびて、画面のすみの、名前の並びの「アレク」の横で止まる。"}];
GR_BT[1]={mid:[[{w:"nina",t:"クマッパ、つる！",v:"01_0225"},{w:"hero",t:"もっと近くだ、フォルン！",v:"01_0228"},{w:"elly",t:"毒！　あのつる、毒があるの！",v:"01_0230"},{w:"nina",t:"林の中は、クマッパの庭よ。",v:"01_0231"},{w:"hero",t:"負けんな、フォルン！　行け！　行けって！",v:"01_0232"}],[{w:"x",n:"子ども2",t:"当たった！",v:"01_0234"},{w:"hero",t:"逃げたぞ！　追え、フォルン！",v:"01_0236"},{w:"hero",t:"なにやってんだよ、行けって！",v:"01_0238"},{w:"elly",t:"ヤマト、だめ！　林の中、つるだらけだよ！",v:"01_0239"},{w:null,t:"ヤマトの口が、「行け」の形のまま止まる。"},{w:null,t:"ヤマト、口を閉じる。"},{w:"nina",t:"出てこないなら、待つだけさ。毒でじわじわ弱るからね。",v:"01_0244"},{w:null,t:"ヤマト、身を乗り出しかける。……やめる。"}],[{w:"hero",t:"まだだ、フォルン。そこにいろ。",v:"01_0249"},{w:"nina",t:"ちっ……。",v:"01_0251"},{w:null,t:"ニーナのゴーグルが、それを見る。"},{w:"nina",t:"クマッパ、毒が切れた！　もう一回かけてきな！",v:"01_0255"},{w:"nina",t:"そばまで行けば届く！",v:"01_0256"},{w:null,t:"ヤマトの目が、クマッパの手もとに行く。"},{w:null,t:"ヤマト、だまって、クマッパの手もとを指さす。"},{w:"nina",t:"なにしてんの、立ちな、クマッパ！",v:"01_0264"}]],post:[{w:null,t:"クマッパ、枯れ草の上で、あおむけにひっくり返る。目がぐるぐる。"},{w:null,t:"枯れ草に火が走りかける。フォルンがしっぽをひと振りする。"},{w:"elly",f:"smile",t:"勝った……。",v:"01_0268"},{w:"hero",f:"smile",t:"勝った！！　フォルン、勝ったぞ！",v:"01_0269"}]};
GR_EP[1]={"t": "テリオン・ワールド", "sc": [["g01_01", "語り", 0], ["g01_02", "オリーヴァ村・市場の坂（昼）", 0], ["g01_03", "坂道の追いかけっこ", 0], ["g01_04", "神殿のあとの丘", 0], ["g01_05", "同じ場所・女の子", 0], ["g01_06", "同じ場所・手のひらのオリーブ", 0], ["g01_07", "丘・ヴィクター", 0], ["g01_08", "勝負", 1], ["g01_09", "勝負のあと", 0], ["g01_10", "黒塗りのロボタクシーの中（夕方）", 0], ["g01_11", "坂の上のホテル・一階のはしの部屋（夜）", 0], ["g01_12", "窓のない部屋（夜）", 0]]};
GR_SC.g02_01=[{w:null,t:"オリーヴァ村。坂の上のホテルの朝。",v:"02_0044"},{w:null,t:"裏のぶどう畑。"},{w:null,t:"エリーが、パンとオリーブの皿を持ってのぞきこむ。"},{w:"elly",t:"ヤマト？　まさか、ひと晩じゅうここにいたの？",v:"02_0047"},{w:"hero",t:"見張ってたんだよ。",v:"02_0048"},{w:"hero",t:"ヴィクター一味が、また来るかもしれないだろ。",v:"02_0049"},{w:null,t:"フォルン、起き上がる。"},{w:"hero",t:"かっけえ……。",v:"02_0051"},{w:"elly",t:"毎朝やってるよ、あれ。",v:"02_0052"},{w:null,t:"二階の窓が、ばんと開く。"},{w:"ana",t:"エリー！　お客さんの朝ごはん！　日本の子の分も！",v:"02_0054"},{w:"elly",t:"はーい、お姉ちゃん！",v:"02_0055"},{w:null,t:"第2話　古代の競技場",v:"02_0057"}];
GR_SC.g02_02=[{w:null,t:"白い壁の小さな食堂。"},{w:"hero",t:"なあ、ここ、料理を運ぶロボットいないの？",v:"02_0064"},{w:"ana",t:"（台所から）聞こえてるからね！",v:"02_0065"},{w:"ana",t:"それと、ヤマト。おじいさんから、宿代がひと月分。",v:"02_0066"},{w:"hero",f:"surprised",t:"じいちゃんから！？　どこにいるって？",v:"02_0067"},{w:"ana",t:"振りこみだけ。ひと言も書いてなかった。",v:"02_0068"},{w:null,t:"アナ、空になった皿を二枚、ヤマトの手にのせて、もう次の客の方へ行っている。"},{w:null,t:"エリーの長い髪のかげから、うす茶色の、まんまるの毛玉が、そっと顔を出す。"},{w:"hero",f:"surprised",t:"うわっ！　なにそれ、いつからいたの！？",v:"02_0071"},{w:"elly",t:"ずっといたよ。ピリポン。こわがりなの。",v:"02_0072"},{w:"hero",t:"なあ、さわってもいい？",v:"02_0073"},{w:"elly",t:"だめ。寝てる時は、ぜったいだめ。びりってするから。",v:"02_0074"},{w:"hero",t:"さわらねーよ。",v:"02_0075"}];
GR_SC.g02_03=[{w:null,t:"古いソファと、壁の大きな画面。"},{w:null,t:"ヤマト、エリーを見る。"},{w:null,t:"指先が、毛にふれる。ピリポンの目が、ぱちっと開く。"},{w:null,t:"ヤマトの前髪が、まっすぐ上に立つ。"},{w:null,t:"エリーがもどってくる。ヤマトの頭と、ソファのうしろのふるえる毛玉を見る。"},{w:"elly",f:"serious",t:"……さわった？",v:"02_0083"},{w:"hero",t:"さわってない。",v:"02_0084"},{w:null,t:"ヤマトの前髪から、ぱちっと小さな火花。"},{w:"hero",f:"serious",t:"……ちょっとだけ。",v:"02_0086"},{w:null,t:"画面のお知らせが切りかわる。"},{w:"ana",t:"ヴィクター一味よ。パン屋の猫の子も、あいつら。",v:"02_0088"},{w:"hero",t:"取り返せねーの？",v:"02_0089"},{w:"ana",t:"持ち主がいても、「登録が古い」と言われたら、それまで。",v:"02_0090"},{w:"ana",t:"持ち主のいない子は、「いなくなっただけ」で終わり。",v:"02_0091"},{w:"hero",t:"じゃあ、フォルンは……。",v:"02_0092"},{w:"ana",t:"野良でしょ、あの狐。だれも探してくれないわね。",v:"02_0093"},{w:"hero",t:"だったら、おれが持ち主になる！　登録って、どこでやんの？",v:"02_0094"},{w:"ana",t:"持ち主の登録は、十五から。あんた、いくつ。",v:"02_0095"},{w:"hero",f:"serious",t:"……十一。",v:"02_0096"},{w:"ana",t:"それに、登録の板には、その子が自分で前足を置くの。",v:"02_0097"},{w:"ana",t:"持ち主は、テリオンの方が選ぶのよ。……見てなさい。",v:"02_0098"},{w:null,t:"アナ、手首の画面にふれる。"},{w:null,t:"アナ、光の板をフォルンの鼻先に差し出す。"},{w:null,t:"画面が切りかわる。"},{w:null,t:"画面「白い都テリオン大会　参加者募集　年れい不問」。"},{w:null,t:"画面のすみに、1秒だけ。"},{w:null,t:"ヤマト、がばっと画面の前へ。目は、「年れいにかかわらず」の字から動かない。"},{w:"hero",f:"surprised",t:"エリー、これ！　優勝したら、十一でも登録できるってことだろ！？",v:"02_0105"},{w:"elly",t:"……ほんとだ。でも、白い都って、ずっと東だよ。",v:"02_0106"},{w:null,t:"アナが、画面の横に重ねてある電子ペーパーのちらしを一枚ぬいて、ヤマトの手にねじこむ。"},{w:"ana",t:"持ってきな。……本気にするんじゃないよ。",v:"02_0108"},{w:"hero",t:"する！",v:"02_0109"},{w:"ana",t:"……でしょうね。",v:"02_0110"},{w:"elly",t:"とにかく、先におばあちゃんち。呼ばれてるの。",v:"02_0111"}];
GR_SC.g02_04=[{w:null,t:"村のいちばん上の丘。",v:"02_0114"},{w:null,t:"段々のオリーブ畑。"},{w:null,t:"畑のまん中に、石でかこんだ小さなため池。"},{w:null,t:"フォルン、池のふちへ。水に顔を近づける。"},{w:"elly",t:"水、きらいなの。",v:"02_0118"},{w:null,t:"池の向こう、丘の頂上に、白い大きな建物のあと。"},{w:"elly",t:"昔の研究所。おばあちゃん、前にあそこで働いてたの。",v:"02_0120"},{w:null,t:"フォルンの耳が、建物の方へ、ぴくっと動く。"}];
GR_SC.g02_05=[{w:null,t:"丘の向こうの、小さな石の家。"},{w:"elly",t:"おばあちゃーん！　つれてきたよ！",v:"02_0125"},{w:null,t:"おばあさん、ヤマトの顔をじっと見る。"},{w:"oba",t:"……両方、焦げてるね。",v:"02_0127"},{w:"hero",t:"こっちは狐で、こっちはピリポン。",v:"02_0128"},{w:null,t:"家の中。研究の記録の板と、データの箱が、どこにでも積んである。棚の写真の画面に、白い建物の前で笑う白衣の若い人が三人。"},{w:null,t:"ヤマト、くしゃくしゃのちらしをテーブルに置く。"},{w:"hero",t:"優勝して登録すれば、フォルンも探してもらえるんだろ。",v:"02_0131"},{w:null,t:"おばあさん、ちらしの「年れいにかかわらず」の字を見る。それから、ヤマトの手を見る。"},{w:"oba",t:"……エリー。一緒に行っておいで。",v:"02_0133"},{w:"elly",t:"うん。パン屋さんの猫の子も、まだ帰ってきてないもん。",v:"02_0134"},{w:"oba",t:"村にじっとしてても、あの狐は守れないよ。",v:"02_0135"},{w:null,t:"窓の外。庭の洗濯物の上を、黒いドローンが一台、ゆっくり横切る。"},{w:"oba",t:"出るのは、あしたの夜。森の道なら、あれに見えない。",v:"02_0137"},{w:"oba",t:"あしたの昼は、競技場の手伝いに行っておいで。",v:"02_0138"},{w:"oba",t:"ドローンのあとは、車でホテルに来るからね。",v:"02_0139"},{w:null,t:"おばあさん、手首の画面を指で二回たたく。"},{w:"oba",t:"今、あんたの画面に送っといたよ。消すんじゃないよ。",v:"02_0141"},{w:"elly",t:"なにこれ？　ファイルが一個だけ。",v:"02_0142"},{w:"oba",t:"古いもんだよ。開いても、あんたには分かんないよ。",v:"02_0143"},{w:null,t:"ヤマトの手首の画面が、ひとりでに光る。"},{w:null,t:"いすから立ち上がりかけていたおばあさんが、そのまま止まる。"},{w:null,t:"アイコンの中で、針が一本だけ、かちりと動く。"},{w:"hero",t:"じいちゃんが勝手に入れたアプリ。押しても開かないんです。",v:"02_0147"},{w:null,t:"おばあさん、座り直す。いつもの顔。"},{w:"oba",t:"……古い形の時計だね。消さずに、大事にしな。",v:"02_0149"},{w:null,t:"窓の外。庭のオリーブの根もとで、フォルンが、しっぽの火で実を焼いている。"}];
GR_SC.g02_06=[{w:null,t:"同じころ、遠くの丘。",v:"02_0153"},{w:null,t:"丘の上。若い男が一人、古い小さな望遠鏡で星を見ている。顔は半分しか見えない。"},{w:null,t:"男の手首の画面が鳴る。マークも顔も名前も出ない。"},{w:"x",n:"画面の声",t:"アレク、急ぎの仕事だ。",v:"02_0156"},{w:"x",n:"画面の声",t:"オリーヴァ村の丘に、狐が一匹いる。",v:"02_0158"},{w:"x",n:"画面の声",t:"施設へ送る前の夜に逃げた子だ。運んできてくれ。",v:"02_0159"},{w:null,t:"画面のすみに、少年の前に立って、しっぽを立てる狐の写真。"},{w:"alek",t:"運ぶのは、狐だけですか。",v:"02_0161"},{w:"x",n:"画面の声",t:"狐だけだ。払いは、いつもの研究費に上乗せしておく。",v:"02_0162"},{w:null,t:"アレク、望遠鏡から目を離さないまま、写真を開かずに、画面を指で消す。"},{w:null,t:"それから、ゆっくり望遠鏡を下ろす。"}];
GR_SC.g02_07=[{w:null,t:"次の日。村の外れの、三千年前の競技場。",v:"02_0170"},{w:null,t:"オリーブの林を抜けると、石を積んだ古い入口のアーチ。"},{w:null,t:"白い案内のロボットが、小さな旗を立てて、観光客の一団を連れて歩いている。"},{w:null,t:"その横に、リュックのヤマト。"},{w:null,t:"案内のロボットが、一団を土手の上の日かげへ連れていく。"},{w:"hero",t:"エリー、かけっこしようぜ。向こうの端まで。",v:"02_0175"},{w:"elly",t:"えー。わたし、仕事中なんだけど。",v:"02_0176"},{w:"hero",t:"あ、負けるのがこわいんだ。",v:"02_0177"},{w:"elly",t:"……いいよ。そこまで言うなら、走ってあげる。",v:"02_0178"},{w:null,t:"エリー、スタートの線に並ぶ。"},{w:"elly",t:"よーい……ドン！",v:"02_0180"},{w:null,t:"二人、同時にとび出す。"},{w:null,t:"その横を、紺色のかげが、すっと追いぬいていく。"},{w:"hero",t:"（息を切らして）……一番、もってかれた。",v:"02_0185"}];
GR_SC.g02_08=[{w:null,t:"正午。",v:"02_0188"},{w:null,t:"枯れかけた草の土手。"},{w:null,t:"エリーの手首の画面が、ぴこんと鳴る。"},{w:"elly",f:"serious",t:"……ヴィクター一味が、ホテルに来たって。",v:"02_0191"},{w:"hero",t:"ほんとに来たんだ。……アナさん、だいじょうぶ？",v:"02_0192"},{w:null,t:"エリー、すぐに「だいじょうぶ？」と打つ。"},{w:null,t:"ヤマト、手首の画面を見る。"},{w:"hero",t:"きのうは、押しても開かなかったのに。",v:"02_0195"},{w:"elly",t:"今度は、開くんじゃない？",v:"02_0196"},{w:null,t:"ヤマト、アイコンを、指でとんと押す。"},{w:null,t:"手首の画面から、うすい光が宙に広がって、地図の形になる。"},{w:null,t:"地図の上に、小さな光の印が、四つ。"},{w:"hero",t:"うわ、うわ、なにこれ！",v:"02_0200"},{w:"hero",f:"surprised",t:"じいちゃんのアプリ、こんなことできたの！？",v:"02_0201"},{w:null,t:"印の一つは、今いる場所と重なっている。"},{w:null,t:"もう一つは、村のいちばん上の丘。"},{w:"elly",t:"あ、そこ、おばあちゃんが前に働いてた所の近くだよ。",v:"02_0204"},{w:null,t:"残りの二つは、地図のずっとはし。"},{w:"hero",t:"この真下って……下に何かあんの？",v:"02_0206"},{w:null,t:"ヤマト、土手のすそを見る。"},{w:null,t:"ヤマト、看板には目もくれずに、柵の前まで行く。"},{w:"hero",f:"serious",t:"……ちょっと、中を見てくるだけ。",v:"02_0209"},{w:"elly",t:"ちょっとって、どれくらい？",v:"02_0210"},{w:"hero",t:"入口から、見えるとこまで。",v:"02_0211"},{w:"elly",t:"中、まっ暗だよ。",v:"02_0212"},{w:"hero",t:"じゃあ、見えるとこまで、全部。",v:"02_0213"},{w:null,t:"フォルンが、先に柵の下をくぐる。"}];
GR_SC.g02_09=[{w:null,t:"競技場の、真下。",v:"02_0217"},{w:null,t:"ひんやりした石の通路。フォルンのしっぽの火が明かりになる。"},{w:"elly",t:"ヤマト、もう、見えるとこ、過ぎてるよ。",v:"02_0219"},{w:"hero",t:"フォルンが明るいから、ずっと見えてる。",v:"02_0220"},{w:null,t:"つきあたりに、大きな石の扉。"},{w:null,t:"扉のふちに、細かい文字がびっしり。"},{w:"hero",f:"serious",t:"……でっか。",v:"02_0223"},{w:"elly",f:"serious",t:"……これ、古いギリシャの字だ。",v:"02_0224"},{w:null,t:"エリー、文字を指でなぞって、声に出して読む。"},{w:"elly",f:"surprised",t:"えっとね……ここで寝てる子、起こさないでね、だって。",v:"02_0226"},{w:null,t:"エリーの声が、通路にひびいて、消える。"},{w:null,t:"……足の下の、ずっと深い所から、低い音が一つだけ返ってくる。"},{w:null,t:"天井から、砂がひとすじ落ちる。"},{w:null,t:"ヤマトは角を見上げている。"},{w:"elly",t:"……ヤマト。なんだか、いやな感じがする。今日は、もう帰ろ。",v:"02_0235"},{w:"hero",f:"serious",t:"……うん。",v:"02_0236"}];
GR_BT[2]={mid:[[{w:"alek",t:"立ち入り禁止って、入口の看板に書いてあっただろ。",v:"02_0242"},{w:"hero",f:"serious",t:"……読んでない。",v:"02_0243"},{w:"alek",t:"×の絵ぐらい見ろよ。",v:"02_0244"},{w:"elly",t:"わたし、ぜんぶ読めたよ。奥の扉のも。",v:"02_0245"},{w:null,t:"アレク、だまる。"},{w:null,t:"アレクの目が、ヤマトの足もとのフォルンに止まる。"},{w:"alek",t:"その狐、置いていけ。運ぶ仕事を受けてんだよ。",v:"02_0248"},{w:"alek",t:"施設に送られる前の夜に逃げた子だって聞いてる。",v:"02_0249"},{w:"elly",t:"フォルンは、わたしが知ってるだけでも、三年この丘にいるよ。",v:"02_0250"},{w:"elly",t:"逃げた子なんかじゃない。",v:"02_0251"},{w:null,t:"アレクの目が、一瞬だけエリーに止まる。"},{w:"hero",t:"フォルンは、だれのでもねーよ。お前のでも、おれのでもない。",v:"02_0253"},{w:"alek",t:"だれのでもないなら、おれが運んでも文句はないだろ。",v:"02_0254"},{w:null,t:"アレク、手首の画面を指で一回たたく。"}],[{w:"elly",t:"そのドローン、ヴィクター一味のだよ！",v:"02_0256"},{w:"elly",t:"おとといの黒い車と、同じマークだもん。",v:"02_0257"},{w:null,t:"アレク、ドローンの胴の輪を見上げる。ほんの一瞬、目が止まる。"},{w:null,t:"アレク、目をもどす。"},{w:"alek",t:"こっちは、仕事で来てんだよ。下がってろ。",v:"02_0260"},{w:"alek",t:"そこにいたら、ぬれるぞ。",v:"02_0261"},{w:null,t:"ヤマトとエリー、通路の出口の石の壁ぎわまで下がる。"},{w:"elly",t:"ピリポン！　もどって！",v:"02_0264"},{w:null,t:"エリー、一歩出かける。"}],[{w:"hero",t:"すぐ終わらせるから。",v:"02_0267"},{w:"hero",t:"フォルン、水路に近よるな！",v:"02_0272"},{w:"hero",t:"右のはしからだ！",v:"02_0273"},{w:null,t:"アレク、画面を指ではじく。"},{w:"hero",t:"なんで、あんな遠くまで……！",v:"02_0278"},{w:"alek",t:"水路の中だぞ。",v:"02_0279"}],[{w:"hero",t:"遠くじゃだめだ！　近くで撃て、フォルン！",v:"02_0282"},{w:null,t:"ヤマト、何か言いかけて、口を閉じる。"},{w:null,t:"アレク、画面に指をのせる。"},{w:"elly",t:"ピリポン！",v:"02_0291"},{w:null,t:"エリーが飛び出しかける。"},{w:"hero",t:"出るな！　水が来る！",v:"02_0294"},{w:null,t:"アレク、画面から指をはなす。"},{w:"alek",t:"……撃つな。",v:"02_0296"},{w:null,t:"ヤマト、エリーの腕をつかんだまま、フォルンを見る。"},{w:null,t:"アレク、それを見ている。"},{w:"alek",t:"……終わらせるぞ。",v:"02_0305"},{w:"hero",t:"フォルン！",v:"02_0309"}]],post:[{w:null,t:"ヤマト、走る。"},{w:null,t:"アレクの手首の画面が、ぶるっとふるえる。"},{w:"alek",t:"はい。狐は、網の中です。",v:"02_0313"},{w:"alek",t:"それと、女の子が、地下の古い字を読みました。",v:"02_0314"},{w:null,t:"返事が来ない。"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……狐は、まだ運ぶな。",v:"02_0316"},{w:"x",n:"画面の声（アレクの耳の中）",t:"今夜、その娘と一緒にだ。",v:"02_0317"},{w:null,t:"アレクの、画面にのせていた指が止まる。"},{w:null,t:"通話が切れる。"},{w:null,t:"アレク、画面を一回たたく。"},{w:"hero",f:"serious",t:"……なんで、やめんだよ。",v:"02_0321"},{w:"alek",t:"今日は、ここまでだ。",v:"02_0322"},{w:null,t:"アレク、水路のふちを軽くたたく。"},{w:"elly",f:"serious",t:"……ありがとう、フォルン。",v:"02_0327"}]};
GR_EP[2]={"t": "古代の競技場", "sc": [["g02_01", "ホテルの裏・ぶどう畑のはし（朝）", 0], ["g02_02", "ホテルの食堂（朝）", 0], ["g02_03", "ロビー（朝）", 0], ["g02_04", "丘の上・ため池と研究所あと（昼）", 0], ["g02_05", "おばあさんの家（昼）", 0], ["g02_06", "どこかの丘（夜）", 0], ["g02_07", "古代の競技場（次の日・昼前）", 0], ["g02_08", "土手の上（正午）", 0], ["g02_09", "地下の扉", 0], ["g02_10", "通路の出口・土手のすその空き地", 1]]};
GR_SC.g03_01=[{w:null,t:"同じ日の夕方。村の裏の森。",v:"03_0032"},{w:null,t:"小川べりの平たい岩に、背の高い若い男が一人、ひざを立てて座っている。"},{w:null,t:"小川の中を、頭に卵のからをかぶった緑のワニの子が、ぐるぐる回って泳いでいる。"},{w:null,t:"ワニの子が、岸の白っぽい乾いた石の上へ上がる。"},{w:null,t:"男、かばんから、やわらかく煮た魚の包みを出す。"},{w:null,t:"手首の画面が、ぶるっとふるえる。"},{w:"x",n:"受付の女の声",t:"出資元の受付です。おつなぎします。",v:"03_0038"},{w:"x",n:"画面の声",t:"アレク。日が落ちたら、狐と娘だ。",v:"03_0039"},{w:"x",n:"画面の声",t:"狐がなついている男の子も、一緒にな。",v:"03_0040"},{w:"alek",t:"男の子も、ですか？",v:"03_0041"},{w:"alek",t:"おれが受けたのは、狐を一匹運ぶ仕事だけです。",v:"03_0042"},{w:"alek",t:"子どもまで連れていく理由は、何なんですか。",v:"03_0043"},{w:"x",n:"画面の声",t:"理由は、お前が知らなくていい。言われたとおりにやれ。",v:"03_0044"},{w:"alek",t:"子どもを連れていったら、もう運びの仕事じゃないですよ。",v:"03_0045"},{w:"x",n:"画面の声",t:"……忘れるなよ。",v:"03_0046"},{w:"x",n:"画面の声",t:"そのワニに入れたチップは、居場所を知らせるだけじゃない。",v:"03_0048"},{w:"x",n:"画面の声",t:"こっちで、いつでも止められるんだからな。",v:"03_0049"},{w:null,t:"通話が切れる。"},{w:null,t:"ワニの子が、男のひざに、ぬれた頭をのせる。"},{w:null,t:"男、ワニの子の頭に手を置く。"},{w:null,t:"第3話　夜の森",v:"03_0055"}];
GR_SC.g03_02=[{w:null,t:"その夜。",v:"03_0061"},{w:null,t:"ホテルの裏口の戸が、そっと開く。"},{w:"hero",t:"……エリー、その手に持ってる、でっかいの、なに？",v:"03_0063"},{w:"elly",t:"虫よけだよ。",v:"03_0064"},{w:"elly",t:"夜の森って、虫がいっぱいいるんだもん。",v:"03_0065"},{w:"elly",t:"これがないと、顔じゅう刺されちゃうよ。",v:"03_0066"},{w:"hero",t:"でっか。そんなにあったら、一年分くらいあるだろ。",v:"03_0067"},{w:"elly",t:"ううん、これで一晩分だよ。この森の虫、すごいんだから。",v:"03_0068"},{w:null,t:"エリー、戸のすきまに、うすい電子メモをはさむ。"},{w:"hero",t:"「ちょっと出かけます」って書いて、白い都まで行くの？",v:"03_0070"},{w:"hero",t:"ちょっとどころじゃないだろ。",v:"03_0071"},{w:"elly",t:"いいの。",v:"03_0072"},{w:"elly",t:"お姉ちゃん、長い字は読まないの。",v:"03_0073"},{w:"elly",t:"短く書いた方が、ちゃんと読んでくれるんだもん。",v:"03_0074"},{w:null,t:"塀の上から、フォルンが、とん、と下りてくる。"}];
GR_SC.g03_03=[{w:null,t:"ぶどう畑を抜けた先の、暗い森。"},{w:null,t:"かえるの声。"},{w:"elly",t:"この道なら、空のドローンから見えないんだって。",v:"03_0080"},{w:"hero",t:"ドローンって、まだ村の上を回ってんの？",v:"03_0081"},{w:"hero",t:"もう、あきらめたかと思ってた。",v:"03_0082"},{w:"elly",t:"ううん、まだいるよ。夕方も、三台いたもん。",v:"03_0083"},{w:null,t:"光る板のまわりに、羽虫がわっと集まる。"},{w:"hero",t:"うわ、うわ、来んな！　虫、こっち来んなって！",v:"03_0085"},{w:null,t:"エリー、スプレーをかまえて、ぷしゅー。"},{w:"hero",t:"おれにかけんなよ！　目にしみるだろ！",v:"03_0087"},{w:"elly",t:"だって、ヤマトの頭に、虫がいっぱいついてたんだもん。",v:"03_0088"},{w:null,t:"フォルンだけは、森の奥をじっと見ている。耳が前を向いている。"},{w:null,t:"小川べりの平たい岩。"},{w:null,t:"ヤマト、せきこみながら顔を上げて、止まる。"},{w:"hero",f:"serious",t:"……また、お前かよ。",v:"03_0092"},{w:"hero",t:"いつから、ここにいたんだよ。",v:"03_0093"},{w:"alek",t:"夕方から、ずっとここで待ってたんだよ。",v:"03_0094"},{w:"alek",t:"お前らがこの森に来るのは分かってたからな。",v:"03_0095"},{w:"elly",t:"なんで、わたしたちがこの道を通るって分かったの？",v:"03_0096"},{w:"elly",t:"だれにも言ってないのに。",v:"03_0097"},{w:"alek",t:"昼の道は、ドローンだらけだろ。",v:"03_0098"},{w:"alek",t:"狐連れて見られずに出るなら、夜のこの森しかねえよ。",v:"03_0099"},{w:null,t:"男、望遠鏡から目をはなさない。"},{w:"hero",f:"serious",t:"……さっきから、望遠鏡で何を見てんの？",v:"03_0101"},{w:"alek",t:"星、見てんだよ。今夜はよく晴れてるからな。",v:"03_0102"},{w:"hero",t:"星って、どの星だよ。いっぱいあるじゃん。",v:"03_0103"},{w:"alek",t:"どの星かなんて、お前に教える必要ないだろ。",v:"03_0104"},{w:"hero",t:"なんだよ、それ。教えてくれたっていいだろ！",v:"03_0105"},{w:null,t:"男、望遠鏡の筒をていねいにちぢめて、かばんにもどす。"}];
GR_SC.g03_04=[{w:"alek",t:"その狐、こっちに渡してくれ。おれは、そのために待ってたんだ。",v:"03_0109"},{w:"hero",t:"やだね。フォルンは、だれにも渡さないって決めてんだよ。",v:"03_0110"},{w:"hero",t:"だいたい、昼は網まで出して、なんで帰ったんだよ。",v:"03_0111"},{w:"alek",t:"まだ運ぶなって言われたんだよ。",v:"03_0112"},{w:"alek",t:"今夜、お前らも一緒に連れてこいってな。二人ともだ。",v:"03_0113"},{w:"hero",f:"serious",t:"……は？　おれらも？",v:"03_0114"},{w:"hero",t:"なんで、おれらまで行かなきゃいけないんだよ。",v:"03_0115"},{w:"elly",t:"そうだよ。わたしたちまで連れていって、どうするつもりなの？",v:"03_0116"},{w:"alek",t:"理由なんか、おれも知らないよ。",v:"03_0117"},{w:"alek",t:"仕事の相手に、そう言われただけだ。",v:"03_0118"},{w:"hero",t:"仕事の相手って、ヴィクター一味だろ。",v:"03_0119"},{w:"hero",t:"フォルンをさらって、どこかに売るつもりなんだろ。",v:"03_0120"},{w:"alek",t:"相手の顔なんか、見たこともないよ。画面の声だけだ。",v:"03_0121"},{w:"alek",t:"おれは、運ぶ仕事を受けただけなんだよ。",v:"03_0122"},{w:"hero",t:"顔を知らなくても、手伝ってんなら同じじゃん！",v:"03_0123"},{w:"alek",t:"うるせえな。こっちにも、断れないわけがあるんだよ。",v:"03_0124"},{w:"elly",t:"その子も、そのお仕事してるの？",v:"03_0125"},{w:"alek",t:"こいつは関係ねえよ。仕事の話に、こいつを入れんな。",v:"03_0126"},{w:"hero",t:"関係なくねーだろ。いつも一緒にいるんだから、お前の相棒だろ。",v:"03_0127"},{w:"alek",t:"もう話はいいだろ。",v:"03_0128"},{w:"alek",t:"起きてる狐に網を出したって、どうせ燃やすんだろ？",v:"03_0129"},{w:"alek",t:"前のやつらが、それでしくじったって聞いてるよ。",v:"03_0130"},{w:"alek",t:"だから、勝負で決めようぜ。",v:"03_0131"},{w:"alek",t:"おれが勝ったら、狐とお前らを連れていく。",v:"03_0132"},{w:"hero",f:"smile",t:"じゃあ、おれが勝ったら、どうすんだよ。",v:"03_0133"},{w:"alek",t:"おれは黙って帰るよ。",v:"03_0134"},{w:"alek",t:"仕事の相手には「森にはだれも来なかった」って言っとく。",v:"03_0135"},{w:null,t:"男の目が、一瞬だけ、ヤマトの顔に止まる。それから、はなれる。"},{w:"elly",t:"ヤマト、だめだよ。",v:"03_0137"},{w:"elly",t:"この人に仕事をさせてるの、ヴィクター一味なんだよ。",v:"03_0138"},{w:"elly",t:"何をしてくるか、分からないもん。",v:"03_0139"},{w:"hero",t:"逃げたって、どうせまた追っかけてくるんだろ。",v:"03_0140"},{w:"hero",t:"だったら、ここで勝って終わらせる。",v:"03_0141"},{w:null,t:"エリー、しゃがんで、ワニの子の頭の卵のからを見る。"},{w:"elly",t:"（ワニの子に）こんばんは、タマゴちゃん。頭のから、かわいいね。",v:"03_0143"},{w:"alek",t:"こいつはタマゴじゃねえよ。ちゃんと名前があるんだ。",v:"03_0144"},{w:"elly",t:"じゃあ、なんていう名前なの？　教えてよ。",v:"03_0145"},{w:"alek",t:"名前は、あとで教えてやるよ。お前らが、おれに勝てたらな。",v:"03_0146"}];
GR_SC.g03_05=[{w:null,t:"ヤマト、光る板を手前の切り株の上に置く。"},{w:null,t:"右を、小川が奥から手前へまっすぐ流れている。"},{w:null,t:"男、ワニの子を小川に放す。"},{w:"hero",t:"昼の分、返すからな。",v:"03_0152"},{w:"elly",f:"serious",t:"……うん。",v:"03_0153"},{w:null,t:"エリーは、小川を見ている。"},{w:null,t:"エリーの肩のピリポンが、エリーの髪のかげで、ぶるぶる震えている。"},{w:"elly",t:"ピリポン。こわかったら、そこの石のかげにいて。",v:"03_0156"},{w:"elly",t:"それだけでいいから。",v:"03_0157"},{w:null,t:"ピリポン、エリーの腕をつたって、草の上に、ぽてっと下りる。"},{w:"alek",t:"二体で来いよ。",v:"03_0159"},{w:"alek",t:"水のそばのこいつに、一体ずつじゃ勝負にならないからな。",v:"03_0160"},{w:null,t:"フォルン、大きな木の根もとへ歩いていく。しっぽの火が、ぼっとふくらむ。"},{w:"alek",t:"準備できたんなら、いつでも来いよ。",v:"03_0162"}];
GR_SC.g03_07=[{w:null,t:"ピリポン、固まっている。"},{w:"elly",t:"ピリポン、すごいよ……！",v:"03_0236"},{w:null,t:"アレク、ひっくり返ったワニの子のそばにひざをつく。曲がったあごに、手をそえる。"},{w:null,t:"耳のうしろのうろこのすき間から、小さなチップが、ころっと落ちる。"},{w:"elly",t:"その黒いの、なに？",v:"03_0239"},{w:"alek",t:"仕事の相手に渡されたチップだよ。",v:"03_0240"},{w:"alek",t:"居場所を知らせるためだって言われて、入れてたんだ。",v:"03_0241"},{w:"elly",t:"そのマーク、昼のドローンと同じ……。",v:"03_0242"},{w:"alek",t:"ああ。",v:"03_0243"},{w:"alek",t:"しかも、向こうの気分しだいで、こいつを止められるんだってさ。",v:"03_0244"},{w:"elly",t:"止められるって……どういうこと？",v:"03_0245"},{w:"alek",t:"体が固まって、動けなくなるんだよ。",v:"03_0246"},{w:"hero",t:"それ、割れてんじゃん。",v:"03_0247"},{w:"alek",t:"さっきの雷だろうな。",v:"03_0248"},{w:null,t:"乾いた草の上で、ワニの子の背中のうろこが、白っぽくかわいていく。"},{w:null,t:"ヤマト、小川へ走る。"},{w:"alek",t:"お前、何してんだよ。",v:"03_0251"},{w:"hero",t:"かわいてんじゃん、こいつ。",v:"03_0252"},{w:null,t:"アレク、それを見ている。割れたチップをにぎった手が、ひざの上で止まっている。"},{w:null,t:"エリーも、ピリポンを肩にのせて、両手で水をすくいに走る。"},{w:null,t:"三回目の水がかかった時、ワニの子が目を開ける。"},{w:null,t:"アレクの手首の画面が、ぶるっとふるえる。"},{w:"x",n:"画面の声（アレクの耳の中）",t:"アレク。狐と子どもは、どうした。",v:"03_0257"},{w:null,t:"アレク、ヤマトを見る。"},{w:"alek",t:"狐も子どもも、見つかりませんでした。",v:"03_0259"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……夕方から、ずっとか。",v:"03_0260"},{w:"alek",t:"はい。森には、だれも来ませんでした。",v:"03_0261"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……ワニのチップの反応が、消えたぞ。",v:"03_0262"},{w:"alek",t:"さっき、ワニが川で暴れて、取れてこわれたみたいです。",v:"03_0263"},{w:"x",n:"画面の声（アレクの耳の中）",t:"……そうか。",v:"03_0264"},{w:null,t:"通話が切れる。"},{w:"elly",t:"今の、仕事の相手の人？　なんて言ってたの？",v:"03_0266"},{w:"alek",t:"チップの反応が消えたってさ。こわれたって言っといたよ。",v:"03_0267"},{w:null,t:"アレク、手首の画面を外す。"},{w:null,t:"止まる。もどってくる。"},{w:null,t:"それから、小川へ投げる。"},{w:"hero",t:"え、捨てちゃっていいの？　仕事に使うやつだろ。",v:"03_0271"},{w:"alek",t:"もう、この仕事はやめだ。",v:"03_0272"},{w:"alek",t:"狐一匹のはずが、子どもまでだぞ。ただの人さらいじゃねえか。",v:"03_0273"},{w:"alek",t:"お前らの手首も、居場所を金で買われるぞ。出せよ。",v:"03_0274"},{w:null,t:"アレク、ヤマトの手首をつかんで、画面の設定を指で次々に開く。"},{w:"alek",t:"画面のAIに話したことも、もう会社に行かねえ。",v:"03_0276"},{w:null,t:"ヤマトの画面のすみの、小さな話し相手のマークが、すっと消える。"},{w:"alek",t:"毎月もらえるお金も止まる。名前のない手首には来ねえんだ。",v:"03_0278"},{w:"hero",f:"serious",t:"……じゃあ、おれら、お金ゼロ？",v:"03_0279"},{w:"alek",t:"旅のあいだはな。",v:"03_0280"},{w:null,t:"エリーも、手首を出す。"},{w:"elly",t:"お姉ちゃんから、電話が十二回も来てる。",v:"03_0282"},{w:"elly",f:"serious",t:"……これで、お姉ちゃんにはかけられる？",v:"03_0283"},{w:"alek",t:"かけるのも受けるのもできるよ。",v:"03_0284"},{w:"alek",t:"向こうに場所が出なくなるだけだ。",v:"03_0285"},{w:"hero",f:"surprised",t:"おれのじいちゃんのアプリ、消えてないよな！？",v:"03_0286"},{w:"alek",t:"消してないって。さわってもいないよ。",v:"03_0287"},{w:null,t:"アレク、ぐったりしたワニの子を抱き上げる。"},{w:"elly",t:"その子、休ませなきゃ。お水も、いっぱいいるよ。",v:"03_0289"},{w:"elly",f:"serious",t:"……うち、すぐそこだから。",v:"03_0290"},{w:"hero",t:"え、もどんの？　せっかく出てきたのに。",v:"03_0291"},{w:"elly",f:"surprised",t:"でも、この子、このままじゃ歩けないよ。",v:"03_0292"},{w:"elly",t:"お水につけて、休ませてあげないと。",v:"03_0293"},{w:"hero",f:"serious",t:"……わかったよ。今夜は、もどる。",v:"03_0294"},{w:null,t:"アレク、何も言わない。でも、エリーが歩きだすと、そのあとについてくる。"}];
GR_SC.g03_08=[{w:null,t:"夜ふけ。坂の上のホテル。",v:"03_0298"},{w:null,t:"玄関の明かりだけが、ついている。"},{w:null,t:"門の内側に、アナが、腕を組んで立っている。"},{w:"ana",t:"……こんな夜中に、二人とも、どこに行ってたの？",v:"03_0301"},{w:"elly",f:"surprised",t:"……えっと、ちょっと、そこまで。",v:"03_0302"},{w:"ana",t:"ちょっと出かけただけで、そんなに泥だらけになるの？",v:"03_0303"},{w:"ana",t:"電話、十二回もしたんだけど。",v:"03_0304"},{w:"elly",t:"知ってる。ちゃんと数えたもん。",v:"03_0305"},{w:"ana",t:"数えたなら、出なさい。……で、あの人は、だれなの？",v:"03_0306"},{w:null,t:"門の外の、石の塀のそば。"},{w:"alek",t:"（ヤマトの手首を見て）お前のその手首の画面さ。",v:"03_0308"},{w:"alek",t:"昼に競技場の土手で、地図みたいな光を出してただろ。",v:"03_0309"},{w:null,t:"ヤマト、手首の画面を手で押さえる。"},{w:"hero",f:"serious",t:"……え、あれ、見てたのかよ。",v:"03_0311"},{w:"alek",t:"ああ。土手の上が光ったから、望遠鏡で見てたんだよ。",v:"03_0312"},{w:null,t:"アレクの目が、ヤマトのリュックの横ポケットに行く。"},{w:"alek",t:"白い都まで行くつもりなのか？",v:"03_0314"},{w:"hero",t:"行くよ。地図で見たら、まっすぐ行けば、すぐだし。",v:"03_0315"},{w:"alek",t:"まっすぐ行ったら、海に落ちるぞ。",v:"03_0316"},{w:"elly",t:"ほらね。光の地図、ちゃんと見ないからだよ。",v:"03_0317"},{w:"alek",t:"道なら、おれが知ってるよ。ヴィクターの車が通らない道もな。",v:"03_0318"},{w:"alek",t:"……案内してやろうか？",v:"03_0319"},{w:"hero",f:"serious",t:"……でも、おれら、お金ないよ。",v:"03_0320"},{w:"alek",t:"金を取るなんて、言ってないだろ。",v:"03_0321"},{w:"elly",t:"でも、ただじゃ悪いよ。クッキー、一枚なら出せるよ。",v:"03_0322"},{w:"alek",t:"だから、いらないって。",v:"03_0323"},{w:"hero",t:"じゃあ、オリーブ、五つでどう？",v:"03_0324"},{w:null,t:"フォルンの耳が、ぴくっとヤマトの方へ向く。"},{w:"alek",t:"それ、その狐のオリーブだろ。",v:"03_0326"},{w:"hero",f:"serious",t:"……じゃあ、四つ。",v:"03_0327"},{w:null,t:"フォルン、ヤマトのリュックの前に、どすっと座りこむ。"},{w:"hero",f:"serious",t:"……三つ。",v:"03_0329"},{w:null,t:"フォルン、そっぽを向いたまま、しっぽでヤマトのすねを、ぺしっとたたく。"},{w:null,t:"エリー、塀の下にしゃがむ。"},{w:"elly",f:"smile",t:"（ワニの子に）約束だよ。わたしたち、勝ったんだから、名前、教えて。",v:"03_0332"},{w:"alek",t:"こいつの名前は、クロッコだ。",v:"03_0333"},{w:"elly",t:"じゃあ、クロッコちゃんだね。",v:"03_0335"},{w:"alek",t:"「ちゃん」は、つけなくていいって。",v:"03_0336"},{w:"hero",f:"serious",t:"……案内、たのむよ。……おれ、ヤマト。",v:"03_0337"},{w:"alek",t:"おれは、アレク。",v:"03_0338"},{w:"elly",t:"お姉ちゃん、この人、今夜泊めてあげて！",v:"03_0339"},{w:"elly",t:"この子を、休ませなきゃいけないの。",v:"03_0340"},{w:null,t:"アナ、電子メモを持ったまま、アレクを上から下まで見る。"},{w:"ana",t:"……で、一泊いくら払えるの？",v:"03_0342"},{w:null,t:"アレク、何もついていない自分の手首を見る。"}];
GR_BT[3]={mid:[[{w:"alek",t:"行け。水だ。",v:"03_0168"},{w:"hero",t:"フォルン、撃ち返せ！",v:"03_0172"},{w:"alek",t:"もぐれ。もう一回、水だ。",v:"03_0174"},{w:"hero",t:"出んな！　そこにいろ！　そこが一番、火がでかいんだから！",v:"03_0176"},{w:null,t:"ヤマト、その耳を見る。"},{w:"alek",t:"木の下にいても、水は届くぞ。……手前に回れ。",v:"03_0179"}],[{w:"elly",t:"ピリポン！",v:"03_0182"},{w:null,t:"アレクの目が、はじめてヤマトからはなれる。"},{w:"alek",t:"下がれ！　そいつの電気から離れろ。",v:"03_0188"},{w:"elly",f:"surprised",t:"ヤマト、このままじゃ、フォルンの火が消えちゃう！",v:"03_0192"},{w:null,t:"ヤマト、森を見わたす。"},{w:null,t:"ヤマトの目が、フォルンの細った火から、しぶきを吸ってふくらんだ根もとの苔へ。"},{w:"hero",t:"火と、水と、森……じゃんけんじゃん、これ。",v:"03_0196"},{w:"elly",f:"serious",t:"……ほんとだ。",v:"03_0197"},{w:null,t:"ヤマトの目が、石のかげのピリポンに行く。"},{w:null,t:"ヤマトの目が、小川から、左の、白っぽい石の地面へ行く。"},{w:"hero",t:"フォルン！　もう、木の下にいなくていい！",v:"03_0201"}],[{w:"hero",t:"（石の地面の奥を指さして）あそこまで下がれ！",v:"03_0203"},{w:"hero",t:"川から遠い、乾いた所までだ！",v:"03_0204"},{w:"alek",t:"石の上に逃げたって、終わり方は同じだぞ。",v:"03_0207"},{w:"hero",t:"逃げてねーよ。来られるもんなら、来てみろよ。",v:"03_0208"},{w:null,t:"エリー、石の地面のフォルンを見る。それから、石のかげで震えているピリポンを見る。"},{w:"elly",t:"ピリポン、もう少しだけ前に出られる？",v:"03_0210"},{w:"elly",t:"わたし、ここでずっと見てるから。",v:"03_0211"},{w:null,t:"アレク、石の地面の奥のフォルンを見る。しっぽの火が、まだ小さい。"}],[{w:"alek",t:"狐はもうへばってる。今なら一発で終わるぞ。",v:"03_0214"},{w:"alek",t:"川から上がれ！　追いかけろ！",v:"03_0215"},{w:null,t:"アレクの顔が、わずかに動く。"},{w:"alek",t:"もどれ！　川までもどるんだ！",v:"03_0221"},{w:"elly",f:"serious",t:"……ピリポン、いける？",v:"03_0223"},{w:"elly",t:"ピリポン、ぱちって！",v:"03_0227"},{w:"hero",t:"フォルン、今だ！　乾いた所から撃て！",v:"03_0229"}]],post:[{w:null,t:"ワニの子が、炎に押されて吹き飛び、小道の草の上を転がって、ひっくり返る。目を回して、起き上がらない。"},{w:null,t:"ひっくり返ったワニの子の耳のうしろのうろこを、雷の残りが、ちりちりっと走る。"}]};
GR_EP[3]={"t": "夜の森", "sc": [["g03_01", "森の小川（夕方）", 0], ["g03_02", "ホテルの裏口（夜）", 0], ["g03_03", "森の道（夜）", 0], ["g03_04", "口げんか", 0], ["g03_05", "向かい合う", 0], ["g03_06", "勝負（2Dアニメ）", 1], ["g03_07", "勝負のあと", 0], ["g03_08", "ホテルの門（夜ふけ）", 0]]};
GR_SC.g04_01=[{w:null,t:"坂のとちゅうに、黒塗りのロボタクシーが止まっている。"},{w:null,t:"うしろの席。"},{w:null,t:"画面の字。「アレク　応答なし」「オリーヴァ村　狐　まだ」。"},{w:"nina",t:"マルコ、起きて。仕事が来たよ。",v:"04_0033"},{w:"marco",t:"……それ、アレクさんの仕事っすよね。",v:"04_0034"},{w:"marco",t:"おれら、もう外されたじゃないっすか。",v:"04_0035"},{w:"nina",t:"そのアレクが、きのうの夜から返事しないんだって。",v:"04_0036"},{w:"nina",t:"だから、こっちに回ってきたの。",v:"04_0037"},{w:null,t:"マルコ、帽子を少しだけ上げる。"},{w:"marco",t:"……めんどくさいっすね。朝ごはん、まだなのに。",v:"04_0039"},{w:null,t:"マルコの足もとで、黒い体にオレンジの点の散った、小さなヤモリの子が、目をあける。"},{w:null,t:"耳のうしろで、ヴィクターのマークの小さなチップが、ちかっと光る。"},{w:null,t:"第4話　夜明けの火",v:"04_0043"}];
GR_SC.g04_02=[{w:null,t:"坂の上のホテル。四日目の朝。",v:"04_0049"},{w:null,t:"ぶどう畑のはしの道具小屋から、アレクが、うすい掛け物をたたみながら出てくる。"},{w:null,t:"二階の窓から、アナが顔を出す。"},{w:"ana",t:"おはよう。じゃあ、ひと晩分の宿代ね。20ジェムコイン。",v:"04_0052"},{w:"alek",t:"すみません、今は払えないんです。",v:"04_0053"},{w:"alek",t:"払いに使っていた画面を、きのうの夜、川に捨てたので。",v:"04_0054"},{w:"ana",t:"画面を、川に？　……じゃあ、裏の用水路の泥かき。",v:"04_0055"},{w:"ana",t:"それでいいから。",v:"04_0056"},{w:"alek",t:"泥かきなら、ロボットの方が早くないですか。",v:"04_0057"},{w:"ana",t:"ロボットは、ぬかるみに足を取られて動けなくなるの。",v:"04_0058"},{w:"alek",t:"はい。分かりました。",v:"04_0059"},{w:null,t:"小屋の横の石の水おけ。クロッコが体をしずめて、目をつむっている。"}];
GR_SC.g04_03=[{w:null,t:"朝ごはんのテラス。"},{w:null,t:"テーブルのあいだを、丸い小さなロボットがすべって回る。"},{w:null,t:"テラスの手すりの向こう、裏の畑。"},{w:"hero",t:"でさ、相手、水なわけ。こっちは炎だろ。",v:"04_0066"},{w:"hero",t:"ふつうは、負けるじゃん。",v:"04_0067"},{w:"x",n:"客の子A",t:"えっ、負けちゃうの？",v:"04_0068"},{w:"hero",t:"ふつうはね。でも、そこでおれが気づいちゃったわけ。",v:"04_0069"},{w:null,t:"ヤマト、指を立てて、炎、森、水、と一本ずつ折っていく。"},{w:"hero",t:"全部、じゃんけんみたいになってんの。",v:"04_0071"},{w:"hero",t:"だから、勝てる場所に下がればいいって。",v:"04_0072"},{w:"x",n:"客の子B",t:"じゃあ、じゃんけんで勝ったってこと？",v:"04_0073"},{w:"hero",f:"smile",t:"じゃんけんみたいなもんで、勝ったの。",v:"04_0074"},{w:"elly",t:"（パンをちぎりながら）気づいたの、負けそうになってからだったよね。",v:"04_0075"},{w:"hero",t:"負けそうになってからでも、気づいたもんは気づいたの。",v:"04_0076"},{w:null,t:"テーブルのはしで、フォルンがしっぽの火の上でオリーブを転がしている。"},{w:null,t:"ヤマト、いちばん大きい焼きオリーブを、ひょいとつまむ。"},{w:"hero",t:"これは、作戦を考えたおれの分ね。",v:"04_0079"},{w:null,t:"フォルンのしっぽの火が、ぼっとふくらむ。"},{w:"hero",t:"あっ、ち、ち、ち——",v:"04_0081"},{w:null,t:"オリーブが手のひらの上でおどる。"},{w:null,t:"フォルン、宙のオリーブを口で受けとめる。"},{w:null,t:"子どもたちが、どっと笑う。"},{w:"hero",t:"……と、とにかく。次にだれが来ても、おれとフォルンなら——",v:"04_0085"},{w:null,t:"テラスの入口に、アナが立っている。"},{w:"ana",t:"ヤマト。門のところに、あんたにお客さんが来てる。",v:"04_0087"}];
GR_SC.g04_04=[{w:null,t:"門の外に、マルコ。"},{w:"marco",t:"どうも。ヴィクターのマルコっす。この前は、どうも。",v:"04_0091"},{w:"marco",t:"……あの狐、ここにいますよね。",v:"04_0092"},{w:null,t:"ヤマトの足もとで、フォルンの耳が立つ。"},{w:null,t:"マルコの目が、フォルンから、そのうしろへ行く。"},{w:"marco",t:"……アレクさん？　なにしてんすか、そんなとこで。",v:"04_0095"},{w:"alek",t:"見りゃ分かんだろ。泥かきだよ、泥かき！",v:"04_0096"},{w:"marco",t:"いや、それは見れば分かるんすけど。……まあ、いいや。",v:"04_0097"},{w:"marco",t:"そういうの報告すんの、めんどくさいんで。",v:"04_0098"},{w:null,t:"坂の下で、ニーナの画面が、かしゃっと鳴る。"},{w:"marco",t:"一対一で、どうすか。そっちが勝ったら、おれは手を引きます。",v:"04_0100"},{w:"marco",t:"おれが勝ったら、狐はもらっていきます。",v:"04_0101"},{w:null,t:"アレク、泥だらけのまま、畑から門へ走ってくる。"},{w:"alek",t:"おい、ヤマト、待て！　勝手に返事すんなよ！",v:"04_0103"},{w:"hero",t:"まだ何も言ってないって。",v:"04_0104"},{w:"hero",t:"（マルコに）受けなかったら、どうなんの？",v:"04_0105"},{w:"marco",t:"ニーナさんがドローンを呼んで、網っすね。",v:"04_0106"},{w:"marco",t:"ホテルの屋根の上から。",v:"04_0107"},{w:"marco",t:"おれは、そっちの方がめんどくさいんすけど。",v:"04_0108"},{w:null,t:"ヤマト、テラスの方をふり返る。"},{w:null,t:"ヤマト、アレクの顔を見る。"},{w:null,t:"アレク、テラスの子どもたちを見る。それから、水おけのクロッコ。"},{w:"alek",t:"……受けるしかねえか。",v:"04_0112"},{w:"alek",t:"クロッコは、まだ戦えないからな。",v:"04_0113"},{w:"hero",t:"分かってる。フォルンだけで行く。",v:"04_0114"},{w:null,t:"マルコの肩のヤモリが、口をあける。"},{w:null,t:"エリーの肩のピリポンが、エリーの髪の中に、頭からもぐりこむ。"},{w:"elly",t:"……ピリポン、ああいう大きい火は、こわくてだめなの。",v:"04_0117"},{w:"alek",t:"あのヤモリ、まだ進化するぞ。",v:"04_0118"},{w:"hero",t:"大丈夫だって。乾いた所から撃ちゃいいんだろ。",v:"04_0119"},{w:"hero",f:"smile",t:"きのうの夜、それで勝ったじゃん。",v:"04_0120"},{w:null,t:"ヤマトは、もう門の外に出ている。"},{w:"marco",t:"場所は、どこでもいいっすけど。……裏の畑にしましょうか。",v:"04_0122"},{w:"marco",t:"林のそばなら、日かげがあるんで。",v:"04_0123"}];
GR_SC.g04_05=[{w:null,t:"ぶどう棚の前で、マルコが畑を見わたす。"},{w:null,t:"手前は、乾いた草の畑。"},{w:null,t:"マルコ、林のわきの石垣のかげに木箱を置いて、座る。"},{w:null,t:"ヤマト、フォルンを手前の畑のまん中に立たせる。"},{w:null,t:"アレクとエリーが、ぶどう棚の下に立つ。"},{w:"marco",t:"じゃ、始めましょうか。こっちは、いつでもいいっすよ。",v:"04_0134"}];
GR_SC.g04_09=[{w:null,t:"フォルンの体から、光がすうっと引いていく。"},{w:null,t:"ヤマト、ひざをついたまま、目をぱちぱちさせる。"},{w:"alek",t:"勝負が終われば、もとの姿にもどるんだよ。",v:"04_0221"},{w:null,t:"マルコ、オキヤモを両腕でかかえ上げて、重そうに肩にかつぎ直す。"},{w:"marco",t:"……約束は約束なんで、今日は帰ります。",v:"04_0223"},{w:"nina",t:"マルコ、今の、ボスに送る写真、撮った？",v:"04_0224"},{w:"marco",t:"ニーナさんが、坂の下でもう撮ってたじゃないっすか。",v:"04_0225"},{w:"marco",t:"おれは、もういいっす。",v:"04_0226"},{w:null,t:"マルコ、帰りかけて、アレクの前で止まる。"},{w:"marco",t:"アレクさん。",v:"04_0228"},{w:"marco",t:"……抜けるんなら、もっと遠くまで行った方がいいっすよ。",v:"04_0229"},{w:"marco",t:"うちのボス、しつこいんで。",v:"04_0230"},{w:"alek",t:"……分かってるよ。",v:"04_0231"},{w:null,t:"マルコ、坂を下りていく。肩の上で、オキヤモのしっぽがぶらぶらゆれる。"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。さっきまで見上げていた顔が、ひざの高さにある。"},{w:null,t:"フォルン、首をくるっと回して、ヤマトの右手の指なし手袋を、ぱくっとくわえて引きぬく。"},{w:"hero",t:"おい、それ、おれの手袋だって。",v:"04_0235"},{w:null,t:"フォルン、手袋をぶらぶらさせながら、畑の外へすたすた出ていく。"},{w:"hero",t:"返せって！　なでさせてくれないのに、手袋は取るのかよ！",v:"04_0237"},{w:null,t:"エリーの髪の中から、ピリポンが目だけ出して、フォルンを見ている。"},{w:null,t:"アレク、勝負のあった畑を見ている。"}];
GR_SC.g04_10=[{w:null,t:"ロビーの画面に、広告。"},{w:null,t:"ヤマト、その前に立っている。"},{w:null,t:"アレクがうしろに来る。"},{w:"alek",t:"ニーナが写真を送ったんだ。",v:"04_0245"},{w:"alek",t:"昼までには、ヴィクターの車がもっと来るぞ。",v:"04_0246"},{w:"alek",t:"今のうちに、村を出た方がいい。",v:"04_0247"},{w:null,t:"パンの袋をつめていたエリーの手が、一瞬だけ止まる。"},{w:"hero",t:"白い都まで、どれくらいかかんの？",v:"04_0249"},{w:"alek",t:"歩きなら、二週間くらいだ。",v:"04_0250"},{w:"hero",f:"serious",t:"……歩き？　ロボタクシーとか、乗らないの？",v:"04_0251"},{w:null,t:"門の前を、ロボタクシーがすうっと通る。ヤマト、手を上げかける。"},{w:"alek",t:"乗るなって！",v:"04_0253"},{w:"alek",t:"乗った記録から、居場所がヴィクター一味にばれるだろ。",v:"04_0254"},{w:"hero",t:"てかさ、アレク、なんでついてくんの？",v:"04_0255"},{w:"hero",t:"もう仕事、やめたんだろ。",v:"04_0256"},{w:"alek",t:"仕事を投げて、うそまでついたんだ。おれも追われるよ。",v:"04_0257"},{w:"alek",t:"それと、大会の賞金。勝ったら、案内料こみで半分もらうからな。",v:"04_0258"},{w:"hero",f:"serious",t:"……それは、勝ってから決めようぜ。",v:"04_0259"},{w:null,t:"アレク、水おけからクロッコを出して、背中にかつぐ。クロッコ、目はあけない。"},{w:"ana",t:"おばあちゃんから、電話があったよ。",v:"04_0261"},{w:"ana",t:"……どうせ、止めても行くんでしょ。",v:"04_0262"},{w:null,t:"エリー、目をそらして、笑う。"},{w:"ana",t:"画面は、名無しにしてあるんでしょ。",v:"04_0264"},{w:"ana",t:"そのかわり毎晩、自分の画面で電話してきなさい。",v:"04_0265"},{w:null,t:"アナ、エリーのうしろのアレクを、一度だけ見る。"},{w:"ana",t:"電話が一晩抜けたら、むかえに行くからね。",v:"04_0267"},{w:"elly",f:"serious",t:"……うん。毎晩、かける。",v:"04_0268"},{w:null,t:"アナ、上着のポケットから、手のひらほどのうすい板を出す。"},{w:"ana",t:"それと、これ。",v:"04_0270"},{w:"ana",t:"名前のつかない、使い切りのジェムコインのカード。",v:"04_0271"},{w:"elly",t:"お金ゼロのこと、なんで知ってるの？",v:"04_0272"},{w:"ana",t:"名無しの画面には、毎月のお金が来ないでしょ。",v:"04_0273"},{w:"ana",t:"これなら、名前が残らないで払えるの。",v:"04_0274"},{w:"hero",f:"smile",t:"（のぞきこんで）すげえ。これで、アイス何個ぶん？",v:"04_0275"},{w:"ana",t:"アイスに使うんじゃないの。ごはんと宿に使いなさい。",v:"04_0276"},{w:null,t:"エリー、カードを両手で受け取って、肩かけカバンの内ポケットにしまう。"},{w:null,t:"アナ、アレクの方を向く。"},{w:"ana",t:"（アレクに）宿代は、泥かきでちゃらにしてあげる。",v:"04_0279"},{w:"ana",t:"そのかわりカードの分は、帰ってきたら働いて返してね。",v:"04_0280"},{w:null,t:"アレク、背すじをのばして、アナに頭を下げる。"},{w:"alek",t:"はい。必ず、働いて返しに来ます。",v:"04_0282"},{w:null,t:"アナ、フロントの「忘れ物」の箱から、古い型の手首の画面を一つ出して、アレクに投げる。"},{w:"ana",t:"それも。二年だれも取りに来ないから、あげる。",v:"04_0284"},{w:"ana",t:"手首に何もないと、かえって目立つよ。",v:"04_0285"},{w:null,t:"アレク、受け取って手首に巻く。"},{w:"hero",t:"はや。",v:"04_0287"},{w:null,t:"アレク、ヤマトとエリーの方を向く。"},{w:"alek",t:"昼でも、森の道を行こうぜ。上から見えにくいからな。",v:"04_0289"},{w:null,t:"三人とフォルンが、ぶどう畑の先の森の道へ。"},{w:null,t:"ヤマト、一度ふり返る。"}];
GR_SC.g04_11=[{w:null,t:"昼前の光が、小川の底までさしこんでいる。"},{w:null,t:"画面が、水の中でぽうっと光る。"},{w:null,t:"黒いドローンが一機、低く飛んでくる。"},{w:null,t:"赤い光が、岸のぬかるみで止まる。"},{w:null,t:"ドローンが高く上がる。"}];
GR_BT[4]={mid:[[{w:"hero",t:"フォルン、乾いた所から撃て。水には寄るな。",v:"04_0137"},{w:"marco",t:"スミヤモ、焼いちゃって。",v:"04_0141"},{w:"alek",t:"向こうも炎だろ！　炎どうしは、弱点がねえんだよ！",v:"04_0145"},{w:"hero",t:"じゃあ、近くで撃て！　フォルン、林まで行け！",v:"04_0146"},{w:"marco",t:"あーあ。当てちゃいましたね。",v:"04_0151"},{w:"hero",t:"出ろ！　フォルン、林から出ろ！",v:"04_0155"},{w:null,t:"アレクは何も言わない。組んだ腕の指が、ひじをつかんでいる。"}],[{w:null,t:"マルコ、木箱から腰を上げて、のびをする。"},{w:"marco",t:"あー、もういいっす。",v:"04_0161"},{w:"marco",t:"これ以上焦がすと、あとでボスがうるさいんで。",v:"04_0162"},{w:"marco",t:"オキヤモ、止まれ。",v:"04_0163"},{w:"marco",t:"……オキヤモ？　止まれって言ってるんすけど。",v:"04_0166"},{w:null,t:"ニーナの手首の画面が鳴る。"}],[{w:"marco",t:"……ニーナさん、止められないんすか。",v:"04_0168"},{w:"nina",t:"ボスが、止めるなって。",v:"04_0169"},{w:null,t:"マルコ、ニーナの画面をのぞきこんだまま、だまる。"},{w:"marco",t:"もういいって。止まってくださいよ。",v:"04_0176"},{w:null,t:"アレク、ぶどう棚の下から一歩出る。"},{w:"alek",t:"ヤマト、もうやめさせろ！　これ以上は、無理だ！",v:"04_0180"},{w:null,t:"ヤマト、ぶどう棚の前から、畑のなかほどまで走り出る。"},{w:"hero",t:"フォルン！　おい、フォルン！",v:"04_0182"},{w:null,t:"マルコの口が、あいたまま。"},{w:null,t:"ヤマトは、手首の画面を見ない。"}],[{w:null,t:"ヤマトの目が、二つの炎を見くらべる。"},{w:"hero",t:"フォルコン、あいつを水から上げるな！",v:"04_0201"}]],post:[{w:null,t:"オキヤモが吹き飛ばされて、ぬかるみの上にあおむけに倒れる。"},{w:null,t:"倒れたオキヤモの耳のうしろで、チップがまだ光っている。"},{w:"marco",t:"……もういいって。お前、がんばったよ。",v:"04_0212"},{w:null,t:"マルコ、畑を歩いていって、ぬかるみに入る。"},{w:"nina",t:"……ボスから。「もういい」って。",v:"04_0215"}]};
GR_EP[4]={"t": "夜明けの火", "sc": [["g04_01", "村を見下ろす坂（夜明け）", 0], ["g04_02", "ホテルの裏・道具小屋（朝）", 0], ["g04_03", "ホテルのテラス（朝）", 0], ["g04_04", "ホテルの門", 0], ["g04_05", "ホテルの裏の畑・向かい合う", 0], ["g04_06", "勝負・炎どうし（2Dアニメ）", 1], ["g04_07", "勝負・止まらない（2Dアニメ）", 1], ["g04_08", "勝負・水から上げない（2Dアニメ）", 1], ["g04_09", "勝負のあと", 0], ["g04_10", "ホテルのロビーと門（昼前）", 0], ["g04_11", "ホテル裏の森の小川", 0]]};
GR_SC.g05_01=[{w:null,t:"オリーヴァ村を出た三人は、丘のオリーブの木の下で夜を明かした。",v:"05_0024"},{w:null,t:"丘の中腹。古いオリーブの木の下に、銀色のうすいシートが一枚。"},{w:null,t:"ヤマトだけ、シートからはみ出して、草の上で大の字。"},{w:null,t:"フォルンは、シートのはしで丸くなっている。しっぽの火だけが、シートの外に出ている。"},{w:null,t:"丘の下の道。"},{w:null,t:"アレク、目をあける。"},{w:null,t:"アレク、フォルンのしっぽをつかんで、シートの中へ押しこむ。"},{w:null,t:"アレク、ヤマトの腕をつかんで、シートの下へずるずる引きずりこむ。エリーは、目をつむったまま、自分でころころ転がって場所をあける。"},{w:null,t:"ドローンが丘を上がってきて、オリーブの木の上で止まる。"},{w:null,t:"アレク、シートのはしを持ち上げて、長く息を吐く。"},{w:"hero",t:"（寝ぼけて）……なに。もう朝？　なんで、おれの腕、引っぱってんの。",v:"05_0034"},{w:"alek",t:"ヴィクターのドローンだよ。あの赤い光、体の熱を見てんだ。",v:"05_0035"},{w:"alek",t:"シートの下にいりゃ見つかんないのに。",v:"05_0036"},{w:"alek",t:"お前だけ、外で大の字で寝てたんだぞ。",v:"05_0037"},{w:"hero",t:"だったら、ふつうに起こせばいいじゃん。",v:"05_0038"},{w:"alek",t:"起こしたって！　何回も呼んだのに、ぜんぜん起きねえんだもん。",v:"05_0039"},{w:"elly",t:"（シートの中から、目をつむったまま）うん。アレク、何回も呼んでたよ。",v:"05_0040"},{w:"hero",t:"起きてたんなら、エリーが起こしてくれればよかったじゃん。",v:"05_0041"},{w:"elly",t:"わたしは、自分で転がって場所をあけたもん。",v:"05_0042"},{w:"elly",t:"ヤマトの分まではむり。",v:"05_0043"},{w:null,t:"アレク、かまれた手をふりながら、丘の下の道を見る。"},{w:"alek",t:"道は、あいつの通り道だ。畑の中、行こうぜ。",v:"05_0045"},{w:null,t:"フォルン、シートから顔を出して、あくび。"},{w:"hero",t:"おい、それ、まだ返してくれないのかよ。",v:"05_0047"},{w:null,t:"第5話　丘の畑",v:"05_0049"}];
GR_SC.g05_02=[{w:null,t:"オリーヴァ村の東。オリーブの丘が、いくつも続いている。",v:"05_0055"},{w:null,t:"となりの大きな丘。"},{w:null,t:"こちらの斜面の畑。"},{w:"hero",t:"あっちの丘はロボットなのに、こっちは手か。",v:"05_0058"},{w:"hero",t:"手で摘むと、高く売れんの？",v:"05_0059"},{w:"elly",t:"うん。だれが摘んだか、記録に残るんだって。",v:"05_0060"},{w:"hero",t:"じゃあ、おれが拾ったのも、高くなんの？",v:"05_0061"},{w:"elly",t:"ヤマトの手首の画面は、この畑とつながってないもん。",v:"05_0062"},{w:null,t:"ヤマト、くやしそうに、網の上の実を一つ拾って、近くの女の人のかごに入れる。"},{w:"x",n:"村の女の人",t:"ありがとう。……あなたたち、この丘を越えて行くの？",v:"05_0064"},{w:"elly",t:"うん。向こうがわに下りたいの。",v:"05_0065"},{w:"x",n:"村の女の人",t:"なら、いちばん上のヤニスさんの畑を通るしかないよ。",v:"05_0066"},{w:"x",n:"村の女の人",t:"先月から、よそ者にはきびしいけどね。",v:"05_0067"},{w:null,t:"ヤマト、丘のいちばん上を見上げる。"},{w:null,t:"クロッコは、アレクの足のうしろを、自分の足で歩いている。"},{w:null,t:"ピリポンは、エリーの肩の上。前を行くフォルンのしっぽの火がゆれるたびに、エリーの髪の中に頭をつっこむ。"}];
GR_SC.g05_03=[{w:null,t:"この丘のいちばん上に、ひときわ手入れのいい畑があった。",v:"05_0073"},{w:null,t:"畑の見えるところで、アレクの足が止まる。"},{w:null,t:"アレク、がけの下と石垣の高さを目ではかる。それから、畑の中の道へ歩き出す。"},{w:null,t:"手入れのいい木の並び。"},{w:null,t:"幹の小さな穴のいくつかに、黒い網の切れはしがひっかかったまま。"},{w:null,t:"畑のはしを、石を組んだ溝が流れている。"},{w:null,t:"手前のすみに、昔の脱穀場の、丸い石の床。"},{w:null,t:"畑のはしに、小さな石の家。"},{w:null,t:"男が一人、くずれた溝の石を、だまって積み直している。"},{w:null,t:"【字幕】「ヤニス」。"},{w:null,t:"ヤマト、石の床の上に、どさっと座って、両手をつく。"},{w:"hero",t:"エリー、この石、ぽかぽかしてる！",v:"05_0084"},{w:"hero",t:"ほとんど寝てないから、ちょっとだけ寝てっていい？",v:"05_0085"},{w:"alek",t:"お前、ドローンが来ても起きないくらい、ぐっすり寝てただろ！",v:"05_0086"},{w:"alek",t:"それに、ここは人の畑だぞ。",v:"05_0087"},{w:null,t:"エリーの肩から、ピリポンが石の床に、ぴょんと下りる。"},{w:null,t:"ヤマト、石についていた手を、さっと上げる。"},{w:null,t:"エリーは、床のはしまで走っていった火花を、じっと見ている。"},{w:null,t:"ピリポン、自分でびっくりして、エリーの足をかけ上がり、肩から髪の中にもぐる。"},{w:null,t:"太いオリーブの幹に、小さなカブトムシのテリオンがとまっている。"},{w:"hero",t:"カブトムシだ！",v:"05_0093"},{w:"hero",t:"こいつ、進化したらヘラクレスオオカブトみたいになんのかな。",v:"05_0094"},{w:"hero",t:"動画で見たことある。",v:"05_0095"},{w:"elly",t:"ヘラクレスって、もとは人の名前なんだよ。",v:"05_0096"},{w:"hero",t:"人？",v:"05_0097"},{w:"elly",t:"ギリシャの昔のお話に出てくる、すっごく力持ちの人。",v:"05_0098"},{w:"elly",t:"カブトムシの方が、あとからその人の名前をもらったの。",v:"05_0099"},{w:"hero",t:"じゃあ、そのうち、おれの名前の虫も出るかもな。",v:"05_0100"},{w:"elly",t:"ヤマトカブト？　……ちっちゃそう。",v:"05_0101"},{w:null,t:"カブッコが、幹の上で前足を、ぐっとふんばる。それから、つのを右下からすくい上げる。"},{w:null,t:"エリーだけが、それを見ている。"},{w:null,t:"ヤマトは、男のかごの黒い実を一つつまんで、光にかざしている。"},{w:"hero",t:"（男に）おじさん、これ、一個食べていい？",v:"05_0105"},{w:null,t:"ヤマト、返事を待たずに、もう口を大きくあけている。"},{w:"stavros",f:"serious",t:"……やめとけ。",v:"05_0107"},{w:"stavros",t:"とったばかりのオリーブは、しぶくて食えたもんじゃない。",v:"05_0108"},{w:null,t:"ヤマトの口が、あいたまま止まる。"},{w:null,t:"男の目が、ヤマトのうしろへ行く。"},{w:null,t:"アレクは、くずれた溝と、土のタイヤのあとを見ている。"},{w:"alek",t:"（ヤマトとエリーに、小声で早く）このタイヤのあと、まだ新しい。",v:"05_0112"},{w:"alek",t:"きのうの夜、ヴィクターの車がここ通ってるぞ。",v:"05_0113"},{w:"stavros",f:"serious",t:"……よく見てるな。",v:"05_0114"},{w:null,t:"ヤニス、幹の穴に指を入れて、網の切れはしをつまみ出す。"},{w:"stavros",t:"先月の晩、ドローンがこの木に網を落としていった。",v:"05_0116"},{w:"stavros",t:"ここに住んでた小さいのが、十二ひき、みんな連れていかれた。",v:"05_0117"},{w:"stavros",t:"その前の日に来た連中は、旅の者だと言って、畑を見ていった。",v:"05_0118"},{w:"stavros",t:"役場に言ったら、国の許しは出てるって言われた。",v:"05_0119"},{w:null,t:"幹の上で、カブッコが羽を一度だけふるわせる。"},{w:null,t:"ヤニスの目が、アレクの足もとのクロッコで止まる。"},{w:null,t:"ヤニス、手の中の網の留め金と、見くらべる。"},{w:"stavros",f:"serious",t:"……ヴィクターのチップだな。",v:"05_0123"},{w:"alek",t:"はい。前の雇い主に渡されたやつです。",v:"05_0124"},{w:null,t:"アレク、それ以上は言わない。ヤニスの目から、目をそらさない。"},{w:"hero",t:"でも、アレクはもう、その仕事やめたんだって！",v:"05_0126"},{w:"hero",t:"おれたちは、ヴィクターに追われてる方なの！",v:"05_0127"},{w:"stavros",t:"口では、何とでも言える。",v:"05_0128"},{w:null,t:"ヤニス、立ち上がって、手首の画面にふれる。畑の入口の低い柵が、すうっとせり上がって閉まる。"},{w:"stavros",t:"通りたいなら、勝負しろ。",v:"05_0130"},{w:"stavros",t:"手下なら、負けそうになればドローンを呼ぶはずだ。",v:"05_0131"},{w:"stavros",t:"負けたら、来た道を帰れ。",v:"05_0132"},{w:null,t:"ヤマトの顔が、少しだけ固まる。"},{w:"alek",t:"じゃあ、こっちは三体で出てもいいですか。",v:"05_0134"},{w:"stavros",t:"そっちが三体なら、こっちも三体だ。",v:"05_0135"},{w:null,t:"ヤニス、口笛を短く一回。"},{w:"hero",t:"え、三匹もいたの？",v:"05_0137"},{w:"stavros",t:"あの晩、家の中にいた三匹だけが残った。",v:"05_0138"},{w:null,t:"エリー、肩のピリポンの頭を、指でとんとんとたたく。"}];
GR_SC.g05_04=[{w:null,t:"畑のまん中で、勝負が始まる。",v:"05_0145"},{w:null,t:"向こうのはしはオリーブの木。"},{w:null,t:"ヤニス、千年のオリーブの向こうがわ、幹のかげに立って、腕を組む。"},{w:null,t:"ヤマト、フォルンを手前のまん中に。"},{w:null,t:"アレク、クロッコを溝のそばの草に下ろす。"},{w:null,t:"エリー、石の床から十歩うしろの、石垣の前に立つ。"},{w:"stavros",t:"始め。",v:"05_0151"}];
GR_SC.g05_08=[{w:null,t:"昼。千年のオリーブの下。",v:"05_0226"},{w:null,t:"フォルコンとピリムサとヘラツノの体から、光がすうっと引いていく。"},{w:null,t:"ヤニス、カブッコ三匹のそばにしゃがむ。"},{w:null,t:"エリー、石の床の上のピリポンをだき上げる。"},{w:"elly",t:"ピリポン、さっき、すっごく大きくなってたよ！",v:"05_0230"},{w:null,t:"ピリポン、エリーの顔に、ぱちっ。"},{w:null,t:"アレク、溝からクロッコをだき上げる。クロッコ、ぶるぶる体をふって、アレクの顔に水をかける。"},{w:null,t:"ヤニス、立ち上がって、アレクの前に来る。"},{w:"stavros",t:"前の雇い主ってのは、だれだ。",v:"05_0234"},{w:"alek",t:"研究にお金を出してくれてた相手です。",v:"05_0235"},{w:"alek",t:"狐だけのはずが、子どもも連れてこいって。だから、やめました。",v:"05_0236"},{w:"stavros",f:"serious",t:"……そうか。",v:"05_0237"},{w:null,t:"ヤニス、クロッコの頭に手のひらをのせる。それから、ふり返って、フォルンの耳のうしろを見る。"},{w:null,t:"ヤニス、石の家からガラスのびんを持ってくる。"},{w:"stavros",t:"こっちは、しおみずに二か月つけてある。これなら、食える。",v:"05_0240"},{w:null,t:"ヤマト、一つ口に入れる。顔が、きゅっとすっぱくなる。"},{w:"hero",t:"すっぱ！　……でも、うまい。もう一個、いい？",v:"05_0242"},{w:null,t:"ヤニス、うなずく。"},{w:null,t:"ヤニス、手首の画面にふれる。入口の柵が、すうっと下がって開く。"},{w:null,t:"ヤニスの手首の画面が、短く一回鳴る。"},{w:null,t:"写真の中の箱が、知らない字の書いた大きな荷物の箱の列に、ならべられている。"},{w:null,t:"ヤニスの指が、写真の上で止まる。"},{w:null,t:"ヤニス、だまって画面を閉じる。"},{w:null,t:"ヤマトは、ヤニスのななめうしろで、それを見ていた。"},{w:null,t:"ヤニス、かごを石の家の前に置いて、また、くずれた溝の石を積みはじめる。"},{w:null,t:"アレク、溝のそばにしゃがむ。"},{w:null,t:"ヤニス、手を止めて、それを見る。"},{w:null,t:"ヤマト、千年のオリーブの幹に、手のひらをつけている。"},{w:"hero",t:"ヤニスさん、この木って、何年くらい生きてんの？",v:"05_0255"},{w:"stavros",t:"千年は、こえてる。",v:"05_0256"},{w:"stavros",t:"この村ができるより前から、ずっとここにある。",v:"05_0257"},{w:"hero",t:"千年……。",v:"05_0258"},{w:null,t:"ヤマト、幹を見上げる。"},{w:"ana",t:"エリー！　きのうの夜、どうしてかけてこなかったの！",v:"05_0261"},{w:"ana",t:"もう少しで、さがしに行くとこだったよ。",v:"05_0262"},{w:"elly",f:"sad",t:"ごめんね。きのうはオリーブの丘の上で寝てて——",v:"05_0263"},{w:"alek",t:"（小声で）場所を言うなって！",v:"05_0265"},{w:"alek",t:"アナさんのそばに、だれがいるか分かんないだろ。",v:"05_0266"},{w:"elly",t:"……外で寝てたら、そのまま朝になっちゃったの。",v:"05_0267"},{w:"elly",t:"今夜からは、ちゃんとかけるから。",v:"05_0268"},{w:"ana",t:"……ごはんは、ちゃんと食べてる？",v:"05_0269"},{w:"elly",t:"うん。オリーブ、食べてる。",v:"05_0271"}];
GR_SC.g05_09=[{w:null,t:"夕方。三人は、畑の向こうの、いちばん高い丘のてっぺんに着いた。",v:"05_0277"},{w:null,t:"いちばん高い丘のてっぺんに、三人と三体。"},{w:null,t:"東の空。遠くの森の上に、灰色の煙が一本。"},{w:null,t:"アレク、古い望遠鏡をのぞく。"},{w:"hero",t:"あれ、煙だよな。何か燃えてんの？",v:"05_0281"},{w:"alek",t:"森のまん中から出てるな。ヤマト、手首の地図、出してくれよ。",v:"05_0282"},{w:"hero",t:"出しても平気なんだよな？",v:"05_0283"},{w:"alek",t:"大丈夫だって。おとといの夜、名無しの設定にしてやっただろ。",v:"05_0284"},{w:"alek",t:"お前の居場所は、もうどこにも出ねえよ。",v:"05_0285"},{w:null,t:"ヤマトの手首から、光の地図が宙に広がる。"},{w:"alek",t:"アルカディアの森だ。歩いたら一日はかかる。",v:"05_0287"},{w:"alek",t:"小さい火じゃねえな。",v:"05_0288"},{w:"elly",t:"あの森には、テリオンがたくさん住んでるんだよね。",v:"05_0289"},{w:null,t:"アレク、答えない。"},{w:null,t:"フォルンの鼻が、ひくっと動く。煙の方を向いて、耳を立てる。"}];
GR_BT[5]={mid:[[{w:null,t:"ヤマト、すぐには言わない。"},{w:"hero",t:"フォルン、まだ出るな。そこから一発撃て。",v:"05_0156"},{w:null,t:"ヤニス、手首の画面にふれる。"},{w:"stavros",t:"カブッコ。",v:"05_0160"},{w:"hero",t:"今の、ヤニスさんの画面で変わったのか？",v:"05_0162"},{w:"alek",t:"ああ。光ってる時に画面で呼ぶと、変わるんだ。",v:"05_0163"},{w:null,t:"ヤマト、すぐに自分の左の手首の画面を押す。"}],[{w:"hero",t:"フォルン！",v:"05_0171"},{w:"hero",t:"フォルコン、動くな。来たら、そこで撃て。",v:"05_0173"},{w:"hero",t:"近くじゃ間に合わねえ。フォルコン、離れて撃て。",v:"05_0177"},{w:"alek",t:"クロッコ、みぞに引きずりこめ！",v:"05_0179"},{w:null,t:"エリーの目は、ヘラツノの前足に止まっている。"}],[{w:"elly",t:"ピリポン、石の上から、ぱちって！",v:"05_0184"},{w:"alek",t:"あいつ、雷に弱いぞ！",v:"05_0188"},{w:null,t:"ヤマトの目が、ヘラツノの止まった所に行く。"},{w:null,t:"ヤマトの目が、草の上を動く。"},{w:"hero",t:"フォルコン、撃つな。あいつの下がる先で待て。",v:"05_0194"},{w:null,t:"エリーは、来ない。"},{w:null,t:"エリーの左の手首の画面が、ぽうっと光る。"},{w:"elly",t:"ピリポン！",v:"05_0203"}],[{w:null,t:"ヤニスの組んだ腕の指が、一本だけ動く。"},{w:"elly",t:"右！",v:"05_0211"},{w:"hero",t:"フォルコン、うしろをふさげ！",v:"05_0213"},{w:"elly",t:"ピリムサ！",v:"05_0216"},{w:"elly",t:"右！",v:"05_0219"}]],post:[{w:null,t:"ヘラツノが、草の上に、ころりと横になる。目を回している。"},{w:null,t:"千年のオリーブの葉が、風で、さあっと鳴る。"}]};
GR_EP[5]={"t": "丘の畑", "sc": [["g05_01", "丘のオリーブの木の下（夜明け）", 0], ["g05_02", "丘の斜面（朝）", 0], ["g05_03", "ヤニスの畑", 0], ["g05_04", "向かい合う", 0], ["g05_05", "勝負・押される", 1], ["g05_06", "勝負・下がる先", 1], ["g05_07", "勝負・決着", 1], ["g05_08", "勝負のあと", 0], ["g05_09", "丘のてっぺん（夕方）", 0]]};
GR_SC.g06_01=[{w:null,t:"五日目の昼。アルカディアの森の、川べり。",v:"06_0022"},{w:null,t:"昼の森。乾いた落ち葉が、地面をうめている。"},{w:null,t:"川べりの大きな岩の上に、ニーナが黒い箱を置く。"},{w:"nina",t:"歌を聞いた子は、自分で川まで歩いてくるよ。",v:"06_0025"},{w:"marco",t:"歩いてくるなら、網なんか、もういらなくないすか。",v:"06_0026"},{w:"nina",t:"歌で来ない子もいるの。そういうのは、網。",v:"06_0027"},{w:null,t:"ニーナ、手首の画面にふれる。"},{w:"marco",t:"あばれると、網が破れるんすよね。",v:"06_0029"},{w:null,t:"ニーナ、足もとの小さなおりの戸をあける。"},{w:"nina",t:"あばれる子は、こいつでおどかせってさ。",v:"06_0031"},{w:null,t:"虎の子の背中の毛が、逆立つ。"},{w:"marco",t:"……それで、もういいっすよ。",v:"06_0033"},{w:null,t:"虎の子、毛を下ろさない。"},{w:null,t:"網から抜けた角の子が、森の奥へ逃げていく。"},{w:"marco",t:"ちょっと、止めてくださいよ。",v:"06_0036"},{w:null,t:"ニーナの手首の画面。"},{w:"nina",t:"……止まんないのよ、これ。",v:"06_0039"},{w:"marco",t:"森ごと焼く気っすか、これ。",v:"06_0040"},{w:null,t:"マルコ、腰の水の筒をあけて、燃える落ち葉にかける。"},{w:null,t:"マルコの足もとで、スミヤモが、走っていった虎の子の方を見ている。"},{w:null,t:"第6話　ラドン川の歌",v:"06_0044"}];
GR_SC.g06_02=[{w:null,t:"六日目の昼すぎ。",v:"06_0050"},{w:null,t:"森へ続く道。三人とも、目の下にくま。"},{w:null,t:"アルカディア。楽園という名の森だ。",v:"06_0052"},{w:null,t:"森の入口。木の枠の自動ゲート。"},{w:null,t:"アレク、パーカーのフードを深くかぶる。受付のロボットの目から、顔をそらす。"},{w:null,t:"ロボットの胸の画面に、三人と三体の絵。"},{w:null,t:"エリー、しゃがんで、フォルンをロボットの前へ押し出そうとする。"},{w:"elly",t:"この子はフォルンっていうの。ちゃんとテリオンだよ。",v:"06_0057"},{w:"x",n:"受付のロボット",t:"フォルン様。判定できません。",v:"06_0058"},{w:null,t:"エリー、白い肩かけカバンから、手のひら大のうすいカードを出す。"},{w:null,t:"カードの上に、残高の数字が光る。"},{w:null,t:"アレク、横からその数字をのぞきこむ。"},{w:"alek",t:"エリー、そのカード、おれに持たせてくれよ。",v:"06_0062"},{w:"alek",t:"この先、何にいくら使ったか、ちゃんと数えときたいんだ。",v:"06_0063"},{w:"elly",t:"いいよ。アレク、お金の計算、好きだもんね。",v:"06_0064"},{w:"alek",t:"好きでやってんじゃねえよ！",v:"06_0065"},{w:"alek",t:"だれも数えないから、おれが数えてんだって！",v:"06_0066"},{w:null,t:"アレク、カードを受け取って、パーカーの内ポケットにしまう。"},{w:"x",n:"受付のロボット",t:"本日、森の東がわで煙が出ています。",v:"06_0068"},{w:"x",n:"受付のロボット",t:"消防のドローンが向かっております。",v:"06_0069"},{w:null,t:"ゲートが、すうっと開く。"}];
GR_SC.g06_03=[{w:null,t:"焦げたにおいが、だんだん強くなる。"},{w:null,t:"木のあいだがひらけた所。"},{w:null,t:"小川のふちに、手さげかばんほどの小さなポンプ。"},{w:"x",n:"作業員のおじさん",t:"泡は、これで終わりだ！　あとは水しかないぞ！",v:"06_0076"},{w:null,t:"バケツを回す人たちの中に、すすで顔のまっ黒な男。"},{w:null,t:"アレク、もうクロッコを小川に下ろしている。"},{w:null,t:"エリー、肩のピリポンを髪の中へ押しもどして、バケツを回す人たちの中に入る。"},{w:null,t:"フォルン、燃える草の前に立つ。しっぽを、ひと振り。"},{w:null,t:"ヤマト、バケツの列に走っていって、前の人からバケツを受け取る。"},{w:null,t:"わたしてきたのは、マルコ。"},{w:"hero",t:"あっ！　お前、ヴィクター一味の——",v:"06_0083"},{w:"marco",t:"今、それ、いいっす。バケツ、次に回してもらえます？",v:"06_0084"},{w:null,t:"ヤマト、口をあけたまま、バケツを次の人にわたす。"},{w:null,t:"煙の向こうで、ぱちぱちっと新しい火の音。"},{w:null,t:"虎の子の頭のうしろで、チップがちかっと光る。目のふちが、オレンジ色。"},{w:"x",n:"作業員のおじさん",t:"あいつだ！　朝から、あいつが火をつけて回ってる！",v:"06_0088"},{w:null,t:"虎の子の毛が逆立つ。"},{w:null,t:"フォルンが、その火の前に跳びこむ。しっぽで吸いこむ。"},{w:"x",n:"森番のおばあさん",t:"みんな、上の焼けあとまで下がるよ！",v:"06_0091"},{w:null,t:"おばあさんが、バケツの列を、小川の上の方の焼けあとへ下げる。"},{w:null,t:"ヤマトは、ひらけた所のはしの、倒れた大木のかげに走りこむ。"}];
GR_SC.g06_05=[{w:null,t:"フォルン、ふきだまりの上で、足がふらつく。"},{w:null,t:"スミヤモが、マルコの足もとにもどってくる。マルコ、しゃがんで、スミヤモの頭に手をのせる。"},{w:null,t:"小川の上の方で、最後の煙が消える。"},{w:null,t:"みんな、すすだらけで地面に座りこむ。"},{w:null,t:"ぶーん。上から、音。"},{w:"nina",t:"ドローンが来た。写真に写る前に、行くよ。",v:"06_0136"},{w:null,t:"ニーナ、マルコの腕を引く。"},{w:null,t:"赤い消防のドローンが一機、下りてくる。"},{w:null,t:"森の奥へ続く道の入口に、細い柱を二本立てる。"},{w:null,t:"ドローン、そのまま飛んで帰っていく。"},{w:null,t:"おばあさん、バケツの上から、空を見上げる。"},{w:"x",n:"森番のおばあさん",t:"あのドローンが来るのは、いつも火が消えたあとなんだよ。",v:"06_0142"},{w:null,t:"ヤマト、光るひもに手を近づける。"},{w:null,t:"エリー、焦げた草の中から、燃え残った網の切れはしを拾う。"},{w:"elly",t:"アレク、これ。ヤニスさんの木に引っかかってたのと、同じだよ。",v:"06_0145"},{w:"alek",t:"ああ。あいつら、この森でまた何か集めてんだよ。",v:"06_0146"},{w:null,t:"アレク、マルコたちが消えた森の奥を見る。"}];
GR_SC.g06_06=[{w:null,t:"森の裏がわの、舗装された細い道。"},{w:null,t:"木のあいだから、ニーナとマルコが出てくる。"},{w:null,t:"ニーナの手首の画面に、字。"},{w:null,t:"ニーナ、その字を指で横にはらう。"},{w:null,t:"ニーナ、「本部」の欄を、指で長く押す。"},{w:null,t:"マルコ、スミヤモの耳のうしろのチップを見る。"},{w:null,t:"二人、車に背を向けて、反対がわの草の小道を歩きだす。"},{w:"marco",t:"……朝ごはん、まだっすね。",v:"06_0157"},{w:"nina",t:"……行くよ。",v:"06_0158"},{w:null,t:"うしろで、ドアがすうっと閉まる。"}];
GR_SC.g06_07=[{w:null,t:"ラドン川。この秋は、夜になると、川から歌が聞こえる。",v:"06_0162"},{w:null,t:"森の外がわを流れる川。"},{w:null,t:"アレク、ヤマトの左の手首を、ぐいと引っぱる。"},{w:"alek",t:"ヤマト、地図出してくれ。場所を知らせるのは、切ったままでな。",v:"06_0165"},{w:"hero",t:"わかってるって。毎回それ言うじゃん。",v:"06_0166"},{w:null,t:"ヤマトの手首から、光の地図が宙に広がる。"},{w:"alek",t:"森の中の道、閉められちまったな。",v:"06_0168"},{w:"alek",t:"でも、川を下れば、森の向こうの外れまで行けるぞ。",v:"06_0169"},{w:"elly",t:"じゃあ、あの船に乗るんだね！",v:"06_0170"},{w:null,t:"船着き場に、白い小さな観光船。"},{w:null,t:"切符の機械。"},{w:null,t:"アレク、カードを内ポケットにもどす。"}];
GR_SC.g06_08=[{w:null,t:"白い小さな観光船。だれも舵をにぎっていない。"},{w:null,t:"エリー、船べりで自分の手首の画面にふれて、声だけでアナにかける。"},{w:"elly",t:"お姉ちゃん？　うん、みんな元気だよ！",v:"06_0178"},{w:"elly",t:"今ね、ふね……じゃなくて、ないしょ！",v:"06_0179"},{w:null,t:"となりで、アレクがじろっと見る。"},{w:"elly",t:"ちゃんと、毎晩かけるからね。おやすみ！",v:"06_0181"},{w:null,t:"エリー、笑って手をふって、切る。"},{w:null,t:"案内のロボットが、かごを持って回っている。"},{w:"x",n:"案内のロボット",t:"このあと「歌の瀬」を通ります。",v:"06_0184"},{w:"x",n:"案内のロボット",t:"歌を聞いたテリオンは、岸へ歩いていくことがございます。",v:"06_0185"},{w:"x",n:"案内のロボット",t:"お客さまも、お連れのテリオンも、こちらをどうぞ。",v:"06_0186"},{w:null,t:"エリー、髪の中のピリポンに、小さな耳あてをかぶせる。"},{w:null,t:"エリーがフォルンにも耳あてを持っていく。"},{w:null,t:"ヤマトだけ、耳せんを取らない。"},{w:"elly",t:"ヤマト、耳せんしないの？",v:"06_0190"},{w:"elly",t:"歌を聞いたら、川に入っちゃうんだよ。",v:"06_0191"},{w:"hero",t:"だって、どんな歌か聞いてみたいじゃん。",v:"06_0192"},{w:"alek",t:"聞いたら、お前が川に飛びこむって言ってるんだよ！",v:"06_0193"},{w:null,t:"ヤマト、船のまん中の太い柱を見上げる。"},{w:"hero",t:"じゃあさ、あの柱におれをしばっといてよ。",v:"06_0195"},{w:"hero",t:"それなら、飛びこめないだろ。",v:"06_0196"},{w:"alek",t:"お前、本気で言ってんのか？",v:"06_0197"},{w:"hero",t:"本気だって。いちおう、かたく結んどいて。",v:"06_0198"},{w:null,t:"アレク、長いあいだヤマトを見る。それから、荷物どめのロープで、柱にぐるぐる、ぎゅっ。"},{w:"alek",t:"言っとくけど、歌が終わるまで、ほどかないからな。",v:"06_0200"},{w:"hero",t:"いいよ。おれ、そんなのに負けないもん。",v:"06_0201"},{w:null,t:"アレク、結び目を、もう一つ足す。"},{w:null,t:"案内のロボットが、船のまん中で話しはじめる。"},{w:"x",n:"案内のロボット",t:"海の岩の上で歌う、鳥の体をした女の人たちのお話です。",v:"06_0204"},{w:"x",n:"案内のロボット",t:"その歌を聞いた船乗りは、船ごと岩へ寄っていってしまう。",v:"06_0205"},{w:"x",n:"案内のロボット",t:"そこで船長は、自分を帆柱にしばらせて、歌を聞いたそうです。",v:"06_0206"},{w:null,t:"客の何人かが、柱のヤマトを見る。ヤマトは、背中の手でロープの結び目をさぐっている。"},{w:"x",n:"案内のロボット",t:"この近くの山には、赤ちゃんの神さまのお話がございます。",v:"06_0208"},{w:"x",n:"案内のロボット",t:"生まれたその日に、牛をうしろ向きに歩かせたそうです。",v:"06_0209"},{w:"x",n:"案内のロボット",t:"その足あとで、大人をだましたそうです。",v:"06_0210"},{w:"elly",t:"赤ちゃんなのに、大人をだましたんだって！",v:"06_0211"},{w:"hero",t:"うしろ向きに歩くくらい、おれだってできるけど。",v:"06_0212"},{w:"elly",t:"ヤマトは、今、柱から一歩も動けないでしょ。",v:"06_0213"},{w:null,t:"ヤマト、また結び目をさぐる。"}];
GR_SC.g06_09=[{w:null,t:"川幅が広くなる。"},{w:null,t:"歌が聞こえてくる。"},{w:null,t:"岸の葦のあいだから、野生の子たちが出てくる。"},{w:null,t:"ヤマトの目が、その子たちを追う。"},{w:"hero",t:"ちょっと、ほどいて！　ちょっとだけでいいから！",v:"06_0224"},{w:null,t:"だれも、ふり向かない。"},{w:"hero",t:"エリー！　ほどいてって！　エリーってば！",v:"06_0226"},{w:null,t:"エリー、ヤマトに気づく。にこにこして、手をふり返す。"},{w:"hero",t:"ちがーう！！",v:"06_0228"},{w:"hero",t:"フォルン！　あの岩の箱だ！　あそこから鳴ってる！",v:"06_0233"},{w:"alek",t:"なんだよ、ずっと口が動いてたけど。何か言ってたのか？",v:"06_0244"},{w:"hero",f:"serious",t:"……べつに。ぜんぜん、平気だったし。",v:"06_0245"}];
GR_SC.g06_10=[{w:"x",n:"案内のロボット",t:"機械の確認のため、こちらで少し停まります。",v:"06_0248"},{w:null,t:"観光船が岩に寄る。"},{w:null,t:"箱は横だおし。"},{w:null,t:"アレクがしゃがんで、手のひらほどの光る板で、箱の底を照らす。"},{w:null,t:"エリー、カバンから、昼に拾った網の切れはしを出す。"},{w:null,t:"エリー、箱の丸い穴を見る。それから、葦の方を見る。"},{w:"elly",t:"あの子たち、歌に呼ばれて、どこへ歩いていくところだったの？",v:"06_0254"},{w:null,t:"アレク、札の字を、指でなぞる。"},{w:"alek",t:"森の奥だ。",v:"06_0256"},{w:null,t:"アレク、札の輪を見たまま、自分の左手の親指と人差し指のあいだを、右の親指でぎゅっとおさえる。"},{w:"elly",t:"アレク、その手、どうしたの？",v:"06_0258"},{w:"alek",t:"ここに、チップが入ってんだよ。研究の金の受け取り用。",v:"06_0259"},{w:"elly",t:"それで、場所がばれちゃうの？",v:"06_0260"},{w:"alek",t:"これは名前だけだ。場所は出ねえよ。",v:"06_0261"}];
GR_SC.g06_11=[{w:null,t:"最後の船着き場。"},{w:null,t:"岸から上がる道に、また、細い柱が二本。"},{w:"hero",f:"surprised",t:"うそだろ、ここも通行止めなの？",v:"06_0269"},{w:"alek",t:"森の中の道、全部閉めたんだろ。",v:"06_0270"},{w:"alek",t:"今夜は、どっか寝るとこさがすしかないな。",v:"06_0271"},{w:null,t:"アレク、道のわきの少しはなれた所を見る。"},{w:null,t:"明かりの方へ歩く。"},{w:null,t:"そのはしに、小さな組み立て式の小屋。"},{w:null,t:"エリー、小屋の戸を、こんこんとたたく。"},{w:null,t:"戸があく。頭に小さな明かりをつけた女の人。顔も腕も、土でまっ黒。"},{w:"x",n:"女の人",t:"……こんな夜ふけに、何の用？",v:"06_0277"},{w:"elly",t:"こんばんは！　今夜、泊まれる所はありませんか！",v:"06_0278"},{w:null,t:"アレク、エリーのうしろから一歩出る。"},{w:"alek",t:"森の道が閉められて、行くところがないんです。",v:"06_0280"},{w:"alek",t:"床で寝かせてもらえるだけで、助かります。",v:"06_0281"},{w:"x",n:"女の人",t:"……床でいいなら、入って。",v:"06_0284"}];
GR_BT[6]={mid:[[{w:"hero",f:"surprised",t:"フォルン、追え！",v:"06_0096"},{w:"alek",t:"川べりはだめだ！　足もとに来るぞ！",v:"06_0101"},{w:null,t:"ヤマトの目が、虎の子の足もとを追う。"},{w:null,t:"ヤマトの目が、フォルンのしっぽへ。"},{w:null,t:"ヤマトのとなりで、マルコが、腕の中のスミヤモを見る。それから、走っていく虎の子を見る。"},{w:"marco",t:"……スミヤモ、行くっすよ。",v:"06_0111"},{w:"hero",t:"フォルン、河原の手前の落ち葉だ！",v:"06_0114"},{w:null,t:"ヤマト、手のひらをフォルンに向けて上げる。"},{w:"hero",t:"フォルン、そこから撃て！",v:"06_0123"}]],post:[{w:null,t:"頭のうしろのチップが、ぱきっと割れる。目のふちのオレンジ色が、すうっと消える。"},{w:null,t:"虎の子、起き上がって、ぶるっと水をはらう。"}]};
GR_EP[6]={"t": "ラドン川の歌", "sc": [["g06_01", "アルカディアの森・川べりの岩（5日目の昼）", 0], ["g06_02", "アルカディアの森の入口（6日目の昼すぎ）", 0], ["g06_03", "森の中（昼すぎ）", 0], ["g06_04", "勝負・森の火（2Dアニメ）", 1], ["g06_05", "森の中・火のあと（昼すぎ）", 0], ["g06_06", "森の裏の道（夕方前）", 0], ["g06_07", "川の船着き場（夕方）", 0], ["g06_08", "観光船の上（夜）", 0], ["g06_09", "歌の瀬（夜）", 0], ["g06_10", "岸の大岩（夜）", 0], ["g06_11", "森の外れの船着き場（夜ふけ）", 0]]};
GR_SC.g07_01=[{w:null,t:"森の外れの発掘場。三人は、ここの小屋に泊めてもらった。",v:"07_0023"},{w:null,t:"組み立て式の小屋の中。"},{w:null,t:"女の人が、床の手前の半分を指さす。"},{w:"x",n:"女の人",t:"床は、こっちの半分を使って。",v:"07_0026"},{w:"x",n:"女の人",t:"奥は、先に来た子が使ってるから。",v:"07_0027"},{w:null,t:"奥の床に、銀色のシート。"},{w:null,t:"【字幕】「レン」。"},{w:"x",n:"女の人",t:"あの子も、通行止めで足止めなの。",v:"07_0030"},{w:"x",n:"女の人",t:"今夜は、迷子がよく来るねえ。",v:"07_0031"},{w:null,t:"ヤマトがエリーに日本語で何か言いながら、荷物を床に下ろす。レンが顔を上げる。"},{w:"dimi",f:"serious",t:"……日本の人？",v:"07_0033"},{w:"hero",t:"そうだけど。……え、日本語しゃべれんの？",v:"07_0034"},{w:"dimi",t:"親が日本人なんだ。おれは、アメリカから来た。",v:"07_0035"},{w:"elly",t:"へえ、アメリカから。わたしはエリー。こっちはヤマト。",v:"07_0036"},{w:"dimi",t:"レン。",v:"07_0037"},{w:null,t:"レン、それだけ言って、手首の画面に目をもどす。"},{w:null,t:"アレクの手が、パーカーのポケットの前で止まる。"},{w:"alek",t:"レンって……前の大会で優勝した、あのレンか？",v:"07_0040"},{w:"dimi",t:"うん。",v:"07_0041"},{w:"elly",f:"surprised",t:"えっ、優勝した人なの？",v:"07_0042"},{w:null,t:"レンの目が、戸口で丸くなっているフォルンの、しっぽの火に行く。"},{w:"dimi",t:"あの狐、お前の？",v:"07_0044"},{w:"hero",t:"そうだよ。今は、こいつと白い都まで旅してるとこ。",v:"07_0045"},{w:null,t:"ヤマト、戸口の方を指さす。"},{w:"hero",t:"アメリカこそ、なんでギリシャにいんの？",v:"07_0047"},{w:"dimi",t:"白い都の大会に出るんだよ。",v:"07_0048"},{w:"hero",f:"serious",t:"……マジか。おれも出るんだけど。",v:"07_0049"},{w:"dimi",t:"その狐、お前の言うこと聞くの？",v:"07_0050"},{w:"hero",t:"聞くよ！　……たまに。",v:"07_0051"},{w:null,t:"レン、それには何も言わない。手首の画面に目をもどす。"},{w:null,t:"レンの画面に、写真が一枚。"},{w:null,t:"レン、画面を消して、シートに横になる。"},{w:null,t:"ヤマト、エリーに顔を寄せる。"},{w:"hero",t:"（小声で）なんか、感じわるくない？　アメリカのやつ。",v:"07_0056"},{w:"elly",t:"（小声で）名前、レンだって。さっき聞いたでしょ。",v:"07_0057"},{w:"alek",t:"（小声で）前の大会の優勝者だぞ。覚えとけよ。",v:"07_0058"},{w:null,t:"第7話　巨人の骨",v:"07_0060"}];
GR_SC.g07_02=[{w:null,t:"次の日の朝。",v:"07_0066"},{w:null,t:"朝の光。ひもで四角く区切った地面に、掘りかけの穴がいくつも。"},{w:null,t:"奥の床の銀色のシートは、きちんとたたんである。"},{w:null,t:"ヤマト、青いシートのまわりを、ぐるぐる回っている。"},{w:null,t:"小屋から、女の人が出てくる。"},{w:"x",n:"女の人",t:"それ、気になる？",v:"07_0071"},{w:"hero",t:"なる！　きのうの夜から、ずっと気になってたんだよ。",v:"07_0072"},{w:"x",n:"女の人",t:"じゃあ、朝ごはんの前に、ちょっとだけね。",v:"07_0073"},{w:null,t:"女の人、手首の画面にふれる。"},{w:null,t:"シートの下は、赤土の大きな岩。"},{w:null,t:"へこみの中は、空っぽ。"},{w:null,t:"ヤマトの口が、あいたまま止まる。"},{w:"hero",t:"でっか……。これ、なんの骨？",v:"07_0078"},{w:"x",n:"女の人",t:"骨じゃなくて、骨の型なの。",v:"07_0079"},{w:"x",n:"女の人",t:"大昔の大きな生き物が、ここに埋まってたあと。",v:"07_0080"},{w:"alek",t:"型ってことは、中に骨があったんですよね。",v:"07_0081"},{w:"alek",t:"その骨は、今どこにあるんですか？",v:"07_0082"},{w:"x",n:"女の人",t:"それが、一本もないの。",v:"07_0083"},{w:"x",n:"女の人",t:"三年掘ってるけど、かけら一つ出てこない。",v:"07_0084"},{w:null,t:"アレク、型のふちを、目で追っていく。"},{w:null,t:"ヤマト、型の肩のあたりの、なだらかに盛り上がった線を見上げている。"},{w:"alek",t:"あの、森の道って、いつ開くか分かりますか。",v:"07_0088"},{w:"x",n:"女の人",t:"あしたの朝までは通行止めだって。",v:"07_0089"},{w:"alek",t:"じゃあ、今夜もここに泊めてもらえますか。",v:"07_0090"},{w:"alek",t:"その分、何か手伝います。",v:"07_0091"},{w:"x",n:"女の人",t:"助かる。今日は、村の子の発掘体験の日なの。",v:"07_0092"},{w:"x",n:"女の人",t:"子どもの相手をしてくれたら、それでいいよ。",v:"07_0093"},{w:"elly",t:"まかせて！　子どもの相手なら得意だよ。",v:"07_0094"},{w:"hero",t:"おれも化石掘りたい！　どこ掘っていいの？",v:"07_0095"},{w:"x",n:"女の人",t:"ひもの中はだめ。きみは、子どもたちとふるいの係ね。",v:"07_0096"},{w:null,t:"ヤマト、肩を落とす。"}];
GR_SC.g07_03=[{w:null,t:"村の子どもたちが五人。"},{w:null,t:"仕分けのロボットが、四本の足で歩きながら、ふるいに残った石を箱に分けていく。"},{w:null,t:"ヤマト、ふるいを大きくふる。"},{w:null,t:"となりの男の子がふるうと、小さな白いかけらが一つ残る。"},{w:"hero",t:"なんで、そっちばっかり出るんだよ。",v:"07_0104"},{w:"x",n:"村の男の子",t:"ふりすぎなんだよ。中身、ぜんぶ飛んでってるもん。",v:"07_0105"},{w:null,t:"ヤマトの足もとに、飛び散った小石が散らばっている。"},{w:null,t:"女の人が、手をたたいて、子どもたちを型の前に集める。"},{w:"x",n:"女の人",t:"はい、休けい。この型の昔話、してあげる。",v:"07_0108"},{w:"x",n:"女の人",t:"村のおばあちゃんたちから聞いた話だけどね。",v:"07_0109"},{w:null,t:"子どもたちが、型の前の地面に座る。"},{w:"x",n:"女の人",t:"大昔の生き物は、昔の言葉しか聞かないんだって。",v:"07_0111"},{w:"x",n:"女の人",t:"今の言葉で「おすわり」って言っても、知らん顔。",v:"07_0112"},{w:"x",n:"村の女の子",t:"じゃあ、昔の言葉で言ったら、おすわりするの？",v:"07_0113"},{w:"x",n:"女の人",t:"するする。骨だけになっても、たぶんするよ。",v:"07_0114"},{w:null,t:"子どもたちが笑う。"},{w:null,t:"エリーの、ピリポンの頭をなでていた指が、一度だけ止まる。"},{w:"x",n:"女の人",t:"それとね、この型の主は、だれかが連れていったんだって。",v:"07_0117"},{w:"x",n:"村の男の子",t:"こんなに大きいのを？　どうやって連れてくの？",v:"07_0118"},{w:"x",n:"女の人",t:"さあ。ひもでもつけて、引っぱったんじゃない？",v:"07_0119"},{w:"x",n:"村の男の子",t:"ひもじゃ無理だよ！　ちぎれちゃうって。",v:"07_0120"},{w:"x",n:"女の人",t:"だよねえ。おばあちゃんたちも、そこは知らないの。",v:"07_0121"},{w:null,t:"アレク、型の空っぽのへこみを見ている。"},{w:null,t:"休けいの続き。"},{w:"x",n:"村の女の子",t:"この子、しっぽが燃えてる！　だれの子？",v:"07_0124"},{w:null,t:"ヤマト、ふるいを置いて、すっと立ち上がる。"},{w:"hero",t:"おれの相棒。フォルンっていうんだ。",v:"07_0126"},{w:null,t:"フォルン、目をあけずに、しっぽを一回だけふる。"},{w:"x",n:"村の男の子",t:"この子、強いの？",v:"07_0128"},{w:"hero",t:"強いよ。白い都の大会にも出るしな。",v:"07_0129"},{w:"hero",t:"優勝なんか、楽勝だよ。",v:"07_0130"},{w:null,t:"日なたのフォルン、片目だけあけて、ヤマトを見る。"},{w:"x",n:"村の男の子",t:"すげえ！",v:"07_0132"},{w:"x",n:"村の女の子",t:"それ、世界じゅうから来る大会でしょ？",v:"07_0133"},{w:"hero",t:"そう。そこで一番になるんだよ。",v:"07_0134"},{w:null,t:"型の外。少しはなれた木のかげ。"},{w:null,t:"レンの口のはしが、ほんの少しだけ上がる。"}];
GR_SC.g07_04=[{w:null,t:"ヤマト、子どもたちのあいだを抜けて、レンの方へ歩いていく。"},{w:"hero",t:"おい、アメリカ。今、笑ったろ。",v:"07_0140"},{w:"dimi",t:"笑ってないよ。",v:"07_0141"},{w:"hero",t:"笑ったって！　ほんとに勝てるから言ってんだよ！",v:"07_0142"},{w:"dimi",t:"その狐が言うこと聞くか、きのうの夜に聞いたよね。",v:"07_0143"},{w:"dimi",t:"「たまに」って言ってたじゃん。",v:"07_0144"},{w:"hero",t:"それとこれとは関係ないだろ！",v:"07_0145"},{w:"dimi",t:"大会に出るなら、どうせどこかで当たるし。",v:"07_0146"},{w:"dimi",t:"今やっとく？",v:"07_0147"},{w:"hero",t:"やって——",v:"07_0148"},{w:null,t:"アレクが、うしろからヤマトの肩をつかむ。"},{w:"alek",t:"あいつ、テリオン連れてねえぞ。",v:"07_0150"},{w:"alek",t:"相手も見ないで、勝負受けんなって。",v:"07_0151"},{w:null,t:"ヤマト、レンをにらんだまま、口を閉じる。"},{w:"hero",f:"serious",t:"……夕方にしようぜ。",v:"07_0153"},{w:"dimi",t:"いいよ。夕方まで待つ。",v:"07_0154"},{w:null,t:"女の人が、二人のあいだに入る。"},{w:"x",n:"女の人",t:"夕方なら、子どもたちも帰ってるね。",v:"07_0156"},{w:"x",n:"女の人",t:"ひもの外でね。型にだけは当てないで。",v:"07_0157"},{w:null,t:"レン、木のかげへもどって、また画面を見る。"},{w:null,t:"ヤマト、ふるいの係にもどりながら、木のかげのレンから目をはなさない。"},{w:null,t:"レンの足もとの地面。"},{w:null,t:"盛り上がった土のすき間から、黄色い目が一つ、のぞく。"},{w:null,t:"小鳥の羽から色が抜けて、灰色のまま、ぴたりと止まる。"}];
GR_SC.g07_06=[{w:null,t:"女の人が来て、型の青いシートの焦げたはしを、指でつまむ。"},{w:"x",n:"女の人",t:"シートだけで済んだね。型に当たらなくて、よかった。",v:"07_0232"},{w:"alek",t:"……ありゃ、格がちがうわ。",v:"07_0233"},{w:"hero",f:"serious",t:"……分かってるよ。",v:"07_0234"},{w:null,t:"ヤマト、アレクの顔を見ないまま、倒れたフォルンの方へ歩いていく。"},{w:null,t:"レン、何も言わずに小屋の方へ歩いていく。"},{w:null,t:"エリー、ピリポンをだき上げる。"},{w:null,t:"アレク、あおむけのクロッコを起こす。"},{w:null,t:"フォルン、地面に横になったまま。"},{w:"hero",t:"エリー、テリオンの薬、ちょっと借りるな。",v:"07_0240"},{w:"elly",t:"いいよ。そっとね。",v:"07_0241"},{w:"elly",t:"ちょっと、また右手！　ほら、見せて。",v:"07_0246"}];
GR_SC.g07_07=[{w:null,t:"光る板の下のテーブル。"},{w:null,t:"女の人が、奥のレンにテーブルを指さして呼ぶ。レンは首を横にふって、奥のシートの上で一人で食べている。"},{w:null,t:"ヤマト、スープに口をつけない。"},{w:"elly",t:"ヤマト、冷めちゃうよ。負けても、お腹はすくでしょ。",v:"07_0253"},{w:"hero",f:"serious",t:"……食べてるよ。",v:"07_0254"},{w:null,t:"ヤマト、豆を一つだけ口に入れる。"},{w:null,t:"エリー、自分のパンを半分にちぎって、だまってヤマトの皿に置く。"},{w:null,t:"女の人、窓のそばで、空中の画面に型の写真を出している。"},{w:"elly",t:"ねえ、あの型の主って、どのくらい大きかったの？",v:"07_0258"},{w:"x",n:"女の人",t:"肩のところだけで、この小屋より大きいよ。",v:"07_0259"},{w:"x",n:"女の人",t:"生きてるところ、一回でいいから見てみたいね。",v:"07_0260"},{w:null,t:"アレク、窓の外の、シートをかぶった型の黒い影を見る。"},{w:null,t:"ヤマトは窓を見ていない。"}];
GR_SC.g07_08=[{w:null,t:"夜ふけ。みんな寝ている。ヤマトだけ、目をあけている。"},{w:null,t:"ヤマト、シートから出て、小屋の戸をそっとあける。"},{w:null,t:"月の光。小屋のわきの地面が、こんもり盛り上がっている。"},{w:null,t:"ヤマト、少しはなれた所に、ひざを抱えて座る。"},{w:null,t:"じっと見ている。"},{w:null,t:"月が、小屋の屋根の向こうへ動いていく。"}];
GR_BT[7]={mid:[[{w:null,t:"夕方。子どもたちが帰ったあとの発掘場。",v:"07_0168"},{w:null,t:"レン、骨の型の横の、区画のロープの外まで下がって立つ。"},{w:null,t:"レンの手首の画面。"},{w:"alek",t:"あの鱗見ろよ。あいつ一体で、こっちの三体より強いぞ。",v:"07_0173"},{w:"hero",t:"じゃあ、三体で囲めばいいじゃん。",v:"07_0174"},{w:"dimi",t:"いいよ。三体まとめてでいい。",v:"07_0175"},{w:null,t:"ヤマト、フォルンのとなりにしゃがんで、レンに指をつきつける。"}],[{w:"hero",t:"あとで、三対一はずるいとか言うなよ！",v:"07_0177"},{w:"dimi",t:"言わないよ。始めていいよ。",v:"07_0179"},{w:"elly",t:"ピリポン、いける？",v:"07_0180"},{w:null,t:"エリー、手首の画面にふれかけて、指を止める。"},{w:"elly",t:"まだ光ってないけど、変われるの？",v:"07_0183"},{w:"alek",t:"一回なった姿なら、光ってなくてもなれる。",v:"07_0184"}],[{w:"alek",t:"ただ、雷は地面に吸われちまうぞ。",v:"07_0185"},{w:"hero",t:"分かってる。ピリムサは、気を引くだけでいい。",v:"07_0186"},{w:null,t:"ヤマト、左の手首の画面にふれる。"},{w:"hero",t:"フォルン！",v:"07_0188"},{w:null,t:"エリーもだまって手首にふれる。"},{w:"hero",t:"ばらけろ！　二体は横から撃て。ピリムサは前だ！",v:"07_0190"},{w:"alek",t:"……クロッコ、右から回れ！",v:"07_0191"}],[{w:"dimi",t:"効かないよ、それ。",v:"07_0196"},{w:"dimi",t:"バジリク、もぐって。",v:"07_0197"},{w:"hero",t:"穴を囲め！　間はあけて、出てきたら叩け！",v:"07_0200"},{w:null,t:"ヤマトの目だけが、それを見ている。"},{w:"hero",t:"出た！　今だ、叩け！",v:"07_0208"},{w:"dimi",t:"魔眼封石（まがんロック）。",v:"07_0211"}]],post:[{w:null,t:"小さなクロッコは、灰色になったその場で、ころりと横に倒れて目を回す。"},{w:null,t:"光の輪は、顔を伏せたフォルコンの背中の毛の上を、すべって消える。"},{w:null,t:"フォルコン、顔を伏せたまま、低い所から炎を吐く。"},{w:"hero",t:"下向いてんな！　顔上げて撃て！",v:"07_0219"},{w:"alek",t:"あの目だ！　目が合ったら、止められちまう！",v:"07_0223"},{w:"dimi",t:"終わり。",v:"07_0227"}]};
GR_EP[7]={"t": "巨人の骨", "sc": [["g07_01", "発掘場の小屋（6日目の夜ふけ）", 0], ["g07_02", "発掘場（7日目の朝）", 0], ["g07_03", "発掘場・体験の場所（昼前）", 0], ["g07_04", "型の前（昼）", 0], ["g07_05", "発掘場（夕方）　勝負", 1], ["g07_06", "勝負のあと（夕方）", 0], ["g07_07", "小屋の中（夜）", 0], ["g07_08", "小屋の外（夜ふけ）", 0]]};
GR_SC.g08_01=[{w:null,t:"発掘場を出て三日。海ぞいの道の先に、港町ナフリアがあった。",v:"08_0028"},{w:null,t:"朝の港。白い家が坂にびっしり並んでいる。"},{w:null,t:"海から、箱を下げたドローンが何機も飛んでくる。"},{w:null,t:"魚市。台の上に魚。"},{w:null,t:"串焼きの屋台。"},{w:null,t:"魚市の床を、猫の形の掃除ロボットが歩いている。"},{w:null,t:"フォルン、ロボットの前に立ちはだかる。"},{w:null,t:"ロボット、止まらない。"},{w:null,t:"フォルン、しっぽの火をふくらませて跳びかかる。"},{w:null,t:"フォルンの体が、うしろへころころ転がる。"},{w:null,t:"ロボット、何もなかったように、また掃除を続ける。"},{w:null,t:"フォルン、走って、ヤマトの足をかけ上がり、頭の上に乗る。耳を寝かせて、ロボットをにらむ。"},{w:"hero",t:"いてててっ、爪！　自分からけんか売ったんだろ！",v:"08_0040"},{w:null,t:"フォルン、頭の上から動かない。"},{w:"elly",t:"あの子、フォルンはゴミじゃないって、分かってたよ。",v:"08_0042"},{w:"hero",t:"そういう話じゃないだろ！",v:"08_0043"},{w:null,t:"魚市の箱の中の魚が、いっせいにはねる。"},{w:null,t:"ヤマトの頭の上のフォルン、毛を逆立てて、東の空を見る。"},{w:null,t:"魚市の人たちは、一度顔を上げて、また手を動かす。"},{w:null,t:"第8話　港町ナフリア",v:"08_0048"}];
GR_SC.g08_02=[{w:null,t:"港のまん中。"},{w:null,t:"門の横に、テリオン用の読み取りの板。"},{w:null,t:"ヤマト、フォルンを頭からおろして、板の前に置く。"},{w:null,t:"門の画面に、赤い字。"},{w:"x",n:"受付の画面の声",t:"登録のないテリオンは、お乗りいただけません。",v:"08_0058"},{w:"hero",t:"えーっ！　ここまで歩いてきて、乗れないのかよ！",v:"08_0059"},{w:"elly",t:"じゃあ、どうやって白い都まで行くの？",v:"08_0060"},{w:"alek",t:"港には、自分の船で客を運んでる人もいるんだよ。",v:"08_0061"},{w:"alek",t:"そういう船なら、名前も登録も聞かないはずだ。",v:"08_0062"},{w:null,t:"アレク、パーカーのポケットから古い望遠鏡を出して、桟橋の方へ歩きだす。"}];
GR_SC.g08_03=[{w:null,t:"長い木の桟橋。"},{w:null,t:"アレク、古い望遠鏡を目に当てたまま歩いている。"},{w:"hero",t:"アレク、前見て歩けよ。",v:"08_0068"},{w:"alek",t:"客を乗せる船を探してんだから、話しかけんなって——",v:"08_0069"},{w:null,t:"アレクの足が、うろこの上で、つるっとすべる。"},{w:null,t:"アレク、桟橋のへりから、まっすぐ海へ落ちる。"},{w:null,t:"水の中で、アレクの手がばたばたする。"},{w:"alek",t:"ぶはっ！　おれ、泳げねえんだよ！",v:"08_0073"},{w:null,t:"アレクの望遠鏡が、桟橋の板の上に転がっている。"},{w:null,t:"クロッコ、桟橋から海へ跳びこむ。アレクのパーカーのえりに、口を大きく開けて、くわえに行く。"},{w:null,t:"もう一回。つるっ。"},{w:"elly",t:"クロッコ、がんばって！　もうちょっとだよ！",v:"08_0077"},{w:null,t:"そこへ、小さな舟がすうっと寄ってくる。"},{w:null,t:"字幕「マリナ」（初めて出た所で一回だけ）。"},{w:"hero",t:"水の子の相棒なのに、泳げねえの!?",v:"08_0084"},{w:"hero",t:"しかもクロッコ、くわえても、つるって！",v:"08_0085"},{w:"alek",t:"うるせえ！",v:"08_0086"},{w:"alek",t:"……だから、海の仕事は断ったんだよ。",v:"08_0087"},{w:"marina",t:"よそ見して歩くやつが、毎朝一人は落ちるんだよ。",v:"08_0089"},{w:"alek",t:"……すみません。助かりました。",v:"08_0090"}];
GR_SC.g08_04=[{w:null,t:"マリナ、舟を動かして、桟橋ぞいに、つけ根の方へ寄せていく。"},{w:null,t:"つけ根に近づくと、海の底が浅くなって、砂が透けて見える。"},{w:null,t:"マリナ、舟を桟橋につける。"},{w:"elly",t:"お姉さん、白い都まで船、出してる？",v:"08_0096"},{w:"marina",t:"出してるよ。沖の細長いのが、うちの客船。",v:"08_0097"},{w:"alek",t:"三人と、テリオンが三体です。いくらですか？",v:"08_0098"},{w:null,t:"マリナ、手首の画面に数字を出して見せる。"},{w:null,t:"アレク、ずぶぬれのまま、内ポケットからカードを出す。"},{w:"alek",t:"……全然、足りないです。",v:"08_0101"},{w:"marina",t:"名前を聞かない分、高いんだよ。",v:"08_0102"},{w:"hero",t:"じゃあさ、あと払いにしてよ！",v:"08_0103"},{w:"hero",t:"白い都の大会の賞金が入ったら、ちゃんと払うから。",v:"08_0104"},{w:"marina",t:"大会に出るの？　その狐で？",v:"08_0105"},{w:null,t:"マリナ、ヤマトの頭の上のフォルンを見る。"},{w:null,t:"ヤマトの目が、右手のばんそうこうに、一度だけ落ちる。"},{w:"hero",f:"serious",t:"……出るよ。",v:"08_0108"},{w:"marina",t:"賞金なんて、勝ってみないと分かんないでしょ。",v:"08_0109"},{w:"marina",t:"じゃあ、こうしようか。",v:"08_0110"},{w:null,t:"マリナ、沖の深い所を指さす。"},{w:"marina",t:"うちのホエルンに勝てたら、ただで乗せてあげる。",v:"08_0112"},{w:"elly",f:"smile",t:"ほんとに!?　やった！",v:"08_0113"},{w:"alek",t:"負けたら、どうなるんですか。",v:"08_0114"},{w:"marina",t:"そのカードじゃ、もらう物もないしねえ。",v:"08_0115"},{w:null,t:"マリナの目が、エリーの抱えている古い望遠鏡に止まる。"},{w:"marina",t:"それ、本物のレンズの望遠鏡だろ。今どき見ないね。",v:"08_0117"},{w:null,t:"アレク、ぬれたカードの数字を、もう一度見る。"},{w:"elly",t:"アレク、それ、いつも星を見てるやつでしょ？",v:"08_0119"},{w:"alek",t:"船代が足りねえんだから、しょうがねえだろ。",v:"08_0120"},{w:"alek",t:"……船代のかわりに、これを賭けます。",v:"08_0121"},{w:"marina",t:"決まりだね。負けたら、それはもらうよ。",v:"08_0122"},{w:"hero",f:"smile",t:"よし！　フォルン、行くぞ！",v:"08_0123"},{w:null,t:"ヤマト、フォルンを頭からおろそうとする。マリナが、鉤の柄でヤマトの手を止める。"},{w:"marina",t:"狐はだめ。桟橋は木なんだから、燃えたら困る。",v:"08_0125"},{w:"elly",t:"じゃあ、ピリポンならいい？",v:"08_0126"},{w:null,t:"エリーの髪の中から、ピリポンが目だけ出す。"},{w:"marina",t:"雷もだめ。港じゅうの魚が、腹を上にして浮いちゃうよ。",v:"08_0128"},{w:null,t:"みんなの目が、舟の上で体をぶるぶるふっているクロッコに集まる。"},{w:"marina",t:"そっちのワニの子ならいいよ。水どうしでね。",v:"08_0130"},{w:"alek",t:"……おれかよ。",v:"08_0131"},{w:null,t:"アレク、パーカーのすそをしぼる。"}];
GR_SC.g08_06=[{w:null,t:"クロベクの光が引き、小さなクロッコに。"},{w:null,t:"アレク、にぎっていた望遠鏡を、パーカーのポケットにしまう。"},{w:null,t:"クロッコ、潮だまりに口をつけて、水を飲む。"},{w:null,t:"ホエルン、目を回したまま、潮を小さく吹く。"},{w:"marina",t:"あんたの子、かみつくのは下手なんだね。",v:"08_0192"},{w:"alek",t:"あごが弱いんです。かたい物は、かめなくて。",v:"08_0193"},{w:"marina",t:"出るのは、あしたの夕方だよ。",v:"08_0194"},{w:"hero",t:"えー、今日じゃないの？",v:"08_0195"},{w:"marina",t:"客がそろうのが、あしたなんだよ。",v:"08_0196"},{w:"marina",t:"夜のうちに海を渡って、朝には白い都に着く。",v:"08_0197"},{w:"marina",t:"今夜は、うちの客船の床で寝ていいよ。",v:"08_0198"},{w:"alek",t:"……助かります。宿まで探さなくて済みました。",v:"08_0199"},{w:null,t:"フォルン、白い肩かけカバンをくわえて、エリーの前まで歩いていく。"},{w:null,t:"エリー、自分の肩をさわる。"},{w:"elly",t:"あっ、わたしのだ！　フォルン、ありがとう！",v:"08_0202"},{w:null,t:"フォルン、そっぽを向いて、ヤマトの足をかけ上がり、頭の上にもどる。"}];
GR_SC.g08_07=[{w:null,t:"その夜。晴れた夜は、白い都の方の空がぼうっと明るい。",v:"08_0206"},{w:null,t:"港の坂の上。"},{w:null,t:"夜の海。ずっと向こうの水平線の上だけ、空がうっすら白くにじんでいる。"},{w:"elly",t:"あの明るい所が、白い都だよ。",v:"08_0209"},{w:"hero",t:"あれが？　空がちょっと明るいだけだぞ。",v:"08_0210"},{w:"alek",t:"遠いからだろ。船で一晩かかるんだぞ。",v:"08_0211"},{w:null,t:"ヤマト、明かりを見ている。"},{w:null,t:"ヤマト、手首の画面を開く。"},{w:null,t:"少しして、送った字の下に、小さく「既読」。"},{w:null,t:"ヤマトの指が止まる。"},{w:null,t:"ヤマト、画面を閉じる。"},{w:null,t:"アレクのひざの上で、クロッコが寝ている。"},{w:null,t:"灯台の上の夜空。"},{w:null,t:"水平線の上の空が、白くにじんだまま。"}];
GR_BT[8]={mid:[[{w:null,t:"桟橋の先は深い海。つけ根の方は、潮が引いて浅い。",v:"08_0138"},{w:null,t:"マリナ、小舟の上で鉤を肩にかつぐ。"},{w:"hero",t:"水どうしなら、五分なんだろ？",v:"08_0142"},{w:"alek",t:"相性はな。でも、図体が倍だぞ。",v:"08_0143"},{w:"marina",t:"いいよ、いつでも。",v:"08_0144"},{w:"alek",t:"クロッコ、水を吐け！",v:"08_0145"}],[{w:"alek",t:"だから、かむなって！",v:"08_0147"},{w:"hero",t:"フォルン、カバン！",v:"08_0152"},{w:null,t:"ヤマトの頭の上のフォルン、跳びおりて、桟橋の板を走る。"},{w:"marina",t:"寄ってくるなら、ぶつけるだけだよ。",v:"08_0156"},{w:null,t:"アレク、手の中の望遠鏡を、一回にぎりしめる。"},{w:null,t:"アレク、手首の画面にふれる。"},{w:"alek",t:"クロッコ！",v:"08_0163"},{w:"alek",t:"クロベク、それだ！　かまなくていい、突け！",v:"08_0169"}],[{w:"marina",t:"ホエルン、ぶつけて！",v:"08_0170"},{w:null,t:"アレクの目が、桟橋の下の砂に行く。"},{w:"alek",t:"下がれ！　浅い方まで！",v:"08_0173"},{w:null,t:"マリナ、深い所の端とクロベクの間を、目ではかる。"},{w:"marina",t:"ホエルン、ぎりぎりまで寄って！",v:"08_0180"},{w:"alek",t:"今だ、突け！",v:"08_0182"},{w:"marina",t:"……乗りな。ただでいい。",v:"08_0185"}]],post:[]};
GR_EP[8]={"t": "港町ナフリア", "sc": [["g08_01", "港町ナフリア・朝の魚市（10日目の朝）", 0], ["g08_02", "連絡船の乗り場（朝）", 0], ["g08_03", "桟橋（朝）", 0], ["g08_04", "マリナの舟のそば（朝）", 0], ["g08_05", "桟橋（昼前）　勝負", 1], ["g08_06", "勝負のあと（昼）", 0], ["g08_07", "港の坂の上・灯台の下（夜）", 0]]};
GR_SC.g09_01=[{w:null,t:"次の日の夕方。三人は、マリナの客船に乗った。",v:"09_0026"},{w:null,t:"夕方の港。マリナの客船。"},{w:null,t:"客は少ない。"},{w:null,t:"どの子の首元にも、登録の小さな光がない。"},{w:null,t:"マリナ、操縦の台で手首の画面にふれる。"},{w:null,t:"アレク、船室の壁ぎわに座っている。"},{w:null,t:"ヤマト、船べりにひじをついて、遠ざかる港を見ている。"},{w:null,t:"港のまん中の、白い大きな連絡船の乗り場。"},{w:null,t:"ヤマトの目が、その一行で止まる。"},{w:null,t:"ヤマトの目が、上へ動く。"},{w:null,t:"ヤマト、乗り場の字から目をそらして、行く手の海の方を向く。"}];
GR_SC.g09_02=[{w:null,t:"月のない海。"},{w:null,t:"甲板に、テリオンが二体。"},{w:null,t:"そのうしろに、大柄な男。"},{w:null,t:"字幕「ゼノ」（初めて出た所で一回だけ）。"},{w:null,t:"ゼノの足もとで、水の子が一体、大きなあくびをする。"},{w:null,t:"ゼノの手首の画面。"},{w:"zeno",t:"あの船に寄せろ。明かりはつけるな。",v:"09_0045"},{w:null,t:"黒い船が、音もなく、速さを上げる。"},{w:null,t:"第9話　船の上",v:"09_0048"}];
GR_SC.g09_03=[{w:null,t:"日がしずんだ海。"},{w:null,t:"エリー、男の子の横にしゃがんでいる。"},{w:"elly",t:"ねえ、この子かわいくない？　きみが育ててるの？",v:"09_0056"},{w:"x",n:"男の子",t:"うん。ぼくが卵からかえしたんだよ。",v:"09_0057"},{w:"x",n:"男の子",t:"でも、ぼく子どもだから、まだ登録できないんだって。",v:"09_0058"},{w:"x",n:"おじいさん",t:"だから、白い都の窓口で、わたしの名前で登録するんだよ。",v:"09_0059"},{w:"x",n:"おじいさん",t:"それまでに見つかったら、回収されちまう。",v:"09_0060"},{w:null,t:"エリーの笑顔が、ほんの一瞬だけ止まる。"},{w:"elly",t:"じゃあ、着いたら、いちばんに窓口だね。",v:"09_0062"},{w:"elly",t:"それまで、その子はしっかり抱っこしとこうね。",v:"09_0063"},{w:"x",n:"若い夫婦の奥さん",t:"うちの子も同じ。連絡船には乗せてもらえなかったの。",v:"09_0064"},{w:null,t:"奥さんの足もとで、毛の長い子が、くしゃみを一つ。"},{w:null,t:"マリナが、操縦の台から甲板へ下りてくる。"},{w:"marina",t:"うちの客は、だいたいそういう人たちだよ。",v:"09_0067"},{w:"marina",t:"あんたたちみたいに、ただで乗ってる客は初めてだけどね。",v:"09_0068"},{w:"alek",t:"……その分、着いたら荷下ろしでも手伝います。",v:"09_0069"},{w:"hero",t:"そういえば、ホエルンは連れてこないの？",v:"09_0070"},{w:"marina",t:"あの子は港で留守番。",v:"09_0071"},{w:"marina",t:"きのう突かれたとこ、まだ痛がってるからね。",v:"09_0072"},{w:null,t:"アレク、ひざの上のクロッコの頭に、手をのせる。"},{w:null,t:"エリー、船べりで、自分の手首の画面にふれる。"},{w:"elly",t:"お姉ちゃん！　あしたは、大事な日だよ！",v:"09_0075"},{w:"ana",t:"エリー、ちゃんと食べた？",v:"09_0076"},{w:"elly",t:"食べたよ！　さっき、あったかいパンもらったの。",v:"09_0077"},{w:"ana",t:"よかった。夜は冷えるから、気をつけてね。",v:"09_0078"},{w:"elly",t:"うん。じゃあ、またあしたね、お姉ちゃん。",v:"09_0079"},{w:null,t:"エリー、笑って手をふって、画面を切る。"},{w:null,t:"甲板のはし。"},{w:null,t:"フォルン、毛を逆立てて、左舷の木箱の山に跳び乗る。"},{w:null,t:"乾いたシートの上で、しっぽの火が、ぽっとふくらんで元の大きさにもどる。"},{w:null,t:"フォルン、そこで丸くなる。"},{w:null,t:"ヤマト、木箱のふちにひじをつく。"},{w:"hero",t:"フォルン、そこ、客の荷物の上だぞ。",v:"09_0086"},{w:null,t:"フォルン、片目だけあけて、ヤマトを見る。"},{w:"hero",f:"serious",t:"……荷物、焦がすなよ。",v:"09_0088"}];
GR_SC.g09_04=[{w:null,t:"夜ふけ。小雨が降りだしている。客たちは屋根のある船室の入口のあたりで、うとうとしている。"},{w:null,t:"小雨と波しぶきで、甲板の板がぬれて光っている。"},{w:null,t:"船のエンジンの音に、もう一つ、低い音が重なる。"},{w:null,t:"右舷のすぐ横に、黒い船体が、明かりを消したまま並んでいる。"},{w:null,t:"マリナ、操縦の台で顔を上げる。"},{w:"marina",t:"……ゼノの船だ。",v:"09_0096"},{w:"marina",t:"みんな、船室に入って！　戸から顔を出さないで！",v:"09_0097"},{w:null,t:"客たちが船室に入る。"},{w:null,t:"がちゃん。黒い船から、渡し板が一枚、こちらの甲板に下りてくる。"},{w:null,t:"渡し板の上にゼノ。"},{w:null,t:"黒い船のへりに、黒い作業着の男が一人。"},{w:"zeno",t:"狐と、登録のない子は全部もらっていく。",v:"09_0102"},{w:"hero",t:"勝手に人の船に乗ってくんなよ！",v:"09_0104"},{w:"elly",t:"あの輪……ヴィクター一味だよ。",v:"09_0106"},{w:"elly",t:"船室の子たちにも、さわらせないからね！",v:"09_0107"},{w:"zeno",t:"坊主。その狐、持ち主いねえだろ。",v:"09_0109"},{w:"hero",t:"フォルンは、どこにも行かねえよ！",v:"09_0110"},{w:"hero",t:"フォルン！",v:"09_0113"}];
GR_SC.g09_06=[{w:null,t:"三体の光が引き、もとの姿へ。"},{w:null,t:"ヤマト、フォルンの前にしゃがむ。右手をのばしかけて、ばんそうこうの指を見て、止める。"},{w:null,t:"フォルン、その指のにおいを一度だけかぐ。"},{w:null,t:"男の子、右舷のへりで、暗い海を見ている。"},{w:null,t:"エリー、男の子のうしろにしゃがんで、肩を抱く。男の子の手が、エリーの左のそでをつかむ。"},{w:"x",n:"男の子",t:"お姉ちゃん、ひじ……。",v:"09_0186"},{w:"elly",t:"なんでもないよ。",v:"09_0187"},{w:null,t:"エリー、そでを下ろしてひじを隠し、男の子の頭をなでる。"},{w:null,t:"マリナ、船室の戸をあけて、甲板を見回す。"},{w:"marina",t:"みんな、だいじょうぶ？　けがした人はいない？",v:"09_0190"},{w:"elly",f:"serious",t:"……けがした人は、いないよ。",v:"09_0191"},{w:null,t:"エリーの右手は、左のひじのそでを押さえたまま。"},{w:"x",n:"おじいさん",t:"この子の鳥を、持っていかれました。",v:"09_0193"},{w:null,t:"マリナ、黒い船の消えた海を見る。口を結ぶ。"},{w:null,t:"ヤマト、戸口のマリナを見上げる。"},{w:"hero",t:"マリナさん、追っかけられねーの？",v:"09_0196"},{w:"marina",t:"国の札の船だよ。手を出したら、こっちが捕まる。",v:"09_0197"},{w:"alek",t:"あいつ、まだ余裕あったのに引いたよな。",v:"09_0200"},{w:"hero",t:"大会って……あいつも出んのかよ。",v:"09_0201"},{w:"alek",t:"出るかよ。見に来るんだよ、ああいうのは。",v:"09_0202"}];
GR_SC.g09_07=[{w:null,t:"夜明け前。小雨はやんでいる。"},{w:null,t:"客たちは船室の入口で眠っている。"},{w:null,t:"甲板のすみ。"}];
GR_BT[9]={mid:[[{w:null,t:"ゼノ、手首の画面に一度ふれるだけ。"},{w:"x",n:"男の子",t:"待って！",v:"09_0123"},{w:null,t:"エリー、戸口の前で男の子に飛びつき、抱えて戸口の中へ倒れこむ。"},{w:null,t:"エリー、すぐに笑って、そでを下ろしてひじを隠す。"},{w:"alek",t:"くそっ、足もとだ！",v:"09_0129"},{w:"alek",t:"クロベク、突け！　ここなら全部に届く！",v:"09_0130"},{w:"hero",t:"フォルコン、虎に一発だけ！",v:"09_0132"},{w:null,t:"ヤマトの目が、細った炎の帯と、左舷の木箱の山を見比べる。"},{w:null,t:"エリー、戸口から振り返る。目が、木箱の山に行く。"},{w:"elly",t:"ヤマト、箱の上なら——",v:"09_0136"}],[{w:"hero",t:"分かってる。エリー、ピリムサを上げろ！",v:"09_0137"},{w:"elly",t:"うん！　ピリムサ、箱の上から撃って！",v:"09_0138"},{w:"zeno",t:"ラッコン、全部まとめて返せ。",v:"09_0140"},{w:"hero",t:"フォルコン、箱の陰まで下がれ！",v:"09_0142"},{w:null,t:"ゼノ、手首の画面を見たまま、指を一本だけ動かす。ラッコンの目が、走るフォルコンを追う。"},{w:"hero",t:"フォルコン！",v:"09_0146"},{w:null,t:"ヤマトの目が、三体の目を追う。"}],[{w:"zeno",t:"ラッコン、下がってろ。",v:"09_0153"},{w:"hero",f:"serious",t:"……フォルコン？",v:"09_0157"},{w:null,t:"ヤマトの目が、フォルコンの足もとの乾いた板と、二歩先のライガの背中を行き来する。"},{w:null,t:"ヤマト、だまって右手を上げる。"},{w:null,t:"ゼノの手首の画面が光る。"},{w:null,t:"ゼノ、手首の画面にふれる。"},{w:"zeno",t:"……引き上げるぞ。",v:"09_0167"},{w:"zeno",t:"坊主。大会で、また。",v:"09_0169"},{w:"x",n:"男の子",t:"ぼくの鳥！　返して！",v:"09_0174"},{w:null,t:"ヤマト、右舷のへりへ走る。上がっていく渡し板のはしへ、手をのばす。"}]],post:[]};
GR_EP[9]={"t": "船の上", "sc": [["g09_01", "港・マリナの客船（11日目の夕方）", 0], ["g09_02", "夜の海・黒い船（夜のはじめ・同じころ）", 0], ["g09_03", "マリナの客船・甲板（夜のはじめ）", 0], ["g09_04", "甲板（夜ふけ）", 0], ["g09_05", "甲板の勝負", 1], ["g09_06", "勝負のあと（夜ふけ）", 0], ["g09_07", "夜明け前の海", 0]]};
GR_SC.g10_01=[{w:null,t:"夜の海をこえて、マリナの船は白い都の港に着いた。",v:"10_0026"},{w:null,t:"朝の港。白い石の古い倉庫が並ぶ岸壁。"},{w:null,t:"港のうしろの丘。"},{w:null,t:"マリナの船が岸壁につく。"},{w:null,t:"渡し板を下りる三人と三体。"},{w:"marina",t:"大会、がんばんなよ。",v:"10_0031"},{w:"marina",t:"きのうの夜のあれなら、いいとこまで行けるよ。",v:"10_0032"},{w:"hero",t:"いいとこじゃなくて、優勝するんだって。",v:"10_0033"},{w:"marina",t:"そう言う子から、先に負けて帰ってくるんだよ。",v:"10_0034"},{w:null,t:"岸壁の魚の箱のかげから、猫の形の掃除ロボットが出てくる。"},{w:null,t:"フォルン、毛を逆立てて、ヤマトの背中をかけ上がる。"},{w:"hero",t:"お前、まだあいつがこわいのかよ。",v:"10_0037"},{w:null,t:"フォルン、ヤマトの髪を前足でぎゅっとつかむ。"},{w:null,t:"ヤマト、港の沖を見る。"},{w:"hero",t:"あのつるつる頭、ほんとに大会来んのかな。",v:"10_0040"},{w:null,t:"エリーの髪の中で、ピリポンが小さくなっている。顔を出さない。"},{w:"elly",t:"もう来なくていいよ。ピリポン、まだ髪から出てこないもん。",v:"10_0042"},{w:"hero",t:"来たら来たで、今度はちゃんと勝てばいいじゃん。",v:"10_0043"},{w:null,t:"アレク、港の出口の坂を見上げる。"},{w:"alek",t:"受付、朝のうちに閉まるんだぞ。しゃべってないで行こうぜ。",v:"10_0045"},{w:null,t:"第10話　白い都の大会",v:"10_0047"}];
GR_SC.g10_02=[{w:null,t:"白い都。昔の石の町に、きょうは大会の屋台が並んでいる。",v:"10_0053"},{w:null,t:"白い石畳の坂道。"},{w:null,t:"串焼きの屋台では、ロボットの腕が肉を返している。"},{w:null,t:"世界じゅうから来た人とテリオン。"},{w:null,t:"エリー、小さな屋台の前で止まる。"},{w:"elly",t:"アレク、これ大会の時しか売ってないんだって！",v:"10_0058"},{w:"alek",t:"人形は、勝ってからな。",v:"10_0059"},{w:"elly",f:"surprised",t:"ほんと！？　約束だよ。",v:"10_0060"},{w:null,t:"エリー、人形を台にもどす。店番のロボットに、小さく手をふる。"},{w:null,t:"三人、坂を上がっていく。"},{w:"hero",t:"アレクだって止まってんじゃん。",v:"10_0063"},{w:"alek",t:"これは飯だろ。人形とはちがうって。",v:"10_0064"},{w:"elly",f:"serious",t:"……勝ってからじゃないんだ。",v:"10_0065"},{w:null,t:"アレク、聞こえないふりで、カードを読み取りの板に当てる。"}];
GR_SC.g10_03=[{w:null,t:"坂の上がひらける。"},{w:null,t:"入口に、案内のロボットと、宙に浮かぶ受付の画面。"},{w:null,t:"入口のとなりに、白い石の小さな建物。"},{w:null,t:"窓口の前に、9話の船のおじいさんと男の子。"},{w:null,t:"カウンターの光る板に、鳥の子の写真と、赤い字「回収ずみ　登録なし」。"},{w:"x",n:"係の人",t:"登録がないので、お返しできません。",v:"10_0074"},{w:null,t:"おじいさん、男の子の肩に手を置いて、係の人に頭を下げる。"},{w:null,t:"受付の列のヤマト、それを見ている。"},{w:null,t:"ヤマトの頭の上で、フォルンも耳を立てて、窓口の方を見ている。"},{w:"x",n:"受付のロボット",t:"白い都テリオン大会へ、ようこそ。三体までの部ですね。",v:"10_0078"},{w:"x",n:"受付のロボット",t:"組の名前を、どうぞ。",v:"10_0079"},{w:"hero",t:"チーム・フォルンで！",v:"10_0080"},{w:"elly",t:"えー、ピリポンとクロッコも入れてよ。",v:"10_0081"},{w:null,t:"二人がもめているあいだに、アレクが受付の画面に指で打ちこんでいる。"},{w:"x",n:"受付のロボット",t:"「オリーヴァ村」で、受け付けました。",v:"10_0083"},{w:"hero",t:"おい、勝手に決めんなよ！",v:"10_0084"},{w:"alek",t:"名前でもめてるうちに、受付が閉まるだろ。",v:"10_0085"},{w:null,t:"アレク、カードを当てる。"},{w:null,t:"受付のロボットが、こちらの三体の首元に、順に光をかざす。"},{w:"x",n:"受付のロボット",t:"登録のない子は、大会のあいだだけ仮の札です。",v:"10_0088"},{w:"x",n:"受付のロボット",t:"組が負けたら、札は外れます。",v:"10_0089"},{w:"x",n:"受付のロボット",t:"開会式のあと、すぐに1回戦です。選手の入口へどうぞ。",v:"10_0092"}];
GR_SC.g10_04=[{w:null,t:"【ここから一つながりのカメラ】"},{w:null,t:"満員の客席。"},{w:null,t:"選手の入口に、三人と三体。"},{w:"x",n:"実況（場内の声）",t:"協賛の会社より、ごあいさつをいただきます。",v:"10_0099"},{w:null,t:"大きな画面に、協賛の会社の名前と印だけが出る。顔は映らない。"},{w:null,t:"カメラ、客席の上を貴賓席へ。"},{w:"victor",t:"白い都へ、ようこそ。",v:"10_0102"},{w:"victor",t:"今年も、世界じゅうから強い子が来てくれました。",v:"10_0103"},{w:"victor",t:"国の決まりで、優勝した子は年れいを問いません。",v:"10_0104"},{w:"victor",t:"相棒の持ち主として、登録できます。",v:"10_0105"},{w:null,t:"拍手。カメラ、客席を横に流れて、選手の入口のアレクへ。"},{w:null,t:"クロッコの頭をなでていたアレクの手が、止まる。"},{w:"victor",t:"今年も、いい試合を見せてください。",v:"10_0108"},{w:null,t:"アレクの目だけが、声の出どころの貴賓席へ上がる。"},{w:null,t:"アレク、パーカーのポケットから古い望遠鏡を出して、貴賓席に向ける。"},{w:null,t:"望遠鏡の丸い中。手をあげて拍手にこたえる、30歳くらいの男。"},{w:null,t:"白いスーツの胸ポケットから、角のすり切れた小さな古い単語帳がのぞいている。"},{w:"hero",t:"エリー、あそこ。船のつるつる頭、ほんとに来てるぞ。",v:"10_0118"},{w:"elly",f:"surprised",t:"えっ、どこ？",v:"10_0119"},{w:"x",n:"実況（場内の声）",t:"それでは1回戦、第一試合！　北欧代表、オーラ選手の組！",v:"10_0120"},{w:"x",n:"実況（場内の声）",t:"対するは地元ギリシャ、オリーヴァ村の三人！",v:"10_0121"},{w:"alek",t:"どこでもいいだろ。ほら、呼ばれてんぞ。",v:"10_0123"}];
GR_SC.g10_05=[{w:null,t:"向かい合う。"},{w:"x",n:"実況（場内の声）",t:"北欧のオーラ選手、三体とも、今日が初めての大会です！",v:"10_0129"},{w:"x",n:"実況（場内の声）",t:"頭に印のある子がリーダー。倒れたら負けです！",v:"10_0130"},{w:null,t:"審判の合図。"},{w:"hero",t:"フォルン！",v:"10_0132"},{w:null,t:"エリーとアレクも、だまって画面にふれる。"},{w:null,t:"光が引くと、クロベクの頭の上に、小さな印。"},{w:"alek",t:"氷も森も、炎には弱えぞ。",v:"10_0135"},{w:null,t:"ペンギーとアロピコが、ポチャラシのひと鳴きで、そろって向きを変える。ヤマトの目が、その頭の上の印に止まる。"},{w:null,t:"ポチャラシ、フロス。"},{w:"hero",f:"surprised",t:"フォルコン、アザラシだけ狙え！",v:"10_0138"},{w:"aura",t:"……もう？",v:"10_0141"}];
GR_SC.g10_06=[{w:null,t:"光が引いて、三体とも小さな姿にもどる。"},{w:null,t:"選手の通路の出口。"},{w:"x",n:"子ども",t:"狐のお兄ちゃん、サインちょうだい！",v:"10_0146"},{w:"hero",t:"え、おれ？　……しょうがないなあ。並んで並んで。",v:"10_0147"},{w:null,t:"ヤマト、子どもの画面に、指で大きくサインを書く。"},{w:"hero",t:"次の試合も30秒で終わらせるから、ちゃんと見ててよ。",v:"10_0149"},{w:"x",n:"子ども",t:"狐にも、サインしてもらって！",v:"10_0150"},{w:null,t:"子どもが、画面をフォルンの鼻先に向ける。"},{w:"hero",t:"こいつ、そういうのやらないんだよ。……足だけ貸してやるか。",v:"10_0152"},{w:null,t:"ヤマト、フォルンの前足をつまんで持ち上げ、子どもの画面に押しつけようとする。"},{w:null,t:"フォルン、身をよじって手から抜ける。そのままヤマトの顔に跳びつき、すすけた前足で、ほっぺを、ぎゅっとふんで頭の上へ上がる。"},{w:null,t:"ヤマトのほっぺに、黒いすすの足あとが一つ、くっきり。"},{w:null,t:"子どもたち、きゃあきゃあ笑って、その顔を画面でとって逃げていく。"},{w:"alek",t:"嫌がってる子の足を、勝手に持つからだろ。",v:"10_0157"},{w:"elly",t:"ヤマト、ほっぺに足あとついてるよ。写真とっていい？",v:"10_0158"},{w:"hero",t:"とるなって！",v:"10_0159"},{w:null,t:"エリー、もう手首の画面をヤマトに向けている。"},{w:null,t:"通路の先、大きな空中の画面から、地鳴りのような歓声。"},{w:null,t:"画面の中、別の試合。"},{w:"x",n:"実況（場内の声）",t:"まん中の子は、どちらとも組めます！",v:"10_0164"},{w:"hero",f:"surprised",t:"なんだ、今の！？",v:"10_0167"},{w:"alek",t:"融合だ。本物は、おれも初めて見た。",v:"10_0168"}];
GR_SC.g10_07=[{w:null,t:"競技場の裏。"},{w:null,t:"エリーが、休み場の台から、大会が選手に配る軽食の包みを三つもらってくる。"},{w:null,t:"ヤマトのうしろ、裏の門が、音もなく開く。"},{w:null,t:"エリーの足が止まる。笑顔は、そのまま。"},{w:null,t:"ヤマト、エリーの顔を見る。"},{w:null,t:"エリー、くるっと前を向いて、ふつうに歩いてくる。"},{w:"elly",t:"はい、ヤマトの分。",v:"10_0179"},{w:"hero",f:"serious",t:"……おう。",v:"10_0180"},{w:"hero",t:"あれ、ヴィクターの車だろ。なんで大会に入れんだよ。",v:"10_0184"},{w:"alek",t:"あれも、国の仕事の車なんだよ。",v:"10_0185"},{w:"hero",f:"serious",t:"……なんだよ、それ。",v:"10_0186"},{w:"x",n:"実況（場内の声）",t:"2回戦が始まります。オリーヴァ村の三人は、床へどうぞ。",v:"10_0188"}];
GR_SC.g10_09=[{w:null,t:"選手の通路。"},{w:null,t:"通路の出口に、係のロボット。"},{w:null,t:"タリク、パオッコを両腕で抱き上げる。"},{w:null,t:"ヤマト、立ち止まる。"},{w:null,t:"ヤマト、出口の向こう、競技場の入口のとなりの白い窓口の方を、一回だけ見る。"},{w:null,t:"エリーとアレクが、先の控え室の戸口でふり向いて、ヤマトを待っている。"}];
GR_SC.g10_10=[{w:null,t:"競技場の下の、古い石の壁の控え室。"},{w:null,t:"三体は小さな姿にもどっている。"},{w:"hero",t:"次、中国だって。あと二つで優勝じゃん。",v:"10_0282"},{w:"alek",t:"浮かれてると、また顔ふまれるぞ。",v:"10_0283"},{w:null,t:"アレク、クロッコの背中を布でふく。"},{w:null,t:"控え室の戸口に、白いスーツの男が立っている。"},{w:null,t:"男、胸に手を当てて、軽く一礼する。"},{w:null,t:"ヤマトとエリーが、顔を上げて戸口を見る。"},{w:null,t:"アレクだけが、顔を上げない。"}];
GR_BT[10]={mid:[[{w:null,t:"タリク、砂よけの帽子に、長い布を首に巻いた14歳。足もとに、灰色の小さな象の子パオッコ（頭にリーダーの印）、小さなアルマジロのアルマド、赤いしっぽの小さなサソリのヒソリン。"},{w:null,t:"タリクの目が、フォルンの首元の黄色い輪に止まる。"},{w:"tarik",t:"その狐も、仮の札か。",v:"10_0202"},{w:"hero",t:"そっちもだろ。",v:"10_0203"},{w:"tarik",t:"ああ。優勝して、こいつらの登録を取る。",v:"10_0204"},{w:"hero",t:"優勝すんのは、こっちだって。",v:"10_0205"},{w:"x",n:"審判",t:"始め！",v:"10_0206"},{w:null,t:"タリク、手首の画面にふれる。"},{w:null,t:"アレク、象とアルマジロをあごで指す。"}],[{w:"alek",t:"石の床だと、あいつら硬えぞ。",v:"10_0209"},{w:"hero",t:"フォルコン、穴に近づくな。下がって、前の床ぜんぶ見てろ。",v:"10_0212"},{w:null,t:"ヤマトの目は、穴Aのまわりの石のすき間を順に追っている。"},{w:null,t:"エリーの声で、ピリムサがヒノサソリへスパークショット。"},{w:"hero",t:"フォルコン！",v:"10_0224"},{w:"alek",t:"あの古い穴に逃げこんだのか！",v:"10_0232"},{w:null,t:"ヤマト、くちびるをかむ。倒れたフォルコンから目をそらす。"},{w:null,t:"ヤマトの目が、一瞬だけ、となりのエリーの靴のかかとへ行く。"},{w:"hero",t:"ちがう、あの穴から出てきたんだ。",v:"10_0236"},{w:"hero",t:"かかとで砂をけってる。うしろ向きに歩いたんだよ。",v:"10_0237"}],[{w:"hero",t:"次も、あの古い穴から来る。",v:"10_0238"},{w:null,t:"ヤマト、陣のはしで片膝をつき、膝の横で手のひらを小さく下に向ける（そこにいろ）。"},{w:null,t:"ヤマト、そこで口を閉じて、エリーとアレクの方を向く。"},{w:"elly",t:"ピリムサ、あの穴の前に立って。わざと見えるように。",v:"10_0243"},{w:"alek",t:"ピリムサじゃ、あいつの土の技はきついぞ！",v:"10_0244"},{w:"elly",t:"分かってる。目の前にいたら、ピリムサしか見ないでしょ。",v:"10_0245"},{w:"alek",t:"クロベク、穴の横に回れ。正面じゃなくて、横だ。",v:"10_0246"},{w:"tarik",t:"パオドン、雷の子だ！",v:"10_0258"}]],post:[{w:null,t:"パオドン、しっぽをかまれたまま、目の前のピリムサへもう一度ガイアガ。"},{w:"alek",t:"クロベク、決めろ！",v:"10_0260"},{w:null,t:"クロベクの背中の筋が、もう一本光ってあごへ流れる。"},{w:null,t:"クロベクの背中に残った青い筋は、一本だけ。"}]};
GR_EP[10]={"t": "白い都の大会", "sc": [["g10_01", "白い都の港（朝）", 0], ["g10_02", "屋台の町（朝）", 0], ["g10_03", "古い競技場の受付（朝）", 0], ["g10_04", "開会（一つながりのカメラ）", 0], ["g10_05", "1回戦（30秒以内）", 0], ["g10_06", "選手の通路（1回戦のあと）", 0], ["g10_07", "競技場の裏の休み場（2回戦の前）", 0], ["g10_08", "2回戦", 1], ["g10_09", "選手の通路（2回戦のあと）", 0], ["g10_10", "控え室（2回戦のあと）", 0]]};
GR_SC.g11_01=[{w:null,t:"大会の二日目。三人は、アレクが見つけた一番安い宿で朝を迎えた。",v:"11_0024"},{w:null,t:"古い石の建物の上の階。"},{w:null,t:"ヤマト、寝棚の上であぐらをかいて、手首の画面を見ている。"},{w:"hero",t:"エリー、見ろよ。きのうの2回戦、ニュースになってる！",v:"11_0027"},{w:null,t:"空中の画面。"},{w:"hero",t:"なんでこっちの方が見られてんだよ！",v:"11_0029"},{w:"alek",t:"そりゃ、こっちの方が分かりやすいだろ。",v:"11_0030"},{w:null,t:"窓のへりで、フォルンがしっぽの火でオリーブを焼いている。"},{w:null,t:"宿の台所のロボットが、いちばん安い朝ごはんの盆（パンと、はちみつのヨーグルト）を出す。"},{w:"elly",t:"ほら、ご飯先。準決勝の前なんだから、ちゃんと食べて。",v:"11_0033"},{w:null,t:"ピリポンが、エリーのヨーグルトのふたを、はしからなめている。"},{w:null,t:"アレク、パンをかじりながら、自分の手首の画面で大会の対戦表を見ている。"},{w:"alek",t:"きょうの相手、中国の道場の子らしいぞ。",v:"11_0036"},{w:"alek",t:"ここまで、一体も倒されずに勝ってきてる。",v:"11_0037"},{w:"hero",t:"じゃあ、おれたちが最初に倒せばいいんじゃん。",v:"11_0038"},{w:null,t:"第11話　準決勝",v:"11_0040"}];
GR_SC.g11_02=[{w:null,t:"競技場の下の、石の壁の通路。"},{w:null,t:"すれちがいざま、カマコロがハオの肩からひょいと床に下りる。"},{w:null,t:"フォルンの毛が、ぶわっと逆立つ。"},{w:null,t:"カマコロ、かまを二本とも上げて、フォルンの顔の前で止まる。"},{w:"hero",t:"おい、フォルン！　まだ始まってないって！",v:"11_0050"},{w:null,t:"ハオ、すっとしゃがんで、カマコロを手のひらにすくう。"},{w:"hao",t:"すみません。この子、気になる相手には、すぐさわるんです。",v:"11_0052"},{w:"hero",t:"こっちは、さわられると怒るやつなんだよ。",v:"11_0053"},{w:null,t:"ハオ、ヤマトを見る。目がヤマトの顔から、足もとへ下りる。"},{w:null,t:"ハオの耳もとで、翻訳の小さな光がまたたいている。"},{w:"hao",t:"翻訳機、使ってないんですか。",v:"11_0058"},{w:"elly",t:"うん。なんか、聞いたら分かるの。",v:"11_0059"},{w:"elly",t:"フォルン、勝負の前から負けず嫌いだね。",v:"11_0063"},{w:"hero",t:"負けず嫌いなのは、向こうのかまきりの方だろ。",v:"11_0064"}];
GR_SC.g11_03=[{w:null,t:"準決勝のために、競技場の床には、古い水の溝が開けられていた。",v:"11_0067"},{w:null,t:"競技場のまん中。"},{w:null,t:"相手の陣の前。"},{w:null,t:"選手の入口から床に出たヤマト、だまって一枚石のそばにしゃがむ。"},{w:null,t:"ヤマト、一枚石の外のへりに、手のひらをついて体重をかける。"},{w:null,t:"フォルン、石の外のへりに、ぴょんと跳び乗る。"},{w:null,t:"フォルン、毛を逆立てて跳び降りる。"},{w:"x",n:"実況（場内の声）",t:"選手は、陣へ戻ってください。",v:"11_0075"},{w:null,t:"ヤマト、立ち上がって、こちらの陣へ戻る。"},{w:null,t:"貴賓席。日よけの下で、白いスーツの男が座っている。"},{w:null,t:"選手の入口で、アレクが一度だけ貴賓席を見上げる。すぐに目をそらして、クロッコを溝の近くへ下ろす。"},{w:"x",n:"実況（場内の声）",t:"準決勝、第一試合！　中国代表、ハオ選手の組！",v:"11_0079"},{w:"x",n:"実況（場内の声）",t:"対するは、オリーヴァ村の三人！",v:"11_0080"}];
GR_SC.g11_05=[{w:null,t:"光が引いて、三体とも小さな姿にもどる。"},{w:null,t:"ハオ、倒れたホエマルを両手でかかえ上げて、溝の水にそっと浸けてやる。"},{w:null,t:"ヤマト、フォルンを両手で持ち上げようとする。"},{w:null,t:"エリーのひざの上で、ピリポンが毛のしずくを放電で飛ばす。"},{w:null,t:"ハオの肩のカマコロと、ヤマトの頭の上のフォルン。目が合う。"},{w:null,t:"ハオ、カマコロの頭を指でおさえて、ヤマトに礼をする。今度は、ヤマトの足もとではなく、顔を見て。"},{w:"hao",t:"竹の森に来たら、案内します。",v:"11_0179"},{w:"hero",t:"竹の森って、どこにあんの？",v:"11_0180"},{w:"hao",t:"中国の、ずっと山の方です。画面に送っておきます。",v:"11_0181"},{w:null,t:"ハオ、反対側の入口へ歩いていく。"},{w:null,t:"ヤマトの手首の画面が、ぴろんと鳴る。"},{w:null,t:"貴賓席。日よけの下の席は、もう空いている。"}];
GR_SC.g11_06=[{w:null,t:"通路の壁の大きな空中の画面。"},{w:null,t:"相手の三体のうち、バジリクの方を見ていた二体から色が抜けて、灰色に止まる。顔をそむけていた一体だけは、色が抜けない。"},{w:null,t:"ヤマトの目が、画面の、色の抜けなかった一体に止まる（1カット・台詞なし）。"},{w:"x",n:"実況（場内の声）",t:"決勝は、あすの午後！",v:"11_0190"},{w:"x",n:"実況（場内の声）",t:"オリーヴァ村の三人　対　前回の優勝者、レン選手！",v:"11_0191"},{w:"x",n:"実況（場内の声）",t:"レン選手は、今年も一人と一体で勝ち上がってきました！",v:"11_0192"},{w:null,t:"画面に、決勝の組み合わせ。"},{w:null,t:"通路の向こうから、レンが一人で歩いてくる。"},{w:null,t:"ヤマト、立ち止まる。"},{w:null,t:"レン、ヤマトの横を通りすぎる。"},{w:null,t:"ヤマト、ふり向く。"},{w:null,t:"ヤマトの頭の上で、フォルンが耳を立てて、レンの去った方を見ている。"}];
GR_BT[11]={mid:[[{w:null,t:"ハオ、拳を手のひらに当てて礼。"},{w:"hao",t:"もう、足が前に出てますよ。",v:"11_0091"},{w:null,t:"ヤマトのつま先が、陣の線から半分はみ出している。"},{w:"hero",f:"serious",t:"……出てねえし。",v:"11_0093"},{w:"x",n:"審判",t:"始め！",v:"11_0095"},{w:null,t:"ハオが両手を横に開き、三人が手首の画面にふれる。"},{w:"hero",t:"あれ、マリナさんとこのと同じクジラじゃん。",v:"11_0098"},{w:"alek",t:"溝のそばは、水の子が強え。クジラに気をつけろ！",v:"11_0099"},{w:"hero",f:"serious",t:"……フォルコン、まだだ。",v:"11_0101"}],[{w:"alek",t:"クロベク、溝に入れ！",v:"11_0102"},{w:"hao",t:"カマケン、溝のワニを。",v:"11_0108"},{w:"hero",t:"そこだ、フォルコン！",v:"11_0118"},{w:"hao",t:"カマケン、狐を。",v:"11_0119"},{w:null,t:"ハオの手首の画面。"},{w:"alek",t:"溝のそばだと、大波が来るぞ！",v:"11_0129"},{w:null,t:"ヤマトの目は、ホエリオスの腹の下の一枚石。"},{w:null,t:"エリーの目も、同じ石へ。表面に彫られた古い字を、エリーの口が小さくなぞる（古い字の寄り・字幕なし）。"},{w:null,t:"アレクの目が、貴賓席へ跳ねる。"},{w:"hero",t:"（エリーに身を寄せて、小声で）反対が立つんだ。さっき押したら、動いた。",v:"11_0137"}],[{w:"hero",t:"（小声で）ピリムサを的にしてくれ。",v:"11_0138"},{w:null,t:"エリー、ヤマトの顔を見る。"},{w:"elly",t:"ピリムサ、あの石の向こうの端で待って！",v:"11_0140"},{w:"alek",t:"そこ、大波の的だぞ！",v:"11_0142"},{w:"elly",t:"（アレクに身を寄せて、小声で）うん。的なの。",v:"11_0143"},{w:"hero",t:"フォルコン、そこで待ってろ。",v:"11_0144"},{w:null,t:"ハオの目が、二つを見る（1カット）。"},{w:"hao",t:"ホエリオス、前へ。",v:"11_0147"}]],post:[{w:null,t:"ホエリオスの大きな体が、傾いた石の上をすべり落ちる。"},{w:null,t:"ホエリオス、口を開ける。"},{w:"elly",t:"ピリムサ、今！",v:"11_0157"},{w:null,t:"ホエリオスのすぐ横に、跳び降りたピリムサ。"},{w:"hao",t:"ホエリオス、雷の子を。",v:"11_0162"}]};
GR_EP[11]={"t": "準決勝", "sc": [["g11_01", "安い宿（朝）", 0], ["g11_02", "競技場の選手の通路（昼前）", 0], ["g11_03", "古い石の床に、水の溝（昼）", 0], ["g11_04", "準決勝", 1], ["g11_05", "勝負のあと（床のはし）", 0], ["g11_06", "客席の下の通路（準決勝、第二試合のあと）", 0]]};
GR_SC.g12_01=[{w:null,t:"決勝の前の夜。白い都の屋根の上に、細い月が出ていた。",v:"12_0025"},{w:null,t:"宿の廊下の小さな窓辺。"},{w:"elly",t:"お姉ちゃん、あしたね、決勝なんだよ。",v:"12_0027"},{w:"ana",t:"決勝！？　村のみんなに言わなきゃ。ロビーの画面で流すからね。",v:"12_0028"},{w:"elly",t:"えー、やめてよ。はずかしいもん。",v:"12_0029"},{w:"ana",t:"そんなことより、ちゃんと食べた？",v:"12_0030"},{w:"elly",t:"食べたよ。アレクが、安い串のお店を見つけてくれたの。",v:"12_0031"},{w:"ana",t:"あの子、ほんとに安いとこ見つけるのがうまいね。",v:"12_0032"},{w:"elly",t:"うん。そのかわり、人形は買ってくれないけどね。",v:"12_0033"},{w:null,t:"声の波形が、笑い声で大きくゆれる。"},{w:null,t:"部屋。明かりを落とした中。"},{w:null,t:"ヤマトだけ、寝棚の上に座っている。"},{w:null,t:"ヤマトの画面。閉じた目の絵。"},{w:null,t:"アレク、寝返りを打って、ヤマトの背中を見る。"},{w:"alek",t:"まだ起きてんのかよ。あしたは決勝なんだぞ、早く——",v:"12_0039"},{w:null,t:"アレク、体を起こして、ヤマトの画面をのぞく。閉じた目の絵が、何枚も。"},{w:null,t:"アレク、口を閉じる。"},{w:null,t:"窓のへりで丸くなっていたフォルンが、片目だけあけて、ヤマトの指の動きを見ている。"},{w:null,t:"第12話　決勝",v:"12_0044"}];
GR_SC.g12_02=[{w:null,t:"大会の三日目。決勝の客席は、上の方の席まで人でうまっていた。",v:"12_0050"},{w:null,t:"満員の客席。"},{w:null,t:"床の水の溝は、石のふたでふさがれている。"},{w:null,t:"貴賓席。日よけの下に、白いスーツの男。"},{w:"x",n:"実況（場内の声）",t:"白い都テリオン大会、決勝！",v:"12_0055"},{w:"x",n:"実況（場内の声）",t:"前回の優勝者、レン選手！",v:"12_0056"},{w:null,t:"向こうの入口から、レンが一人で歩いてくる。"},{w:"x",n:"実況（場内の声）",t:"対するは、オリーヴァ村の三人！",v:"12_0058"},{w:null,t:"選手の入口の横に、テリオン用の水の鉢。"},{w:null,t:"三人が出る。ヤマトは、レンの足もとのバジリクから目を離さない。"}];
GR_SC.g12_04=[{w:null,t:"フォルレオンの光が引き、小さなフォルンに。"},{w:null,t:"大きな画面の勝ち残りの表から、レンの名前の光がすっと消える。"},{w:null,t:"レン、しゃがんだまま、その画面を見上げる。"},{w:null,t:"レン、立ち上がる。"},{w:"hero",f:"serious",t:"……またやろうぜ、レン。",v:"12_0148"},{w:null,t:"レン、振り向かずに手を一回だけ上げる。"}];
GR_SC.g12_05=[{w:null,t:"大会の優勝者は、年れいにかかわらず、持ち主として登録できる。",v:"12_0152"},{w:null,t:"床のまん中に、白い小さな台。係の人（2100年の白っぽい制服）が、空中に光の窓口を開く。"},{w:"x",n:"係の人",t:"持ち主の登録です。手首を、窓口にかざしてください。",v:"12_0154"},{w:null,t:"ヤマト、左の手首をかざす。"},{w:null,t:"板の上のすみに、小さな字が出る。"},{w:null,t:"エリーの目が、その字に止まる。"},{w:null,t:"ヤマト、ひざの上のフォルンを床に下ろす。"},{w:null,t:"フォルン、においもかがずに、くるっとうしろを向く。"},{w:null,t:"客席が、どっと笑う。"},{w:null,t:"ヤマト、板を差し出していた手を、ゆっくり下ろす。"},{w:"hero",f:"serious",t:"……いいよ、別に。",v:"12_0162"},{w:null,t:"ヤマト、窓口に背を向けて、歩き出す。"},{w:null,t:"エリーが、一歩前に出かけて、止まる。アレクは腕を組んだまま、動かない。"},{w:null,t:"フォルン、走る。"},{w:null,t:"下ろしたままのヤマトの手のひらに、ぴょんと跳び乗る。"},{w:null,t:"ヤマトの足が止まる。"},{w:null,t:"フォルン、ヤマトの手のひらの上から、手首の横に浮かぶ光の板へ、前足をのばす。"},{w:null,t:"板が光る。字が変わる。"},{w:null,t:"フォルンの首元の黄色い輪（仮の札）が消えて、かわりに小さな光の点がともる。"},{w:null,t:"客席が、一拍遅れて、わっと沸く。"},{w:null,t:"フォルン、ヤマトの手のひらの上で、もう知らん顔をして、前足をなめている。"}];
GR_SC.g12_06=[{w:"x",n:"実況（場内の声）",t:"優勝、オリーヴァ村！　協賛の会社より、盾が贈られます！",v:"12_0175"},{w:null,t:"貴賓席から、白いスーツの男が床へ下りてくる。いつもの笑顔。"},{w:null,t:"男、ヤマトの前に立つ。"},{w:"victor",t:"優勝、おめでとう。いい狐を連れてるね。",v:"12_0178"},{w:null,t:"男、ヤマトの肩の上のフォルンに、手をのばしかける。"},{w:null,t:"フォルン、白いスーツをにらんで、のどの奥で低くうなる。"},{w:null,t:"男、手を止めて、笑ったまま引っこめる。"},{w:"victor",t:"おっと。白い服は、きらいか。",v:"12_0182"},{w:null,t:"男、付き人から盾を受け取って、ヤマトに渡す。"},{w:null,t:"男、アレクの前へ。手を差し出す。"},{w:"victor",t:"きみも、おめでとう。",v:"12_0186"},{w:"alek",t:"……ありがとうございます。",v:"12_0187"},{w:"victor",t:"きみ、才能あるね。",v:"12_0191"},{w:"elly",t:"ありがとうございます！",v:"12_0192"}];
GR_SC.g12_07=[{w:null,t:"係の人が、アレクの差し出したカードに、光の板を当てる。"},{w:null,t:"フォルン、ヤマトの肩の上から、盾のふちをかじっている。"}];
GR_SC.g12_08=[{w:null,t:"その夜。白い都の屋台の町は、遅くまで明かりが消えなかった。",v:"12_0206"},{w:null,t:"屋台の長い机。"},{w:null,t:"アレク、串にも手をつけずに、カードの残高の数字を見ている。"},{w:"hero",f:"surprised",t:"まだ数えてんの！？　盾もらったの、昼だぞ。",v:"12_0209"},{w:"alek",t:"けたが多いと、何回数えても落ちつかねえんだよ。",v:"12_0210"},{w:"elly",t:"それで、ちゃんと入ってた？",v:"12_0211"},{w:"alek",t:"一万ジェムコイン。……ちゃんと入ってる。",v:"12_0212"},{w:null,t:"アレク、カードをパーカーの内ポケットにしまう。"},{w:null,t:"エリーは、大会の初日に買えなかった大会限定の光る人形を、手のひらにのせて、にこにこしている。"},{w:"hero",t:"それ、アレクが買ったの？",v:"12_0215"},{w:"alek",t:"勝ったら、って言ったろ。……今日だけだぞ。",v:"12_0216"},{w:null,t:"エリー、人形をアレクの顔の前に突き出して、にこっとする。"},{w:"hero",t:"串、みんなにもう一本ずつ！　きょうはおれのおごり！",v:"12_0218"},{w:"alek",t:"まだ山分けしてねえだろ、それ。",v:"12_0219"},{w:"hero",t:"じゃあ、フォルンのおごり！",v:"12_0220"},{w:null,t:"店のロボットの腕が、串を一本ずつ、みんなの皿にのせる。ヤマトが手をのばす前に、フォルンがヤマトの皿の串をしっぽの火で焼き直して、くわえて持っていく。"},{w:"hero",t:"おい、それおれの！",v:"12_0222"},{w:null,t:"エリーが笑う。"},{w:null,t:"フォルンの首元の、小さな登録の光が、屋台の明かりの中でちらちら光っている。"},{w:null,t:"港。屋台の明かりのとどかない、沖の暗がり。"}];
GR_BT[12]={mid:[[{w:null,t:"レン、手首の画面を見ずに立つ。地面から顔を出すバジリク。"},{w:null,t:"ヤマトの手首の画面の端に、きのうの夜描いた絵が一瞬（閉じた目の絵がいくつも）。"},{w:"x",n:"審判",t:"始め！",v:"12_0068"},{w:null,t:"三人がだまって手首の画面にふれる。"},{w:"hero",t:"フォルコン、一番うしろにいてくれ。",v:"12_0070"},{w:"hero",t:"エリー、アレク、二体は左右に離してくれ。",v:"12_0071"},{w:"elly",t:"分かった。ピリムサ、左ね！",v:"12_0072"},{w:"alek",t:"は？　お前、前に出ないのかよ。",v:"12_0073"}],[{w:"hero",t:"いいから。",v:"12_0074"},{w:"alek",t:"岩には水だろ！　クロベク、突け！",v:"12_0077"},{w:null,t:"レンは、画面も見ずに、バジリクの背中だけを見ている。"},{w:"dimi",t:"魔眼封石（まがんロック）。",v:"12_0083"},{w:"alek",t:"クロベク！",v:"12_0085"},{w:null,t:"ヤマト、フォルコンの真うしろ、数歩はなれた所で膝をつく。手のひらを開いて、顔の高さに上げる。"},{w:"hero",t:"フォルコン、待ってくれ。",v:"12_0091"}],[{w:"dimi",f:"serious",t:"……見ないんだね。",v:"12_0097"},{w:null,t:"レン、手首の画面を初めて見る。"},{w:null,t:"レンの目が、光りはじめたフォルコンと、ヤマトの手のひらを往復する。"},{w:"dimi",f:"serious",t:"……そう。",v:"12_0102"},{w:null,t:"ヤマトの目が床へ落ちる。"},{w:null,t:"ヤマト、自分の手首の画面の閉じた目の絵を一度だけ見る。"},{w:"hero",t:"フォルコン、前見てろ。合図したら、すぐ行け。",v:"12_0108"},{w:"elly",t:"見てたら、目が合っちゃうよ！",v:"12_0109"},{w:"hero",t:"出た時、あいつは目をつぶるんだ。",v:"12_0110"},{w:null,t:"ヤマト、手のひらを下ろして、膝をついたまま、さらに数歩うしろへ下がる。"}],[{w:"elly",t:"ピリムサ、一回だけでいい！　目は見ないで、足もとを見てて！",v:"12_0114"},{w:"alek",t:"クロベク、回りこめ。出た所を横から突くぞ。",v:"12_0115"},{w:null,t:"ヤマト、手首の画面にふれる。"},{w:"hero",t:"フォルコン！",v:"12_0119"},{w:"dimi",t:"魔眼――",v:"12_0126"},{w:null,t:"レンの口が、言いかけたまま止まる。"},{w:"hero",t:"フォルレオン、今だ！",v:"12_0129"},{w:null,t:"ヤマトの声で、フォルレオンが跳ぶ。"}]],post:[{w:null,t:"バジリクが目を開けかける。"},{w:null,t:"審判の旗。観客席が一拍遅れて爆発する。"},{w:null,t:"レン、倒れたバジリクの頭の横にしゃがみ、手をのせる。"}]};
GR_EP[12]={"t": "決勝", "sc": [["g12_01", "宿（決勝の前の夜）", 0], ["g12_02", "決勝の日の競技場（午後）", 0], ["g12_03", "決勝", 1], ["g12_04", "勝負のあと（表示と、名前を呼ぶ）", 0], ["g12_05", "登録の窓口", 0], ["g12_06", "表彰", 0], ["g12_07", "表彰のあと（賞金）", 0], ["g12_08", "お祝いの夜（屋台の町）", 0]]};
GR_SC.g13_01=[{w:null,t:"大会が終わった夜。港のそばの屋台の町は、お祭りだった。",v:"13_0025"},{w:null,t:"港のそばの屋台の町。"},{w:null,t:"屋台が並ぶ。"},{w:null,t:"通りのまん中の空中の画面に、きょうの決勝がくり返し流れている。"},{w:null,t:"屋台の長い机。"},{w:null,t:"ヤマトのまわりに、子どもたちが五、六人。"},{w:"x",n:"屋台の子ども",t:"ねえ、優勝した狐って、この子？",v:"13_0031"},{w:"hero",t:"そうだよ。今は寝てるけどな。",v:"13_0032"},{w:"x",n:"屋台の子ども",t:"決勝の火、すごかった！　ねえ、さわってもいい？",v:"13_0033"},{w:"hero",t:"こいつに聞いて。",v:"13_0034"},{w:null,t:"ヤマト、左の手のひらを上にして、フォルンの前に置く。"},{w:null,t:"フォルン、片目をあける。"},{w:null,t:"フォルン、女の子の手のひらに、前足をぽんとのせる。"},{w:null,t:"女の子が、きゃあっと跳びはねる。子どもたち、わっと笑う。"},{w:null,t:"ヤマトも、声を出して笑う。"},{w:null,t:"机の向かいで、アレクが肉の串をかじったまま、口のはしだけで笑う。"},{w:null,t:"フォルン、何もなかった顔で、また丸くなる。"},{w:"hero",t:"エリー、あっちのくじ引こうぜ。今日は当たる気がする。",v:"13_0044"},{w:"elly",t:"ほら、ご飯先。くじは、そのあとね。",v:"13_0045"},{w:"alek",t:"……なんでおれのだけ、一本多いんだよ。",v:"13_0048"},{w:"elly",t:"アレク、今日いっぱい頭使ってたもん。おなかへったでしょ。",v:"13_0049"},{w:"alek",t:"……べつに、へってねえよ。",v:"13_0050"},{w:"elly",t:"ジュース、おかわりもらってくるね。",v:"13_0053"},{w:"elly",t:"優勝した人は、ただなんだって。",v:"13_0054"}];
GR_SC.g13_02=[{w:null,t:"飲み物の屋台。"},{w:null,t:"エリー、列に並ぶ。"},{w:null,t:"となりに、黒い影。"},{w:"kasia",t:"エリーさんね。優勝、おめでとう。",v:"13_0061"},{w:"elly",f:"surprised",t:"ありがとう！　……えっと、どこかで会ったっけ？",v:"13_0062"},{w:"kasia",t:"カシアよ。会うのは初めて。",v:"13_0063"},{w:"kasia",t:"見てほしいものがあるの。",v:"13_0064"},{w:null,t:"カシア、手首の画面を、エリーにだけ見えるように少し傾ける。"},{w:null,t:"空中に、小さな映像。"},{w:null,t:"ため池のまわりの暗がりに、目の奥がオレンジに光る子たちが、じっと立っている。"},{w:null,t:"ホテルのフロントの窓に明かり。"},{w:"elly",f:"serious",t:"……これ、今の村？",v:"13_0069"},{w:"kasia",t:"そう、今の村よ。まだ、だれも何もしてないけど。",v:"13_0070"},{w:"kasia",t:"ヴィクターさまは、あなたを迎えたいだけ。",v:"13_0071"},{w:"kasia",t:"来れば、村には何もしない。",v:"13_0072"},{w:null,t:"エリーの顔。"},{w:null,t:"カシアの耳の、オレンジの輪のピアス。エリーの目が、そこに止まる。"},{w:null,t:"エリーの目が、カシアの肩ごしに、通りの空中の画面へ動く。"},{w:"elly",f:"serious",t:"……行ったら、ほんとに村には何もしない？",v:"13_0076"},{w:"kasia",t:"ヴィクターさまは、約束は守る人よ。",v:"13_0077"},{w:"kasia",t:"今夜だけは、お姉さんに電話しないで。",v:"13_0078"},{w:"kasia",t:"声で、分かっちゃうでしょ。",v:"13_0079"},{w:null,t:"エリー、手首の画面を見る。"},{w:"kasia",t:"船は、三番の桟橋で待ってる。",v:"13_0081"},{w:"kasia",t:"お友だちには、言わない方がいいと思う。",v:"13_0082"},{w:null,t:"カシア、列を抜けて、人ごみの中へ消える。"},{w:null,t:"ロボットの腕が、エリーの重ねたカップを受け取り、ジュースを注いだカップを三つ、エリーの前に並べる。"},{w:"x",n:"飲み物の屋台のロボット",t:"優勝の方ですね。三つ、どうぞ。",v:"13_0085"},{w:null,t:"エリー、カップを見る。それから、通りの向こうの机を見る。"},{w:"elly",t:"これ、あそこの机まで運んでくれる？",v:"13_0087"},{w:"x",n:"飲み物の屋台のロボット",t:"かしこまりました。",v:"13_0088"},{w:null,t:"屋台の下から、運ぶ小さなロボットが出てくる。"}];
GR_SC.g13_03=[{w:null,t:"エリー、屋台の町のはしを、港の方へ歩く。肩の上で、ピリポンが髪の中から顔を出し、エリーのほおに、ぱちっと小さく火花を当てる。"},{w:null,t:"屋台の机。運ぶロボットが来て、カップを三つ置く。ヤマト、新しい串をくわえたまま顔を上げる。"},{w:null,t:"通りの向こう。"},{w:null,t:"エリー、笑って、大きく手を振る。"},{w:null,t:"ヤマト、串をくわえたまま、手を振り返す。"},{w:null,t:"エリー、階段を下りて、見えなくなる。"},{w:null,t:"机の上。カップが三つ。"},{w:null,t:"第13話　笑って手を振る",v:"13_0100"}];
GR_SC.g13_04=[{w:null,t:"通りの空中の画面で、決勝がまた最初から流れている。"},{w:null,t:"机の三つ目のカップ。"},{w:null,t:"子どもたちは、もういない。"},{w:null,t:"ヤマトの目が、もう一つのいすの背に止まる。"},{w:"hero",t:"あれ、エリーのカバン。また置いてってるよ。",v:"13_0110"},{w:"alek",t:"海でも見に行ったんだろ。そのうち戻ってくるって。",v:"13_0111"},{w:null,t:"ヤマト、エリーのカップを持ち上げる。"},{w:"hero",t:"でもこれ、エリーのジュースだぞ。",v:"13_0113"},{w:"hero",t:"取りに行ったのに、一口も飲んでねえじゃん。",v:"13_0114"},{w:null,t:"アレク、串を置く。"},{w:null,t:"ヤマト、手首の画面にふれる。"},{w:null,t:"ヤマト、カバンを肩にかけ、盾をわきにかかえて立ち上がる。机のフォルンが、ぱっと顔を上げる。"},{w:null,t:"飲み物の屋台へ走る。"},{w:"hero",t:"なあ、さっきの女の子、どこ行ったか見なかった？",v:"13_0119"},{w:"hero",t:"肩に雷の子をのせてた子。",v:"13_0120"},{w:"x",n:"飲み物の屋台のロボット",t:"その方なら、港へ下りる階段の方へ行かれました。",v:"13_0121"},{w:"alek",t:"この時間に船が出せんのは、三番くらいだ。",v:"13_0123"},{w:"alek",t:"客の船じゃねえけどな。",v:"13_0124"}];
GR_SC.g13_05=[{w:null,t:"屋台の明かりが、背中の方に遠くなる。"},{w:null,t:"海へまっすぐのびる一本の桟橋。"},{w:null,t:"沖に、船の明かりが一つ。"},{w:"hero",t:"エリー！",v:"13_0131"},{w:null,t:"声は、波の音に消える。"}];
GR_SC.g13_07=[{w:null,t:"明かりを消した黒い船の甲板。"},{w:null,t:"船のわきに、小さな黒い艇がつけられている。"},{w:null,t:"エリーの手首の画面がふるえる。"},{w:null,t:"エリー、画面を見る。"},{w:null,t:"エリー、画面に短く打つ。指が一度止まって、また動く。"},{w:null,t:"エリー、うしろをふり返る。"}];
GR_SC.g13_08=[{w:null,t:"沖。もう、明かりは一つもない。"},{w:null,t:"ヤマト、フォルンを抱いたまま、桟橋の先に立っている。"},{w:"hero",t:"アレク、どっかで船借りられないのかよ！",v:"13_0196"},{w:"alek",t:"夜の便は、もう全部止まってる。出せる船なんかねえよ。",v:"13_0197"},{w:null,t:"ヤマト、桟橋のへりに一歩出る。"},{w:null,t:"アレク、ヤマトのパーカーのえりをつかむ。"},{w:"alek",t:"おい、泳いで追う気かよ。どっち行ったかも分かんねえのに。",v:"13_0200"},{w:null,t:"ヤマトの手首が、ぴこん、と鳴る。"},{w:null,t:"空中に小さな字。"},{w:null,t:"ヤマト、それを見たまま動かない。"},{w:"alek",t:"電話は出ねえのに、字は返してくんのかよ。",v:"13_0204"},{w:null,t:"ヤマトの手首が、今度は呼び出しの音で鳴る。"},{w:null,t:"ヤマト、アレクを見る。"},{w:null,t:"声だけの電話。空中に、アナの声の波形が小さく浮かぶ（顔は映さない）。"},{w:"ana",t:"ヤマト！　見てたよ、優勝！　村じゅう大さわぎよ。",v:"13_0208"},{w:"ana",t:"ヤニスさんなんか、オリーブのびん持ってきたんだから。",v:"13_0209"},{w:null,t:"ヤマト、口をあける。"},{w:"ana",t:"で、エリーは？　今日は電話がないけど、一緒？",v:"13_0211"},{w:null,t:"ヤマト、アレクを見る。アレクも、口を開かない。"},{w:"ana",t:"……ヤマト？　聞こえてる？",v:"13_0213"},{w:"hero",f:"surprised",t:"……あ、うん。聞こえてる。えっと……",v:"13_0214"},{w:"ana",t:"どうせまた、何か置き忘れて探してるんでしょ。",v:"13_0215"},{w:null,t:"ヤマト、肩にかけたエリーのカバンを見る。"},{w:"ana",t:"かけてって言っといて。待ってるからって。",v:"13_0217"},{w:"hero",f:"serious",t:"……うん。言っとく。",v:"13_0218"},{w:null,t:"声の波形が消える。"},{w:null,t:"ヤマト、手首を下ろす。"},{w:"hero",f:"serious",t:"……だれかに言うか。",v:"13_0221"},{w:"alek",t:"本人から「だいじょうぶ」って来てんだぞ。",v:"13_0222"},{w:"alek",t:"だれに言ったって、それじゃ動いてくれねえよ。",v:"13_0223"}];
GR_SC.g13_09=[{w:null,t:"大会の選手が泊まる宿の、小さな部屋。"},{w:null,t:"ヤマト、盾を壁に立てかける。"},{w:null,t:"フォルンが、テーブルに跳び上がる。"},{w:null,t:"カバンのふたが、少し開いている。アレクが閉めようと手をのばす。"},{w:null,t:"フォルン、目をあけずに、低くうなる。"},{w:null,t:"アレク、手を止める。"},{w:"alek",t:"閉めるだけだって。……分かったよ。さわんねえよ。",v:"13_0233"},{w:null,t:"アレク、手を引っこめる。"},{w:null,t:"ヤマト、寝台のはしに座ったまま、窓の外の港を見ている。"},{w:null,t:"アレク、寝台に横になる。目は、あいている。"},{w:null,t:"アレク、横になったまま手首の画面を開く。"},{w:null,t:"アレク、画面を閉じる。"},{w:null,t:"アレク、天井を見たまま、自分の左手の親指と人差し指のあいだを、右の親指でぎゅっとおさえる。"},{w:null,t:"アレク、おさえたまま、まばたきをしない。"}];
GR_SC.g13_10=[{w:null,t:"窓の外が明るい。"},{w:null,t:"フォルンは、カバンの上で丸くなったまま。"},{w:null,t:"部屋の空中の画面が、決まった時刻にひとりでに点く。"},{w:"x",n:"ニュースの読み手",t:"けさ早く、山の中の、悪い人たちのかくれ家が、",v:"13_0246"},{w:"x",n:"ニュースの読み手",t:"ほぼ全部こわされました。",v:"13_0247"},{w:"x",n:"ニュースの読み手",t:"こわしたのは、正体の分からない大きな生き物で、",v:"13_0248"},{w:"x",n:"ニュースの読み手",t:"一体だけだったとみられています。",v:"13_0249"},{w:null,t:"映像。東の空が白みはじめたころ。"},{w:null,t:"影が、一度だけ西の方を向いて、大きく伸びをする。"},{w:null,t:"画面が変わる。"},{w:"x",n:"国の報道の係の人",t:"ある会社に、お金をはらって頼みました。",v:"13_0253"},{w:"x",n:"国の報道の係の人",t:"会社の名前は、言えないことになっています。",v:"13_0254"},{w:null,t:"画面が変わる。"},{w:"x",n:"研究所の人",t:"あれは、人が手綱をにぎれるものじゃありません。",v:"13_0256"},{w:"x",n:"研究所の人",t:"だれが動かしているのか、国はちゃんと——",v:"13_0257"},{w:null,t:"映像が、そこで切れる。"},{w:"x",n:"ニュースの読み手",t:"続いて、白い都の大会の話題です。",v:"13_0259"},{w:null,t:"画面に、きのうの決勝。"},{w:null,t:"ヤマト、空中の画面に手をのばして、消す。"},{w:null,t:"ヤマトの手首が、ぴこん、と鳴る。"},{w:null,t:"「今のニュース見た？」"},{w:"hero",t:"アレク、行くぞ。エリー、迎えに行く。",v:"13_0269"},{w:"alek",t:"……どこにだよ。",v:"13_0270"},{w:"hero",t:"知らねえよ。探すの、お前の得意だろ。",v:"13_0271"}];
GR_SC.g13_11=[{w:null,t:"同じ朝。オリーヴァ村の、丘の向こう。",v:"13_0275"},{w:null,t:"おばあさんの石の家。"},{w:null,t:"おばあさん（60代・見た目40代）、台所の空中の画面で、同じ朝のニュースを見ている。"},{w:null,t:"画面の中で、黒い影が西を向いて伸びをし、腕をだらんと下ろす。"},{w:null,t:"おばあさんの、カップを口へ運ぶ手が止まる。"},{w:null,t:"窓の外。丘の頂上の、研究所あとの丸屋根。"},{w:null,t:"ニュースの黒い影と、窓の外の黒い車が、同じ画面に入る。"},{w:null,t:"おばあさん、カップを置く。"},{w:null,t:"おばあさん、影の肩の線を、じっと見ている。"}];
GR_SC.g13_12=[{w:null,t:"東の空が白んでいる。"},{w:null,t:"煙の向こうに、黒い巨体の影。"},{w:null,t:"その肩の上に、小さな白い人の形。"}];
GR_BT[13]={mid:[[{w:"kasia",t:"ここから先は、おつなぎできません。",v:"13_0137"},{w:"kasia",t:"エリーは自分で来たの。追ってこなくていい。",v:"13_0139"},{w:"hero",f:"surprised",t:"うそつけ！　エリーが自分で行くわけねえだろ！",v:"13_0140"},{w:null,t:"ヤマトとアレクの手首が光る。"},{w:"alek",t:"きのう決勝だったんだぞ。無理させんな。",v:"13_0143"},{w:"hero",t:"分かってるよ！　フォルコン、撃て！",v:"13_0144"}],[{w:"hero",t:"フォルコン、まん中まで下がれ！",v:"13_0146"},{w:"alek",t:"クロベク、行け！",v:"13_0148"},{w:"alek",t:"羽の音がしねえ。目、離すなよ、ヤマト！",v:"13_0150"},{w:null,t:"ヤマト、暗い空を探すのをやめる。"},{w:null,t:"ヤマト、手のひらを下ろす。右手で、二本目の街灯の真上の暗がりを指す。"},{w:"alek",t:"クロベク、今だ！",v:"13_0161"},{w:"hero",t:"フォルコン、ブレイズショット！",v:"13_0167"},{w:null,t:"カシア、背を向ける。街灯の下で、顔が一瞬だけ照らされる。"},{w:null,t:"アレク、その顔から目を離さない。"},{w:null,t:"カシア、桟橋の先の杭につないであった小さな黒い無人の艇に下りる。"}]],post:[]};
GR_EP[13]={"t": "笑って手を振る", "sc": [["g13_01", "白い都・屋台の町（夜）", 0], ["g13_02", "飲み物の屋台", 0], ["g13_03", "港へ下りる階段", 0], ["g13_04", "屋台の机（しばらくして）", 0], ["g13_05", "三番桟橋（夜）", 0], ["g13_06", "勝負（2Dアニメ）", 1], ["g13_07", "黒い船の上（夜）", 0], ["g13_08", "桟橋の先（夜）", 0], ["g13_09", "選手の宿の部屋（夜ふけ）", 0], ["g13_10", "選手の宿の部屋（朝）", 0], ["g13_11", "丘の向こうの石の家（同じ朝）", 0], ["g13_12", "どこかの荒れ地（ニュースと同じ夜明け）", 0]]};
GR_SC.g14_01=[{w:null,t:"エリーのいない朝。二人は、白い都を出た。",v:"14_0023"},{w:null,t:"宿の前。配達のドローンが、優勝の盾を入れた箱を下げて、空へ上がっていく。"},{w:null,t:"宿の前の道に、白いロボタクシーがすっと止まる。"},{w:"hero",f:"serious",t:"……車、乗るのかよ。ずっと歩いてきたのに。",v:"14_0026"},{w:"alek",t:"もう隠れても意味ねえよ。",v:"14_0027"},{w:"alek",t:"向こうは、おれらがどこにいるか全部知ってる。",v:"14_0028"},{w:null,t:"ヤマト、乗る。"},{w:null,t:"車の中の空中の文字「行き先をどうぞ」。"},{w:"hero",t:"で、どこ行くんだよ。",v:"14_0031"},{w:"alek",t:"あの女、オレンジの輪のピアスしてただろ。",v:"14_0032"},{w:"alek",t:"あの輪の連中の屋敷は、獅子の門の丘ってうわさだ。",v:"14_0033"},{w:null,t:"アレク、地図も出さずに、空中の文字に言う。"},{w:"alek",t:"獅子門の丘。遺跡の手前の、北の坂の下まで。",v:"14_0035"},{w:null,t:"空中の文字「獅子門の丘　北の坂の下　約1時間30分」。"},{w:"hero",t:"うわさだけで、坂の向きまで分かんのかよ。",v:"14_0037"},{w:null,t:"アレク、答えない。"},{w:null,t:"アレクの手首の画面が、まだ開いたまま。"},{w:null,t:"アレクの親指が、メモを閉じる。"},{w:null,t:"ヤマトの目が、空中の文字とアレクの横顔を、行ったり来たりする。"},{w:null,t:"第14話　獅子門の丘",v:"14_0044"}];
GR_SC.g14_02=[{w:null,t:"坂の下の道。"},{w:null,t:"坂の下のオリーブ林。"},{w:null,t:"アレク、パンを手に持って、ひっくり返して見る。"},{w:"alek",t:"かてえな、これ。",v:"14_0053"},{w:"hero",f:"serious",t:"……フォルン、ちょっとだけ、あっためて。",v:"14_0054"},{w:null,t:"ヤマト、パンをフォルンの前に置く。"},{w:null,t:"ぼっ。パンが、まっ黒なかたまりになる。"},{w:null,t:"ヤマト、黒いパンを見る。"},{w:null,t:"アレク、手をのばして、まっ黒なはしを、だまってかじる。"},{w:"hero",f:"serious",t:"……それ、うまい？",v:"14_0059"},{w:"alek",t:"うまいわけねえだろ。",v:"14_0060"},{w:null,t:"アレク、顔をしかめたまま、もう一口かじる。"},{w:"hero",f:"serious",t:"……エリーなら、焦げるって分かってたよな。",v:"14_0062"},{w:null,t:"アレクの、かじりかけのパンを持った手が止まる。"},{w:null,t:"少しはなれた木の根もと。フォルンが、自分のしっぽの火で、落ちていたオリーブを一つずつあぶっている。"},{w:null,t:"ヤマト、手首の画面を開く。"},{w:null,t:"見ているあいだに、その一行の下に、小さな「既読」の字が、ふっと付く。"},{w:null,t:"ヤマト、画面を見たまま止まる。……返事は来ない。"},{w:null,t:"ヤマト、画面を閉じる。"}];
GR_SC.g14_03=[{w:null,t:"丘の上に、石の獅子が二頭、門を守っていた。",v:"14_0071"},{w:null,t:"丘の頂上。古い石の門。"},{w:null,t:"門の内側に、新しい白い柵。"},{w:null,t:"門の奥に、白い屋敷。"},{w:null,t:"アレク、門の前で足を止める。"},{w:null,t:"二人が呼ぶ前に、白い柵が、すうっと横に開く。"},{w:null,t:"門の内側に、白いスーツの男が立っている。"},{w:"victor",t:"やあ、よく来たね。道は迷わなかっただろ。",v:"14_0078"},{w:null,t:"ヤマト、男の顔を見る。"},{w:"hero",t:"あんた、大会の……盾くれた人じゃん。",v:"14_0080"},{w:"victor",t:"覚えててくれたんだ。うれしいね。",v:"14_0081"},{w:null,t:"ヤマト、男の指の輪を見る。"},{w:"hero",t:"あんたが……ヴィクターなのかよ。",v:"14_0083"},{w:"victor",t:"町のみんなは、そう呼んでるね。",v:"14_0084"},{w:"victor",t:"立ち話もなんだから、お茶にしよう。",v:"14_0085"},{w:"hero",t:"お茶なんかいいよ。エリー、ここにいるんだろ。",v:"14_0086"},{w:"victor",t:"いるよ。上の部屋で、新しい服を選んでる。",v:"14_0087"},{w:"victor",t:"下りてくるかは、エリーが決めることだよ。",v:"14_0088"},{w:null,t:"ヴィクター、背を向けて屋敷の方へ歩きだす。"},{w:null,t:"ヤマト、アレクを見る。"}];
GR_SC.g14_04=[{w:null,t:"屋敷の奥のテラス。"},{w:null,t:"テラスの前は、刈りこんだ芝の庭。"},{w:null,t:"庭のいちばん奥のすみに、岩のような巨大な背中。"},{w:null,t:"ヤマトの目が、その背中に吸いよせられる。"},{w:null,t:"ヴィクター、カップを持ち上げる。"},{w:"victor",t:"アレク。昔きみが送ってくれた研究、全部読んだよ。",v:"14_0098"},{w:"victor",t:"あの星の測り方、おもしろかった。続きが読みたいんだ。",v:"14_0099"},{w:null,t:"ヴィクター、胸のポケットから、手のひらほどのうすいカードを出す。"},{w:null,t:"胸のポケットの奥に、角のすり切れた古い単語帳が見える。"},{w:"victor",t:"観測所ごと出すよ。好きな山に建てていい。",v:"14_0102"},{w:null,t:"アレク、カードを見る。手をのばさない。"},{w:null,t:"ヤマト、アレクとヴィクターを見くらべる。"},{w:"hero",t:"……研究？　アレク、こいつのこと知ってんのかよ。",v:"14_0105"},{w:"alek",t:"……声だけだよ。仕事の相手だったんだ。",v:"14_0106"},{w:"hero",t:"仕事って、狐を運べってやつの？",v:"14_0107"},{w:"alek",t:"そうだよ。顔は、大会の開会で初めて見たんだ。",v:"14_0108"},{w:"hero",t:"開会って、三日も前じゃん。",v:"14_0109"},{w:"hero",t:"なんで言わなかったんだよ。",v:"14_0110"},{w:null,t:"アレク、答えない。カードから目を上げない。"},{w:null,t:"ヴィクター、笑顔のまま、お茶を一口飲む。"},{w:"victor",t:"責めないであげてよ。",v:"14_0113"},{w:"victor",t:"狐の届け先に、ここの住所を書いたのは、おれだから。",v:"14_0114"},{w:null,t:"ヤマトの目が、アレクの手首の画面に行く。"},{w:null,t:"ヴィクター、立ち上がる。"},{w:"victor",t:"ヤマトくん。きみ、ああいうの好きだろ。",v:"14_0117"},{w:"victor",t:"近くで見てごらん。起きないから大丈夫。",v:"14_0119"}];
GR_SC.g14_05=[{w:null,t:"芝の庭を、ヴィクターとヤマトが歩く。"},{w:null,t:"巨大な背中の前。"},{w:null,t:"ヤマト、見上げる。目が、大きく開く。"},{w:"hero",f:"smile",t:"すげえ……",v:"14_0125"},{w:null,t:"ヤマト、自分の声に気づいて、口を閉じる。"},{w:null,t:"巨大な肩の線。"},{w:"hero",f:"serious",t:"……これ、けさのニュースの。",v:"14_0128"},{w:"victor",t:"見たいだろ。いつでも見においで。",v:"14_0129"},{w:null,t:"ヤマト、巨体から目をそらす。"},{w:null,t:"フォルンが、巨体を見上げて、毛を逆立てている。"}];
GR_SC.g14_07=[{w:"victor",t:"約束だからね。エリー、お友だちが呼んでるよ。",v:"14_0194"},{w:null,t:"屋敷の中から、テラスへ下りる白い階段。"},{w:null,t:"エリー、笑っている。"},{w:"hero",t:"エリー！",v:"14_0197"},{w:null,t:"ヤマト、走りだす。"},{w:"elly",t:"ヤマト、アレク。優勝おめでとう。",v:"14_0199"},{w:"elly",t:"盾、かっこよかったよ。",v:"14_0200"},{w:"hero",t:"そんなの、どうでもいいよ。帰ろうぜ。",v:"14_0201"},{w:"hero",t:"アナさんだって、電話待ってるんだぞ。",v:"14_0202"},{w:"elly",t:"お姉ちゃんには、あとでちゃんとかけるよ。",v:"14_0203"},{w:"elly",t:"大丈夫だよ。ここ、ご飯おいしいし。",v:"14_0204"},{w:"elly",t:"だから、帰って。",v:"14_0205"},{w:"hero",f:"angry",t:"……なんでだよ。エリー、自分で来たのかよ。",v:"14_0206"},{w:"elly",t:"うん。自分で来たの。",v:"14_0207"},{w:null,t:"ヤマト、口をあけたまま、何も言えない。"},{w:null,t:"ピリポンが、エリーの髪の中で、ぱちっと小さく光る。"},{w:null,t:"テラスで、アレクが立ち上がりかけて、また座る。"},{w:null,t:"ヴィクター、庭へ下りてくる。"},{w:"victor",t:"いい狐だ。チップも入れてないのに、よく動くね。",v:"14_0212"},{w:null,t:"ヴィクター、フォルンの頭へ手をのばす。"},{w:null,t:"フォルンの首元で、登録の小さな光が、ふっと明るくなる。"},{w:null,t:"ヴィクターの手が、止まる。"},{w:"victor",t:"……登録ずみか。",v:"14_0216"},{w:null,t:"ヴィクター、笑顔のまま、手を引く。"},{w:"victor",t:"門は、開けとくよ。また、いつでも。",v:"14_0218"},{w:null,t:"ヴィクター、庭の奥の巨大な背中を、ちらりと見る。それから、ヤマトの足もとのフォルンを見る。"},{w:null,t:"エリー、階段の上で、手を振らない。"}];
GR_SC.g14_08=[{w:null,t:"丘を下りる道。"},{w:null,t:"アレクが前、ヤマトがうしろ。"},{w:null,t:"アレク、パーカーのポケットから研究費のカードを出す。"},{w:null,t:"道ばたの、ごみを集めるロボットの箱が、口をあけて待っている。"},{w:null,t:"アレク、カードを箱の上にかざす。……そのまま、ポケットに戻す。"},{w:null,t:"ヤマトは、それを見ている。"},{w:null,t:"坂の下。乗ってきたロボタクシーが、道で待っている。"},{w:null,t:"ヤマト、車の方へは行かない。"},{w:null,t:"アレク、車のドアの前で止まる。"},{w:"hero",t:"おれ、ここで寝る。",v:"14_0232"},{w:null,t:"アレク、手首の画面で、車を帰す。"}];
GR_SC.g14_09=[{w:null,t:"同じころ。オリーヴァ村。",v:"14_0236"},{w:null,t:"アナのホテルのフロント。"},{w:null,t:"アナの手首の画面が鳴る。"},{w:null,t:"声だけの電話。空中に、エリーの声の波形が小さく浮かぶ（顔もうしろの部屋も映らない）。"},{w:"elly",f:"sad",t:"お姉ちゃん、ごめんね。きのう、かけられなくて。",v:"14_0240"},{w:"ana",t:"やっとかかってきた。今、どこにいるの？",v:"14_0241"},{w:"elly",t:"お友だちの家。大会で仲よくなった子のとこなの。",v:"14_0242"},{w:"ana",t:"お友だち？　ヤマトたちは、一緒じゃないの？",v:"14_0243"},{w:"elly",t:"うん、今はちょっと別行動なの。",v:"14_0244"},{w:"ana",t:"どこの家？　住所、送っといて。",v:"14_0245"},{w:"elly",f:"surprised",t:"えっとね……あとで送る。",v:"14_0246"},{w:"elly",t:"あ、窓からね、首のないねこさんが二匹見えるの。",v:"14_0247"},{w:"ana",t:"……ねこさん？",v:"14_0248"},{w:"elly",t:"うん。門の上で、仲よく並んでる。",v:"14_0249"},{w:"elly",t:"ここ、ご飯もおいしいよ。",v:"14_0250"},{w:"ana",t:"……そう。ちゃんと食べてるなら、いいけど。",v:"14_0251"},{w:"elly",t:"また、あしたもかけるね。",v:"14_0252"},{w:null,t:"声の波形が消える。"},{w:null,t:"アナ、手首の画面の写真を、ずっと前までさかのぼる。古い一枚で指が止まる。"},{w:null,t:"アナ、窓の外を見る。"},{w:null,t:"アナ、上着をつかんで、フロントを出る。"}];
GR_SC.g14_10=[{w:null,t:"坂を下りた町の役場の窓口。"},{w:null,t:"中の机に、役場の人が一人だけ。"},{w:"ana",t:"ため池のところの黒い車、きのうから、ずっと止まってるんです。",v:"14_0261"},{w:"x",n:"役場の人",t:"あれは、国の仕事で止まっている車です。",v:"14_0262"},{w:"x",n:"役場の人",t:"国の許しが出ていますから、どかせません。",v:"14_0263"},{w:"ana",t:"それに、妹が、その会社の屋敷にいるんです。",v:"14_0264"},{w:"ana",t:"獅子門の丘です。本人は、お友だちの家って言うけど。",v:"14_0265"},{w:"x",n:"役場の人",t:"ご家族のところには、本人から連絡があるんですよね？",v:"14_0266"},{w:"ana",t:"……はい。さっき、ありました。",v:"14_0267"},{w:"x",n:"役場の人",t:"本人が自分で行ったと言っている限り、動けません。",v:"14_0268"},{w:null,t:"アナ、役場の人を見る。役場の人は、目をそらさない。"},{w:null,t:"アナ、何も言わずに、ガラスの戸を押して出る。"},{w:null,t:"見回りのロボットが、「お気をつけて」と頭を下げる。"}];
GR_SC.g14_11=[{w:null,t:"獅子の門の丘のふもとのオリーブ林。"},{w:null,t:"シートの下で、アレクがヤマトに背中を向けて横になっている。"},{w:null,t:"ヤマトは、あおむけ。目をあけている。"},{w:null,t:"白いカバンは、ヤマトの頭の横。"},{w:null,t:"草をふむ、小さな足音。"},{w:null,t:"フォルン、シートのはしから、もぐりこむ。"},{w:null,t:"ヤマト、フォルンを見る。"},{w:null,t:"ヤマト、そっと手をのばす。"},{w:null,t:"フォルンの耳が、ヤマトの手の方へ、ほんの少し向く。"},{w:null,t:"ヤマト、手のひらを、背中にのせる。"},{w:null,t:"フォルン、目をあけない。"},{w:null,t:"ヤマトの手のひらの下で、フォルンの背中が、息に合わせて上がって、下がる。"},{w:null,t:"ヤマト、手をのせたまま、しばらく動かない。"},{w:null,t:"ヤマト、右の手はフォルンの背中にのせたまま、左の手首を顔の前に上げて、画面を開く。"},{w:null,t:"その下に、空中の文字「アテネ空港　東京行き　あすの便」。ヤマトの右手がフォルンの背中からはなれ、指が「予約」の欄の上に一瞬乗って、止まる。"},{w:null,t:"その下に、うすく一行。"},{w:null,t:"画面の光が、背中を向けたアレクの肩を、うすく照らす。"},{w:null,t:"フォルンの耳が、画面の光の方へ、ぴくっと動く。"},{w:null,t:"ヤマトの指が、「予約」の上で止まったまま。"},{w:null,t:"ヤマト、指を引いて、画面を閉じる。シートの中が、しっぽの火の明かりだけに戻る。"},{w:null,t:"ヤマト、左の手で、頭の横の白いカバンを引きよせる。ひもを、にぎる。"},{w:null,t:"シートのすき間から、丘の上の屋敷の明かりを見ている。目は、閉じない。"},{w:null,t:"背中を向けたアレクの目が、暗い中で、あいている。"}];
GR_BT[14]={mid:[[{w:null,t:"ヴィクター、テラスへ戻りながら、ふり返る。"},{w:"victor",t:"せっかく来たんだ。うちの子と、少し遊んでいかないか。",v:"14_0135"},{w:"hero",t:"なんで、あんたの子と遊ばなきゃいけないんだよ。",v:"14_0136"},{w:"victor",t:"エリーも、上から見てるよ。",v:"14_0137"},{w:null,t:"ヤマト、屋敷を見上げる。"},{w:"hero",f:"smile",t:"……勝ったら、エリーをここに呼べよ。",v:"14_0139"}],[{w:"victor",t:"いいよ。呼ぶだけなら、いつでも。",v:"14_0140"},{w:null,t:"ヴィクター、テラスの椅子に座る。"},{w:"victor",t:"ゼノ。",v:"14_0142"},{w:null,t:"ゼノ、だまってうなずく。"},{w:null,t:"ヤマトの手首が光る。"},{w:null,t:"アレクは、テラスの階段の下。"},{w:"alek",t:"ヤマト、あいつの前で手の内まで見せんなよ。",v:"14_0146"},{w:null,t:"ヤマト、アレクの方を見ない。指が、手首の画面のフォルレオンの印へのびる。"},{w:"alek",t:"あいつ、森も混じってる。火なら通るぞ。",v:"14_0150"},{w:"hero",t:"待て。",v:"14_0155"}],[{w:"hero",t:"噴水の前だ。そこで待ってろ。",v:"14_0158"},{w:"hero",t:"撃て！",v:"14_0161"},{w:null,t:"ヤマト、フォルコンの足もとを見る。"},{w:"hero",t:"下がれ！　芝の上！",v:"14_0165"},{w:null,t:"ヤマト、フォルコンの耳の先を見る。それから、植えこみのはしを見る。"},{w:"hero",f:"serious",t:"……そっちか。行け！",v:"14_0171"},{w:null,t:"ヤマト、左の手のひらを立てる。"},{w:null,t:"ヤマト、手のひらを下ろす。"},{w:"hero",t:"フォルコン、ブレイズショット！",v:"14_0178"}]],post:[{w:null,t:"ホタルン、燃える葉の中から芝の上に落ちる。"},{w:null,t:"ホタルン、初めて小さく鳴く。"},{w:null,t:"庭師ロボットが二台、すぐ走ってきて植えこみの火を消す（燃えたのは下草と葉だけ）。"},{w:"victor",t:"いい試合だった。同じのが、うちにはあと三百いる。",v:"14_0187"}]};
GR_EP[14]={"t": "獅子門の丘", "sc": [["g14_01", "白い都の外れの道（朝）", 0], ["g14_02", "丘のふもとのオリーブ林（昼）", 0], ["g14_03", "獅子の門", 0], ["g14_04", "屋敷のテラス", 0], ["g14_05", "庭のすみ", 0], ["g14_06", "勝負（2Dアニメ）", 1], ["g14_07", "テラスの階段", 0], ["g14_08", "帰り道（夕方）", 0], ["g14_09", "オリーヴァ村・アナのホテル（夕方）", 0], ["g14_10", "町の役場（夕方）", 0], ["g14_11", "丘のふもとのオリーブ林（夜）", 0]]};
GR_SC.g15_01=[{w:null,t:"運河の町コリンタ。海と海を結ぶ、まっすぐな水の道だ。",v:"15_0025"},{w:null,t:"町を南北にまっすぐ走る運河。"},{w:null,t:"船の後ろの席に、ヤマトとアレク。"},{w:null,t:"船が、ゆっくり止まる。"},{w:"x",n:"運河の船の案内ロボット",t:"橋の通行が止められています。",v:"15_0029"},{w:"x",n:"運河の船の案内ロボット",t:"再開の時間は、まだ決まっておりません。",v:"15_0030"},{w:null,t:"船の客たちが、ため息をつく。"},{w:null,t:"橋の向こうがわ。"},{w:null,t:"橋のたもとに、小さな机。"},{w:"hero",t:"なんで止めてんだよ。黒い船は、向こうを通ってるじゃん。",v:"15_0034"},{w:"alek",t:"おれに聞くなよ。あそこの机の人に聞けよ。",v:"15_0035"}];
GR_SC.g15_02=[{w:null,t:"ヤマトとアレク、船から岸に上がって、机の前へ。"},{w:null,t:"机の上に、端末が一台。そのわきに、子どもが描いた絵（男の人と女の子が手をつないでいる。"},{w:"hero",t:"おじさん、橋、いつ開くの？",v:"15_0040"},{w:"nomos",t:"ノモスです。ここの現場主任の。",v:"15_0041"},{w:"nomos",t:"ヴィクターさまの荷がすべて通るまで、開けません。",v:"15_0042"},{w:"nomos",t:"決まりですから、通せません。",v:"15_0043"},{w:null,t:"第15話　運河の町コリンタ",v:"15_0045"}];
GR_SC.g15_03=[{w:null,t:"ヤマト、「ヴィクター」と聞いて、ノモスの胸のオレンジの輪を見る。"},{w:"alek",t:"荷がすべてって、あと何そうあるんですか。",v:"15_0052"},{w:"nomos",t:"お答えできません。",v:"15_0053"},{w:null,t:"橋の向こうの切り通し。"},{w:"alek",t:"……じゃあ、待合所って一泊いくらですか。",v:"15_0055"},{w:null,t:"岸の上の、古い石の倉庫を直した待合所。"},{w:"nomos",t:"一人、十五ジェムコインです。",v:"15_0057"},{w:"alek",t:"テリオンは、ただですよね。",v:"15_0058"},{w:"nomos",t:"テリオンも一人に数える、と決まりに書いてあります。",v:"15_0059"},{w:"hero",t:"じゃあフォルン、半分子どもだから半額な。",v:"15_0060"},{w:null,t:"ノモス、端末の決まりを、指でさがす。"},{w:"nomos",t:"……半額の決まりは、ありません。",v:"15_0062"},{w:"alek",t:"なら、こいつらは外で寝かせます。",v:"15_0063"},{w:"nomos",t:"テリオンを外で寝かせるのは、決まりで禁止です。",v:"15_0064"},{w:null,t:"アレク、口をあけたまま止まる。"},{w:null,t:"机の上に、フォルンがひょいと跳び乗る。"},{w:null,t:"ノモス、フォルンを見る。"},{w:"nomos",t:"……机に乗ってはいけない、とは書いてありませんね。",v:"15_0068"},{w:null,t:"フォルン、弁当箱の上に座る。"},{w:null,t:"ヤマト、ふきだしかける。口を手でおさえて、橋の向こうに目をもどす。"}];
GR_SC.g15_04=[{w:null,t:"岸の石だたみの広場。"},{w:null,t:"切り通しの手前に、古い石の倉庫がもう一つ。"},{w:null,t:"倉庫の入口に、黒い柵がすっと閉まる。"},{w:null,t:"アレク、その車を目で追う。それから、ヤマトの横に立つ。"},{w:"alek",t:"あの車、フォルンを追い回してたのと同じ型だぞ。",v:"15_0077"},{w:"hero",f:"serious",t:"……だから、なんだよ。",v:"15_0078"},{w:"alek",t:"あいつらの車が今どこにいるか、中で見られるかもしれねえ。",v:"15_0079"},{w:"hero",f:"serious",t:"……で、どうやって入んだよ。",v:"15_0080"},{w:null,t:"アレク、答えずに、机の方へ歩いていく。"}];
GR_SC.g15_05=[{w:"alek",t:"あの車庫、入れてもらえますか。",v:"15_0084"},{w:"nomos",t:"関係者以外は、入れません。",v:"15_0085"},{w:"alek",t:"この子を追い回してた車の記録、持ち主なら見られますよね。",v:"15_0086"},{w:"nomos",t:"……はい。持ち主の方は、見られます。",v:"15_0087"},{w:null,t:"アレク、弁当箱の上のフォルンをあごで指す。"},{w:null,t:"ノモス、端末をフォルンの首元にかざす。"},{w:"alek",t:"持ち主は、関係者ですよね。",v:"15_0090"},{w:null,t:"ノモス、端末の決まりを、指でさがす。指が止まる。"},{w:"nomos",t:"……決まりですから、お通しします。",v:"15_0092"},{w:null,t:"ノモス、端末を押す。車庫の入口の黒い柵が、横へすっと開く。"}];
GR_SC.g15_06=[{w:null,t:"古い石の倉庫の中。"},{w:null,t:"アレク、台にふれる。"},{w:null,t:"アレク、一覧を指で下へ、古い方へおろしていく。"},{w:null,t:"ヤマト、ある一行で、アレクの指を止める。"},{w:null,t:"映像。ぶどう畑のはしの、小さな木の小屋。"},{w:null,t:"小屋の前に、小さな女の子が立っている。"},{w:null,t:"車が動きだす。"},{w:null,t:"映像のすみに、行き先の欄。"},{w:"hero",f:"serious",t:"……これ、エリーだ。",v:"15_0108"},{w:null,t:"ヤマト、映像を巻き戻す。8歳の女の子が、黒い車の前で笑ったまま止まっている所で、止める。"},{w:null,t:"ヤマト、止めた絵を見ている。"},{w:null,t:"アレク、一覧の一番上まで戻す。"},{w:null,t:"「オリーヴァ村　ため池周辺　待機　解除指示待ち　指示：V」。"},{w:"alek",t:"今週のも見ろよ。ため池のまわりで、待機してるってよ。",v:"15_0114"},{w:"hero",t:"これ、写してく。",v:"15_0115"},{w:null,t:"ヤマト、左の手首を台にかざす。"},{w:null,t:"アレク、それを見る。"}];
GR_SC.g15_08=[{w:null,t:"運河の岸。待合所の裏。"},{w:null,t:"アレク、岸の石に腰をおろす。"},{w:null,t:"アレク、自分の手首の画面にふれる。"},{w:null,t:"声だけの電話。空中に、アナの声の波形が小さく浮かぶ（顔は映さない）。"},{w:"ana",t:"アレク？　あんたがかけてくるなんて、めずらしいね。",v:"15_0171"},{w:"alek",t:"アナさん、エリーのことで話があります。",v:"15_0172"},{w:"alek",t:"エリーは今、ヴィクターの屋敷にいます。",v:"15_0173"},{w:"alek",t:"大会の夜に、自分で行ったんです。",v:"15_0174"},{w:null,t:"声の波形が、しばらく平らなまま。"},{w:"ana",t:"……やっぱり、そうなんだ。",v:"15_0176"},{w:"ana",t:"獅子の門の丘でしょ。あの子、電話でこっそり教えてくれたの。",v:"15_0177"},{w:"ana",t:"黒い車も、もう三日、ため池のとこにいるの。",v:"15_0178"},{w:"ana",t:"役場には、本人が自分で行ったなら動けないって言われた。",v:"15_0179"},{w:null,t:"ヤマトの目が、自分の手首の画面の記録の「待機」の字に行く。それから、空中の声の波形に戻る。"},{w:"ana",t:"毎晩かけてきて、ご飯がおいしいって、そればっかり。",v:"15_0181"},{w:"ana",t:"村は、ヤニスさんたちとこっちで見てるから。",v:"15_0183"},{w:"ana",t:"堰も、みんなで交代で守る。",v:"15_0184"},{w:"ana",t:"あんたたちは、エリーをお願い。",v:"15_0185"},{w:null,t:"アレク、返事をしかけて、口を閉じる。"},{w:"ana",t:"……アレク？",v:"15_0187"},{w:"alek",t:"……はい。分かりました。",v:"15_0188"},{w:null,t:"声の波形が消える。"}];
GR_SC.g15_09=[{w:"hero",t:"……おれ、谷に行く。エリーの、あの子がいるんだろ。",v:"15_0192"},{w:"alek",t:"きのうの夜、帰りの便、見てたろ。",v:"15_0193"},{w:"hero",t:"……見てたよ。ヴィクターのこと黙ってたのは、そっちだろ。",v:"15_0194"},{w:"alek",t:"言ってたら、何か変わったのかよ。",v:"15_0195"},{w:"alek",t:"勝てない相手だって、見ただろ。",v:"15_0196"},{w:"alek",t:"あいつのとこには、三百いるんだぞ。",v:"15_0197"},{w:null,t:"ヤマト、手首の画面を開く。"},{w:null,t:"ヤマト、その絵を、アレクの顔の前に突き出す。"},{w:null,t:"アレク、絵を見る。"},{w:null,t:"アレク、立ち上がる。"}];
GR_SC.g15_10=[{w:null,t:"アレク、パーカーのポケットから、研究費のカードを出す。"},{w:"alek",t:"これ、ヴィクターさんに返しといてください。",v:"15_0205"},{w:"nomos",t:"……お預かりします。",v:"15_0206"},{w:null,t:"ノモス、カードを両手で受け取って、子どもの絵の横に、まっすぐ置く。"},{w:null,t:"アレク、ふり返らずに、岸の上の道へ上がる。"},{w:null,t:"道の上に、白いロボタクシーがすっと止まる。"},{w:"alek",t:"大理石の谷。",v:"15_0210"},{w:null,t:"アレク、先に乗る。"},{w:null,t:"二人のあいだに、空いた席が一つ。"},{w:null,t:"窓の外。橋のたもとで、ノモスが背すじをのばしたまま、端末に何か打ちこんでいる。"}];
GR_SC.g15_11=[{w:null,t:"その夜。獅子の門の丘の屋敷。",v:"15_0216"},{w:null,t:"屋敷の一室。"},{w:null,t:"エリー、窓辺の床に座って、手首の画面にふれる。"},{w:null,t:"声だけの電話。空中に、アナの声の波形が小さく浮かぶ（顔は映さない）。"},{w:"elly",t:"お姉ちゃん、こんばんは！　今、だいじょうぶ？",v:"15_0220"},{w:"ana",t:"うん。……エリー、ちゃんと食べた？",v:"15_0221"},{w:"elly",t:"うん、ご飯おいしいよ。今日はね、魚だった。",v:"15_0222"},{w:"ana",t:"そう。……よかった。",v:"15_0223"},{w:"elly",t:"お姉ちゃんは？　ちゃんと食べた？",v:"15_0225"},{w:"ana",t:"食べたよ。……ぶどうジュース。",v:"15_0226"},{w:"elly",t:"ジュースはご飯じゃないでしょ。ちゃんと食べてよ。",v:"15_0227"},{w:"ana",t:"はいはい。あしたも、かけてきなさいよ。",v:"15_0228"},{w:null,t:"声の波形が消える。"},{w:null,t:"エリー、しばらく、波形の消えたあたりを見ている。"}];
GR_SC.g15_12=[{w:null,t:"屋敷の地下。"},{w:null,t:"エリーが、はだしで入ってくる。"},{w:null,t:"天井のすみに、黒い見張りのレンズ。"},{w:null,t:"エリー、いちばん奥の檻の前にしゃがむ。"},{w:null,t:"檻の中の小さな丸い子が、オレンジの目でエリーを見る。"},{w:"elly",t:"ピリポン、見て。この子、かわいくない？",v:"15_0238"},{w:null,t:"ピリポン、エリーの髪の中から顔を出す。"},{w:null,t:"檻の子は、動かない。"},{w:null,t:"エリー、檻の格子の前に、指を一本さし出す。"}];
GR_SC.g15_13=[{w:null,t:"山あいの暗い道。"},{w:null,t:"車の中。ヤマトとアレクが、両はしの窓にもたれて眠っている。"},{w:null,t:"前の空中の文字「大理石の谷まで　あと4時間」。"}];
GR_BT[15]={mid:[[{w:null,t:"ノモス、立ち上がる。"},{w:"nomos",t:"見るのは、かまいません。",v:"15_0123"},{w:"nomos",t:"持ち出しは、禁止です。",v:"15_0124"},{w:null,t:"ノモス、机の上の端末を押す。"},{w:null,t:"ヤマトとアレク、目を合わせない。"},{w:null,t:"ヤマト、手首の画面のフォルレオンの印に指を置きかけて、足もとを見る。"},{w:"hero",t:"フォルコン、撃て！",v:"15_0131"},{w:"alek",t:"柱ばっかだ。ここじゃ、あいつらの庭だぞ。",v:"15_0134"},{w:null,t:"ヤマトの手首が光りかける。ヤマト、足もとの欠けた石だたみを見て、自分で手首を下ろす。"},{w:"hero",f:"surprised",t:"アレク、この石じゃ、でかいのは乗れねえ！",v:"15_0138"}],[{w:"hero",t:"アレク。クロベク、切り通しの奥に入れろ。",v:"15_0141"},{w:"alek",t:"……なんでだよ。",v:"15_0142"},{w:"hero",t:"いいから見ろよ。",v:"15_0143"},{w:null,t:"ヤマト、戸口の黒いこすりあとを指さし、それから切り通しの壁を指さす。"},{w:null,t:"アレク、こすりあとと壁を見くらべる。"},{w:"alek",t:"クロベク、運河に下りろ。奥で待て。",v:"15_0146"},{w:null,t:"ヤマト、右手で切り通しの奥を指す。"},{w:"alek",t:"今だ、クロベク！",v:"15_0156"}]],post:[{w:null,t:"リーダーのコモリーナ、水の槍に押されて切り通しの入口まで押し戻され、足場に落ちる。目を回す。"},{w:null,t:"もう一匹も同じように落ち、チップが割れる。"},{w:null,t:"二匹のコモリン、目のオレンジが消え、ふらふらと橋の下のかげへ逃げていく。"},{w:"nomos",t:"……上には、報告だけはします。",v:"15_0162"}]};
GR_EP[15]={"t": "運河の町コリンタ", "sc": [["g15_01", "運河の船の上（朝）", 0], ["g15_02", "橋のたもと・ノモスの机", 0], ["g15_03", "橋のたもと（昼前）", 0], ["g15_04", "回収車の車庫の前（昼）", 0], ["g15_05", "ノモスの机（決まりを逆手に取る）", 0], ["g15_06", "車庫の中・回収車の記録", 0], ["g15_07", "勝負（2Dアニメ）", 1], ["g15_08", "運河の岸・アナの電話（夕方）", 0], ["g15_09", "運河の岸（けんか）", 0], ["g15_10", "ノモスの机〜ロボタクシー（夕方）", 0], ["g15_11", "屋敷・エリーの部屋（夜）", 0], ["g15_12", "屋敷・檻の部屋（夜）", 0], ["g15_13", "夜の道", 0]]};
GR_SC.g16_01=[{w:null,t:"獅子の門の丘の屋敷。"},{w:null,t:"エリー、寝台のはしに座っている。"},{w:null,t:"戸が軽く二回鳴って、開く。"},{w:"kasia",t:"おはよう。あした、山の向こうへ移るわ。",v:"16_0028"},{w:"elly",f:"serious",t:"……山の向こう？　あした、すぐ？",v:"16_0029"},{w:"kasia",t:"ヴィクターさまの用が済むまで、向こうにいてもらう。",v:"16_0030"},{w:"elly",t:"お姉ちゃんの村から、遠くなる？",v:"16_0031"},{w:"kasia",t:"電話は、向こうでもかけられるわよ。",v:"16_0032"},{w:null,t:"カシア、戸を閉める。"},{w:null,t:"エリー、窓の外を見る。"},{w:null,t:"エリー、手首の画面を開く。"}];
GR_SC.g16_02=[{w:null,t:"大理石の谷。山がまるごと、白い石でできている。",v:"16_0038"},{w:null,t:"谷の入口の道。"},{w:null,t:"谷の両側の山はだが、白い。"},{w:null,t:"ヤマト、肩の白いカバンをかけ直して、谷の奥へ歩きだす。"},{w:null,t:"アレク、少しおくれて歩く。"},{w:"alek",t:"で、保管庫に行って、その子を見つけて、どうすんだよ。",v:"16_0043"},{w:"hero",t:"連れて帰るんだよ。エリーの昔の子なんだろ。",v:"16_0044"},{w:"hero",t:"あの子がいたら、エリーだって帰ってくるじゃん。",v:"16_0045"},{w:"alek",t:"……そんな簡単な話かよ。",v:"16_0046"},{w:"hero",t:"簡単だろ。",v:"16_0047"},{w:null,t:"ヤマト、足を止めない。"},{w:null,t:"アレク、口の中で何か言いかけて、やめる。"},{w:null,t:"第16話　大理石の谷",v:"16_0051"}];
GR_SC.g16_03=[{w:null,t:"日が上がる。"},{w:null,t:"粉が、ヤマトの黒い髪に積もる。"},{w:"hero",t:"（くしゃみ）……ここ、息するだけで白くなるじゃん。",v:"16_0059"},{w:"alek",t:"石の粉だよ。口、閉じて歩けよ。",v:"16_0060"},{w:"hero",t:"アレク、頭まっ白だぞ。じいさんみてえ。",v:"16_0061"},{w:"alek",t:"お前もだよ。",v:"16_0062"},{w:null,t:"フォルン、粉の舞う所で、鼻をしかめてくしゃみ。しっぽの火が、ぼっと大きくなる。"},{w:null,t:"ヤマト、前髪をおさえる。"},{w:null,t:"谷のいちばん奥。"},{w:null,t:"入口の前の地面に、太いタイヤのあとが何本も。"},{w:null,t:"アレク、しゃがんでタイヤのあとを見る。"},{w:"alek",t:"新しいな。ここから何か運び出してる。",v:"16_0068"},{w:"hero",f:"serious",t:"……そんなのより、中だよ。",v:"16_0069"},{w:null,t:"ヤマト、柵の前に立つ。"},{w:"alek",t:"開けといてくれるってことかよ。気味わりいな。",v:"16_0071"},{w:"alek",t:"運河のおっさん、決まりどおり報告したんだな。",v:"16_0072"}];
GR_SC.g16_05=[{w:null,t:"グリフォ、一歩、前に出る。"},{w:null,t:"グリフォ、ヤマトの手のひらに、くちばしの先を近づける。"},{w:null,t:"ヤマトの左の手首の画面が、ぽうっと一度だけ光る。"},{w:null,t:"ヤマト、自分の手首を見る。"},{w:"hero",f:"serious",t:"……お前、エリーの、ぶどう小屋の子だろ。",v:"16_0125"},{w:null,t:"グリフォ、首をかしげる。"},{w:null,t:"フォルン、ヤマトの肩に跳び上がり、そこから頭の上に乗る。グリフォを見下ろして、しっぽを立てる。"},{w:"hero",t:"いてっ。フォルン、頭に爪立てんなって。",v:"16_0128"},{w:null,t:"フォルン、どかない。"},{w:null,t:"グリフォがいた奥のすみに、古い小さな檻が一つ、戸を開けたまま転がっている。"},{w:null,t:"檻の格子に、色のあせた小さな金属の札が、針金一本でぶら下がっている。"},{w:null,t:"ヤマト、札を見る。"},{w:null,t:"ヤマト、だまって、札をズボンのポケットに入れる。"},{w:null,t:"アレク、奥のケースの山の前に立っている。"},{w:"alek",t:"荷が半分ねえ。残りも全部、山の向こう行きだ。",v:"16_0135"},{w:null,t:"グリフォが、急に歩きだす。"}];
GR_SC.g16_06=[{w:null,t:"保管庫の前。ヤマト、谷の入口の道の方を指さす。"},{w:"hero",t:"ほら、こっちだ。車で、エリーのとこ行こうぜ。",v:"16_0140"},{w:null,t:"グリフォ、動かない。"},{w:null,t:"グリフォ、山の方へ歩きだす。"},{w:null,t:"ヤマト、手首の画面にふれる。"},{w:null,t:"今いる谷から、グリフォの向かう山の向こうへ、指でたどる。三つ目の印の上で、指が止まる。"},{w:"alek",t:"三つ目の印も、山の向こうか。",v:"16_0145"},{w:"hero",f:"serious",t:"……分かってるよ。",v:"16_0146"},{w:"alek",t:"でも、屋敷とは反対だぞ。",v:"16_0147"},{w:"alek",t:"エリーに会わせるんじゃなかったのかよ。",v:"16_0148"},{w:"hero",t:"こいつが、あっちに行くって言ってんだよ。",v:"16_0149"},{w:"alek",t:"言ってねえだろ、何も。",v:"16_0150"},{w:"hero",t:"顔見りゃ分かるって。おれ、こいつについてく。",v:"16_0151"},{w:null,t:"アレク、グリフォの顔を見る。"},{w:null,t:"アレク、地図の三つ目の印を見る。それから、山の方を見る。"},{w:"alek",t:"……山越えは、一日じゃ着かねえぞ。",v:"16_0154"},{w:null,t:"アレク、パーカーのポケットからアナのカードを出して、残高を見る。"},{w:null,t:"ヤマト、グリフォの方へ歩きだす。"}];
GR_SC.g16_07=[{w:null,t:"その夜。山の中腹の、岩かげ。",v:"16_0160"},{w:null,t:"大きな岩が屋根のように張り出した下。"},{w:null,t:"まん中に、手のひらほどの折りたたみの加熱板。"},{w:null,t:"アレクが鍋をかきまぜている。"},{w:null,t:"グリフォは、少しはなれた岩の上で、体を丸くしている。目はあいている。"},{w:null,t:"ヤマトは、岩のはしで光の地図を広げて、三つ目の印のあたりを指で大きくしたり小さくしたりしている。"},{w:null,t:"アレク、鍋の火を止める。"},{w:"alek",t:"ヤマト、ほら、ご飯さ——",v:"16_0167"},{w:null,t:"アレク、口を閉じる。"},{w:null,t:"ヤマトも、地図を見たまま、指が止まっている。"},{w:null,t:"しばらく、加熱板の小さな音だけ。"},{w:null,t:"ヤマト、地図を閉じて、だまってアレクの前に座る。"},{w:"hero",f:"serious",t:"……しょっぱ。",v:"16_0172"},{w:null,t:"アレク、自分のカップを一口飲む。顔をしかめる。"},{w:null,t:"アレク、水の筒から、自分のカップに水を足す。"},{w:null,t:"ヤマト、アレクを見ずに、だまって自分のカップを差し出す。"},{w:null,t:"アレク、ヤマトを見ずに、そのカップにも水を足す。"},{w:null,t:"フォルン、ヤマトの頭の上から下りて、カップのにおいをかぐ。"},{w:null,t:"アレク、足もとのクロッコを見る。"},{w:"alek",t:"クロッコ。そっちのやつに、まだしょっぱいか聞いてみろ。",v:"16_0179"},{w:null,t:"クロッコ、アレクを見上げる。それから、ヤマトを見る。"},{w:"hero",f:"serious",t:"……フォルン。ちょうどいいって言っとけ。",v:"16_0181"},{w:null,t:"フォルン、目もあけない。しっぽだけ、ぱたりと動く。"},{w:null,t:"アレク、口のはしが少しゆるむ。"},{w:null,t:"グリフォ、岩の上から、スープの湯気の方へ首をのばす。"},{w:null,t:"ヤマトとアレク、まだ目は合わせないまま、水で薄めたスープを飲む。"}];
GR_SC.g16_08=[{w:null,t:"同じ夜。獅子の門の丘の屋敷。",v:"16_0188"},{w:null,t:"屋敷の広い台所。"},{w:null,t:"はだしのエリーが、廊下から入ってくる。"},{w:null,t:"冷やす棚の明かりが、ついている。"},{w:null,t:"ヴィクターの手に、小さなプラスチックのカップ。"},{w:null,t:"エリー、入口で止まる。ヴィクターが顔を上げる。"},{w:"victor",t:"眠れないのか。",v:"16_0194"},{w:"elly",t:"ううん、のどがかわいただけ。",v:"16_0195"},{w:null,t:"エリーの目が、ヴィクターの手のカップに行く。"},{w:"elly",t:"あ、それ、おいしいよね。村の店にも売ってるよ。",v:"16_0197"},{w:"victor",t:"知ってるのか。……もう一個あるよ。食べる？",v:"16_0198"},{w:"elly",t:"食べる！",v:"16_0199"},{w:null,t:"ヴィクター、冷やす棚から、同じカップを一つ出して、カウンターをすべらせる。"},{w:null,t:"二人、だまってゼリーを食べる。"},{w:null,t:"ヴィクター、スプーンを止める。"},{w:"victor",t:"（古代ギリシャ語で・字幕あり）どこの生まれ？",v:"16_0203"},{w:null,t:"エリーのスプーンが、カップのふちで止まる。目が丸くなる。"},{w:"elly",f:"serious",t:"……え、その言葉、話せるの？",v:"16_0205"},{w:null,t:"ヴィクター、答えずに、エリーを見て笑う。"},{w:null,t:"エリー、少し息をすって、同じ古い言葉に切りかえる。"},{w:"elly",t:"（古代ギリシャ語で・字幕あり）わかんない。赤ちゃんの時に、拾われたんだって。",v:"16_0208"},{w:"elly",t:"（古代ギリシャ語で・字幕あり）……ねえ、だれに習ったの？",v:"16_0209"},{w:"victor",t:"（古代ギリシャ語で・字幕なし）ウーデノス。",v:"16_0210"},{w:"victor",t:"古い子を一体起こしてくれたら、檻の子を十匹放すよ。",v:"16_0221"}];
GR_SC.g16_09=[{w:null,t:"エリーの部屋。"},{w:null,t:"エリー、寝台のはしに座る。"},{w:null,t:"空中に、小さなファイルが一つ。"},{w:null,t:"エリー、そのしるしを、じっと見ている。"},{w:null,t:"ピリポンが、エリーの髪から出て、ひざの上で丸くなる。"},{w:null,t:"エリー、しるしを指でそっと押す。"},{w:null,t:"ピリポン、エリーを見上げて、小さく、ぱちっ。"}];
GR_BT[16]={mid:[[{w:null,t:"ヤマトの目が、その左の羽に止まる。"},{w:null,t:"ヤマト、天井と柱のあいだを見上げる。"},{w:"alek",t:"柱のかげに隠れやがる。クロベク、目ぇ離すな！",v:"16_0087"},{w:"alek",t:"石の上じゃ光が強えぞ。ヤマト、次をもらう前に撃て！",v:"16_0089"},{w:"hero",t:"フォルコン、正面から撃て！",v:"16_0090"},{w:null,t:"ヤマト、グリフォの跳んだ方向を見る。"},{w:"alek",t:"クロベク、しっかりしろ！",v:"16_0096"},{w:null,t:"ヤマト、もう一度グリフォを見る。"},{w:null,t:"ヤマト、グリフォの左の羽から目を離さない。"},{w:"hero",t:"フォルコン、左の羽には撃つなよ。",v:"16_0102"},{w:null,t:"ヤマト、右手で、グリフォの右の、柱と柱のあいだを指す。"},{w:"hero",t:"フォルコン、フォックスファイヤー！",v:"16_0110"}]],post:[{w:null,t:"同じ時、柱に押しつけられていたボロウルも、クロベクの二発目の突き（背中の青い筋が、また一本消える）で目を回す。"},{w:null,t:"グリフォ、起き上がる。"},{w:null,t:"フォルコンの光が引いてフォルンに戻る。フォルン、グリフォとヤマトのあいだに入って、しっぽを立てる。"}]};
GR_EP[16]={"t": "大理石の谷", "sc": [["g16_01", "屋敷・エリーの部屋（夜明け）", 0], ["g16_02", "谷の入口（夜明け）", 0], ["g16_03", "谷の奥（朝）", 0], ["g16_04", "保管庫（2Dアニメ）", 1], ["g16_05", "保管庫（勝負のあと）", 0], ["g16_06", "保管庫の外（昼）", 0], ["g16_07", "山の中腹の岩かげ（夜）", 0], ["g16_08", "屋敷の台所（夜中）", 0], ["g16_09", "屋敷・エリーの部屋（夜中）", 0]]};
GR_SC.g17_01=[{w:null,t:"山の向こう。古い迷宮の、いちばん奥。",v:"17_0025"},{w:null,t:"天井の高い、円い石の部屋。"},{w:null,t:"部屋の左右に、太い柱が一本ずつ。"},{w:null,t:"いちばん奥の壁いっぱいに、大きな石の扉。"},{w:null,t:"扉のすきまから、寝息のような低い音。"},{w:null,t:"扉の前の高い段に、ヴィクター、カシア、エリー。"},{w:null,t:"段の下に、荷運びロボットが一台。"},{w:null,t:"ヴィクター、段から扉の前へ出る。手首を、扉の字に当てる。"},{w:null,t:"字は、一つも光らない。"},{w:"victor",t:"エリー、扉に何て書いてあるか読めるかい。",v:"17_0035"},{w:"elly",t:"うん。寝てる子のことと、起こし方が書いてある。",v:"17_0036"},{w:"elly",t:"あと、いちばん下に「起こさないでね」って。",v:"17_0037"},{w:"victor",t:"いちばん下のは、読まなかったことにしよう。",v:"17_0038"},{w:"elly",t:"起こしたら、あの子たち、みんな外に出してくれるんだよね。",v:"17_0041"},{w:"victor",t:"約束だからね。起こしてくれたら、十匹放すよ。",v:"17_0042"},{w:null,t:"第17話　迷宮",v:"17_0051"}];
GR_SC.g17_02=[{w:null,t:"同じ朝。山の道を、グリフォが先に立って歩いていく。",v:"17_0057"},{w:null,t:"岩と低い木の山道。"},{w:null,t:"そのうしろにヤマト。"},{w:null,t:"十歩うしろに、アレクとクロッコ。"},{w:null,t:"ヤマト、手首の光の地図をちらっと開く。"},{w:null,t:"ヤマト、一度だけふり返る。アレクは車輪のあとを見ていて、顔を上げない。"},{w:null,t:"フォルン、ヤマトの頭の上から、グリフォの後頭部をにらむ。"}];
GR_SC.g17_03=[{w:null,t:"昼前。がけの下に、古い石の門が口をあけていた。",v:"17_0066"},{w:null,t:"がけをくりぬいた石の門。"},{w:null,t:"門の中は、まっ暗。フォルンのしっぽの火が、入口の壁を照らす。"},{w:null,t:"グリフォ、迷わず右の道の前へ行って、座る。"},{w:null,t:"ヤマト、アレクの方を見ないまま、頭の上のフォルンに言う。"},{w:"hero",t:"フォルン、だれかさんに言っとけ。道くらい一人で分かるって。",v:"17_0071"},{w:null,t:"アレク、入口の壁にもたれて、腕を組む。"},{w:"alek",t:"クロッコ、だれかさんに言っとけ。グリフォは右にいるぞって。",v:"17_0073"},{w:"hero",f:"serious",t:"……聞こえてねえし。",v:"17_0074"},{w:null,t:"ヤマト、左の道に入っていく。頭の上のフォルンのしっぽの火が、だんだん小さくなる。"},{w:null,t:"……しばらくして。"},{w:null,t:"グリフォは、右の道の前に座ったまま。"},{w:null,t:"ヤマト、コケの顔を見て、止まる。"},{w:null,t:"頭の上のフォルン、大きなあくび。"},{w:null,t:"アレク、壁にもたれたまま、腕をほどく。"},{w:null,t:"ヤマト、グリフォを見る。"},{w:"hero",f:"serious",t:"……グリフォ、お前、分かってたなら言えよ。",v:"17_0082"},{w:null,t:"フォルン、ヤマトの頭の上から、しっぽでヤマトのおでこを、ぺしっ。"},{w:null,t:"ヤマト、耳まで赤くなって、右の道へずんずん入っていく。"},{w:null,t:"アレク、横を向く。肩が一回だけ、ふるえる。"}];
GR_SC.g17_04=[{w:null,t:"迷宮の奥。起きてからずっと、ミノタスは半分寝たままだった。",v:"17_0088"},{w:null,t:"台座の上。ミノタスのまぶたは半分。鼻から、長い息。"},{w:null,t:"段の下。ヴィクターが、手のひらほどの黒い機械を出す。"},{w:null,t:"ヴィクター、機械を一つめの檻に近づける。"},{w:null,t:"二つめ、三つめ。"},{w:null,t:"檻の戸が、ぜんぶ一度に開く。"},{w:null,t:"子どもたちが、まばたきする。"},{w:null,t:"一匹が、外への通路の方へ走り出す。"},{w:null,t:"片耳の先が折れた子だけが、檻の前に残って、エリーを見上げている。"},{w:null,t:"エリー、段から下りて、その子の前にしゃがむ。"},{w:"elly",t:"カシアさん。この子、耳の先だけ折れてるの。かわいくない？",v:"17_0099"},{w:"kasia",t:"あんまり見てると、離れられなくなるわよ。",v:"17_0100"},{w:"elly",t:"だいじょうぶ。見送るだけだもん。",v:"17_0101"},{w:"elly",t:"ほら、もう行っていいんだよ。外は、あっちだから。",v:"17_0103"},{w:"victor",t:"これで十匹だね。",v:"17_0106"},{w:"elly",t:"あの子たち、どこに行くの？",v:"17_0107"},{w:"victor",t:"どこへでも。もう、だれの子でもないからね。",v:"17_0108"},{w:"victor",t:"さて。起きたなら、立ってもらおうか。",v:"17_0111"}];
GR_SC.g17_05=[{w:null,t:"細い石の通路。フォルンのしっぽの火の明かり。"},{w:null,t:"奥から、ぱたぱたぱたっと、たくさんの小さな足音が近づいてくる。"},{w:null,t:"暗がりから、小さな子たちが走り出てくる。"},{w:null,t:"走っていく子の耳のうしろに、小さな新しい傷のあと。"},{w:null,t:"片耳の先が折れた子が、ヤマトの足の横を走り抜けていく。"},{w:null,t:"ヤマト、ふり返って、子どもたちが走っていく方を見る。それからアレクを見る。"},{w:null,t:"グリフォが、奥へ歩きだす。"},{w:null,t:"通路の先。床が細い石の橋になって、下は暗い穴。"},{w:null,t:"ヤマトの頭の上のフォルンと、前を行くグリフォが、にらみ合う。"},{w:null,t:"足もとの石が、がらっと崩れる。"},{w:null,t:"フォルンがヤマトの頭から跳ぶ。"},{w:null,t:"ヤマトとアレクも、一人ずつ跳んでわたる。"},{w:null,t:"その先で、道が五つに分かれている。"},{w:"alek",t:"クロッコ、まんなか行くぞ。",v:"17_0127"},{w:null,t:"アレク、まんなかの道へ入る。"},{w:null,t:"ヤマト、何か言いかけて、口を閉じる。"},{w:"hero",t:"フォルン。おれも、まんなかだと思ってたからな。",v:"17_0130"},{w:null,t:"フォルン、ヤマトの頭の上で、ぷいとそっぽを向く。"},{w:null,t:"まんなかの道の入口。"},{w:null,t:"ヤマト、足を止める。"},{w:null,t:"ヤマト、何も言わずに立ち上がって、アレクのあとを追う。"},{w:null,t:"通路の出口。"}];
GR_SC.g17_06=[{w:null,t:"ヤマト、開いた扉の浮き彫りを見る。"},{w:null,t:"開いた扉のふちに、古い字がびっしり並んでいる。"},{w:null,t:"ヤマト、目を細める。"}];
GR_SC.g17_12=[{w:null,t:"長い通路をぬけると、日はもう傾きはじめていた。",v:"17_0231"},{w:null,t:"奥の通路をぬけると、山の反対側の斜面。"},{w:null,t:"下の山道を、黒塗りの大きなロボタクシーが走っていく。"},{w:null,t:"ヤマトとアレク、出口に並んで立って、息を切らしている。"},{w:null,t:"グリフォが、車の消えた方を見ている。"},{w:null,t:"ヤマト、手首の光の地図を開く。"},{w:null,t:"アレクが、ヤマトの肩ごしに地図をのぞく。ヤマトの横顔を見る。"},{w:null,t:"ヤマト、印①を指でとんとんとたたく。"},{w:"hero",t:"アレク。次、ここだ。",v:"17_0239"},{w:"alek",t:"……ああ。",v:"17_0240"},{w:null,t:"二人、山を下りる道を歩きだす。"}];
GR_SC.g17_13=[{w:null,t:"山のふもと。"},{w:null,t:"片耳の先が折れた小さな子が、草の中を跳ねていく。"},{w:null,t:"草地の向こうの道に、黒い車が一台、音もなく止まっている。"},{w:null,t:"空から、黒いドローンが一機、静かに下りてくる。"},{w:null,t:"網が開いて、落ちる。"},{w:null,t:"草の中で、小さな体が網にからまって、ころがる。"},{w:null,t:"草地にも道にも、人の姿はない。"}];
GR_BT[17]={mid:[[{w:null,t:"ヴィクターが、古代ギリシャ語で短く命じる（字幕なし）。"},{w:null,t:"ヴィクター、回廊の階段を下りてくる二人に気づく。笑顔のまま、手をひらく。"},{w:"victor",t:"やあ。グリフォに案内してもらったのかい。",v:"17_0150"},{w:"hero",t:"エリー！　帰るぞ！",v:"17_0151"},{w:null,t:"ヤマトの手が、ぎゅっとにぎられる。"},{w:"victor",t:"連れて帰りたいなら、どうぞ。",v:"17_0155"},{w:"victor",t:"この子が、通してくれたらだけどね。",v:"17_0156"},{w:null,t:"エリー、ミノタスの方を向く。"},{w:null,t:"ヴィクターの目が、ほんの一瞬、エリーの方へ動く。"},{w:null,t:"カシアがエリーの腕を取り、段の奥の通路の入口まで連れていく。"},{w:"kasia",t:"ヨルフク。あの二人を、奥へ通さないで。",v:"17_0162"},{w:"hero",t:"フォルン！",v:"17_0165"}],[{w:"alek",t:"クロベク、あいつ続けて二回来るぞ。気い抜くな！",v:"17_0172"},{w:null,t:"アレクの目が、焦げた根の先に止まる。"},{w:"alek",t:"クロベク、足止めしろ！　あいつ、石の上じゃ硬えんだ！",v:"17_0176"},{w:"alek",t:"クロベク、大技が来る！　どっかに隠れろ！",v:"17_0183"},{w:null,t:"ヤマトとアレク、赤いふちの外へ。"}],[{w:null,t:"ヤマトの目：ミノタスのもつれる足。"},{w:null,t:"アレクの目：左の柱。"},{w:"hero",t:"左の柱！",v:"17_0191"},{w:null,t:"ヤマトの声と同じ時に、アレクの右手が、もう左の柱を指している。"},{w:null,t:"ヤマトとアレクの左の手首が、同時に上がる。"},{w:"hero",f:"serious",t:"……グレンカイザー。",v:"17_0198"},{w:"hero",f:"surprised",t:"グリフォ、光であの黒い鳥、追っぱらえ！",v:"17_0205"},{w:"hero",f:"surprised",t:"いけえっ、グレンカイザー！",v:"17_0209"}],[{w:null,t:"カシア、通路の入口から指を一本。"},{w:null,t:"ヴィクター、古代ギリシャ語で短く命じる。"},{w:null,t:"ヴィクター、笑顔のまま、命じるのをやめる。"},{w:"victor",t:"……もういい。見えた。",v:"17_0219"},{w:"victor",t:"きみたちの融合もね。今日は、いい物を二つ見たよ。",v:"17_0221"},{w:"victor",t:"この子は置いていこう。今日は、アトラード一体で足りるよ。",v:"17_0224"}]],post:[]};
GR_EP[17]={"t": "迷宮", "sc": [["g17_01", "迷宮のいちばん奥の広間（朝）", 0], ["g17_02", "山の道（朝）", 0], ["g17_03", "迷宮の入口（昼前）", 0], ["g17_04", "迷宮の奥の広間（昼前）", 0], ["g17_05", "迷宮の通路（昼前）", 0], ["g17_06", "広間を見下ろす回廊（昼前）", 0], ["g17_07", "迷宮の奥の広間・勝負の頭", 1], ["g17_08", "勝負・押される", 1], ["g17_09", "勝負・左の柱", 1], ["g17_10", "勝負・角の根", 1], ["g17_11", "止める", 1], ["g17_12", "迷宮の裏の出口（昼すぎ）", 0], ["g17_13", "山のふもとの草地（夕方）", 0]]};
GR_SC.g18_01=[{w:null,t:"その夜。ふもとでロボタクシーを拾い、二人は村の外れの競技場に着いた。",v:"18_0027"},{w:null,t:"競技場の前の道に、荷室の広い白いロボタクシーが止まる。"},{w:null,t:"月の下の競技場。"},{w:null,t:"細長い広場。"},{w:null,t:"ヤマト、まっすぐ土手のすその低い柵の方へ歩いていく。"},{w:null,t:"うしろから、アレク。"},{w:"alek",t:"山から何も聞かずについてきたけどさ。なんで競技場なんだよ。",v:"18_0033"},{w:"hero",t:"迷宮の奥の扉に、角の絵があったじゃん。",v:"18_0034"},{w:"hero",t:"この下にも、角と虹色の羽の扉があるんだよ。",v:"18_0035"},{w:"alek",t:"ああ、お前らが勝手に入ってた、あの地下か。",v:"18_0036"},{w:"hero",t:"そう。エリーと、扉の前まで行ったんだ。",v:"18_0037"},{w:null,t:"ヤマト、手首の光の地図を開く。"},{w:"hero",t:"ほら。地図の印も、ちょうどこの真下なんだ。",v:"18_0039"},{w:"alek",t:"ってことは、ヴィクターはエリー連れて、ここに来るのか。",v:"18_0040"},{w:"hero",t:"そう。だから先に入って、待ってようぜ。",v:"18_0041"},{w:"alek",t:"お前にしちゃ、ちゃんと考えてんじゃねえか。",v:"18_0042"},{w:"hero",t:"「にしちゃ」は、いらねーじゃん。",v:"18_0043"},{w:null,t:"アレク、口のはしだけで笑う。"},{w:null,t:"ヤマト、柵をくぐりかけて、止まる。"},{w:"hero",t:"あ、その前に、アナさんに電話する。",v:"18_0046"},{w:"alek",t:"今か？　もう夜中だぞ。",v:"18_0047"},{w:"hero",t:"堰を守るって言ってたし、たぶん起きてるって。",v:"18_0048"},{w:null,t:"ヤマト、手首の画面にふれる。"},{w:"ana",t:"ヤマト？　どうしたの、こんな時間に。",v:"18_0050"},{w:"hero",t:"アナさん。あした、エリーに会えるかもしれないんだ。",v:"18_0051"},{w:"ana",t:"……ほんと？　どこで。",v:"18_0052"},{w:"hero",t:"言ったらアナさん来ちゃうじゃん。ヴィクターも来るのに。",v:"18_0053"},{w:"hero",t:"代わりに、エリーへの伝言を撮って送ってよ。",v:"18_0054"},{w:null,t:"声の波形が、少しのあいだ平らになる。"},{w:"ana",t:"……分かった。村のみんなにも映ってもらうね。",v:"18_0056"},{w:"hero",t:"うん。頼むね。",v:"18_0057"},{w:null,t:"声の波形が消える。"},{w:null,t:"アレク、少しはなれた所で、ヤマトのうしろ姿を見ている。それから、柵の向こうの暗い入口を見る。"}];
GR_SC.g18_02=[{w:null,t:"競技場の、真下。",v:"18_0065"},{w:null,t:"ひんやりした石の通路。"},{w:null,t:"ヤマトが先、アレクが二歩うしろ。"},{w:null,t:"通路のとちゅう。"},{w:null,t:"アレク、ヤマトの横顔を見る。"},{w:null,t:"ヤマト、また歩きだす。"},{w:null,t:"通路は、扉のすぐ横に出る。"},{w:null,t:"通路を出たすぐ横、広間のつきあたりに、大きな石の扉。"},{w:null,t:"扉のすきまから、低い寝息。"},{w:null,t:"広間の右手に、上へ続く石の階段。"},{w:null,t:"ヤマト、扉の横の壁のくぼみを指さす。"},{w:null,t:"ヤマト、エリーの白い肩かけカバンを、ひざの上に抱える。"},{w:null,t:"第18話　競技場の下",v:"18_0080"}];
GR_SC.g18_03=[{w:null,t:"あくる朝。オリーヴァ村へ下りていく道。",v:"18_0086"},{w:null,t:"オリーブの丘のあいだの道。"},{w:null,t:"ロボタクシーの中。"},{w:null,t:"道が曲がる。"},{w:null,t:"格子のすきまの檻。"},{w:null,t:"エリーの手が、窓ガラスにつく。"},{w:"elly",t:"ヴィクターさん、あの子、きのう放した子だよ。",v:"18_0092"},{w:"elly",t:"なんで、また檻にいるの？",v:"18_0093"},{w:null,t:"ヴィクター、画面から目を上げて、にこっと笑う。"},{w:"victor",t:"放すとは言ったよ。二度と捕まえないとは言ってない。",v:"18_0095"},{w:null,t:"ヴィクター、また画面に目をもどす。"},{w:null,t:"エリー、窓の外を見たまま、口を閉じる。"},{w:null,t:"回収車とロボタクシーが、村の外れの競技場の前に止まる。"},{w:null,t:"ヴィクター、先に降りて、ふり返らずに競技場の門へ歩いていく。"},{w:null,t:"エリー、車を降りる。"},{w:null,t:"エリー、手首の画面を見る。"},{w:null,t:"エリー、競技場の門へ歩いていく。"},{w:null,t:"ゼノが回収車から降りて、うしろの荷台を開ける。"},{w:null,t:"ゼノ、門の方を見る。"},{w:null,t:"ゼノ、手首の画面を、檻の錠に当てる。"},{w:null,t:"折れ耳の子は、耳のうしろのチップを光らせたまま、同じ格好で座っている。"},{w:null,t:"ゼノ、何も言わずに、荷台の戸だけを閉める。"}];
GR_SC.g18_04=[{w:null,t:"右手の階段の上で、板がはずされる。"},{w:null,t:"ヴィクター、ゼノ、エリーが下りてくる。"},{w:null,t:"ヴィクターとゼノは、階段の下の岸に残る。"},{w:null,t:"くぼみの中。"},{w:"victor",t:"これで二つ目だね。エリー、頼むよ。",v:"18_0114"},{w:null,t:"エリー、扉を見上げる。"},{w:null,t:"エリー、手首の画面を扉の字に当てる。"},{w:null,t:"エリー、古代ギリシャ語で一言。"},{w:null,t:"足の下から、低い音。"},{w:null,t:"扉の奥。白い大きな馬の形。"},{w:"hero",t:"エリー。",v:"18_0122"},{w:"elly",t:"ヤマト。アレクも。ご飯、ちゃんと食べてる？",v:"18_0125"},{w:"hero",t:"食べてるって。それより、これ見て。",v:"18_0126"},{w:"ana",n:"アナ（ヤマトの画面の中）",t:"エリー。村は、こっちで守ってるから。",v:"18_0129"},{w:"victor",t:"……そっちを選ぶんだね。",v:"18_0140"},{w:"victor",t:"いいよ。戻りたくなったら、いつでもおいで。",v:"18_0141"},{w:"victor",t:"でも、村のことは何も変わってないよ。",v:"18_0142"},{w:"victor",t:"じゃあ、起きたての子の、ためしの相手をしてもらおうか。",v:"18_0144"}];
GR_SC.g18_10=[{w:null,t:"ゼノ、階段を下りてきて、黙って水路に入り、ラッコンを抱え上げる。首のタオルで、ラッコンの顔の水をふく。"},{w:null,t:"ペガライ、座りこんだまま、角を下げて目を閉じている。"},{w:null,t:"グリフォ、ずぶぬれの羽を体に寄せ、エリーの足もとに座る。エリーがその頭に手を置く。"},{w:null,t:"グレンカイザーの光がほどけて、フォルンとクロッコに戻る。"},{w:null,t:"ヴィクター、ペガライを一度だけ見る。それから、手首の画面を空中に開く。"},{w:null,t:"ヴィクター、その画面を、エリーの方へ少しだけ向ける。笑顔。"},{w:"victor",t:"買い手にはね、きみが自分で来る所を見せたいんだ。",v:"18_0218"},{w:null,t:"エリー、答えない。グリフォの頭に手を置いたまま。"},{w:null,t:"ヴィクター、先に階段を上がっていく。"},{w:"hero",t:"これ。屋台のいすに忘れてったやつ。",v:"18_0227"},{w:"elly",t:"わたしのカバン……ずっと持っててくれたの？",v:"18_0228"},{w:"hero",t:"フォルンが毎晩この上で寝るから、置いてけなかったんだよ。",v:"18_0229"},{w:"alek",t:"夜になったら、裏の道からホテルに帰るぞ。",v:"18_0232"},{w:"alek",t:"あいつがいいって言っても、まわりの車は知らねえだろ。",v:"18_0233"},{w:"elly",t:"うん。お姉ちゃん、起きて待ってるかな。",v:"18_0234"},{w:"hero",t:"アナさんなら、絶対起きてるって。",v:"18_0235"}];
GR_SC.g18_11=[{w:null,t:"その日の夕方。村のいちばん上の、ため池のほとり。",v:"18_0241"},{w:null,t:"夕日。ため池の水が、赤い空を映している。"},{w:null,t:"池のまわりに、黒い車が三台。"},{w:null,t:"池の向こう、丘の頂上に、研究所あとのくずれた丸屋根が、夕日で赤い。"},{w:null,t:"ゼノが、首にタオルをかけたまま近づいてくる。"},{w:"zeno",t:"ヴィクターさま。地下を出る時に、見たんですが。",v:"18_0246"},{w:"zeno",t:"天馬が、あの女の子の言うことを聞いてます。",v:"18_0247"},{w:null,t:"ヴィクターの指が、画面の上で止まる。"},{w:null,t:"ヴィクター、笑顔のまま。"},{w:"victor",t:"……そう。",v:"18_0250"},{w:null,t:"ヴィクター、車から降りて、立ち上がる。"},{w:null,t:"ヴィクター、丘の上の研究所あとを見上げる。"},{w:null,t:"画面が一つずつ、ひとりでに消えていく。"}];
GR_BT[18]={mid:[[{w:null,t:"ヴィクター、もう一度命じる。ペガライは目を閉じて動かない。"},{w:"elly",t:"ピリムサ、石の上から、ぱちってやって！",v:"18_0164"},{w:"alek",t:"待て、水の中に雷撃つな。こっちまで来るぞ。",v:"18_0169"}],[{w:null,t:"ゼノの目が、グレンカイザーとピリムサの方を向く。"},{w:null,t:"エリー、台の上からかがんで、ずぶぬれのグリフォの背に手を置く。"},{w:null,t:"アレク、顔のしぶきを手でぬぐって、ラクドリスのまわりの水を見る。"},{w:"alek",t:"水路の水、もう半分もねえ。",v:"18_0183"},{w:"hero",t:"じゃあ、あと一回しのげばいいじゃん。",v:"18_0184"},{w:"hero",t:"グレンカイザー、岸まで下がって待て。",v:"18_0188"}],[{w:null,t:"エリーの目：台のすぐ横の水路に座りこんだペガライ。"},{w:"elly",t:"グリフォ、こっち！",v:"18_0196"},{w:null,t:"エリー、台のはしにひざをつき、すぐ下のペガライの白い首に手をのばしてふれる。"},{w:"hero",t:"グレンカイザー、ピリムサの前だ！　撃ち終わるまで動くな！",v:"18_0199"}],[{w:"hero",t:"グレンカイザー、今だ！",v:"18_0207"}]],post:[{w:null,t:"湯気が晴れる。ラクドリス、水路の底にあおむけになって、目を回している。"}]};
GR_EP[18]={"t": "競技場の下", "sc": [["g18_01", "夜の古代の競技場（夜）", 0], ["g18_02", "競技場の下・地下の通路（夜ふけ）", 0], ["g18_03", "村へ向かう道・移動の車の中（朝）", 0], ["g18_04", "地下の扉の前（朝）", 0], ["g18_05", "勝負・頭", 1], ["g18_06", "勝負・ペガライ", 1], ["g18_07", "勝負・大波", 1], ["g18_08", "勝負・しのぐ", 1], ["g18_09", "勝負・決着", 1], ["g18_10", "勝負のあと", 0], ["g18_11", "ため池のほとり（夕方）", 0]]};
GR_SC.g19_01=[{w:null,t:"その夜ふけ。三人は、裏の畑の道からホテルへ帰った。",v:"19_0027"},{w:null,t:"収穫のすんだ、段々のぶどう畑。"},{w:null,t:"坂の上の方。"},{w:null,t:"ホテルの白い壁。裏口の戸。"},{w:null,t:"アナ。2100年の作業着の上に、夜の堰の番の上着。"},{w:null,t:"アナの目が、先にエリーの足もとのグリフォに止まる。"},{w:null,t:"アナの片手が、口もとに行く。"},{w:null,t:"アナ、エリーを見る。"},{w:null,t:"エリー、いつもの笑顔を作って、口を開きかける。"},{w:"ana",t:"ちゃんと食べた？",v:"19_0036"},{w:null,t:"エリーの笑顔が、止まる。"},{w:"elly",f:"serious",t:"……まだ。おなかすいた。",v:"19_0038"},{w:"ana",t:"だろうね。入りな。",v:"19_0039"},{w:null,t:"第19話　空の寝床",v:"19_0041"}];
GR_SC.g19_02=[{w:null,t:"ホテルの台所。"},{w:null,t:"アナ、エリーをテーブルの前に座らせる。"},{w:"ana",t:"わたし、ヤニスさんと交代で堰の番してるの。すぐ戻らなきゃ。",v:"19_0049"},{w:"alek",t:"じゃあ、エリーのご飯は、おれらで作っときます。",v:"19_0050"},{w:"ana",t:"台所のもの、何でも使っていいからね。",v:"19_0051"},{w:null,t:"アナ、そう言ったまま、出ていかない。"},{w:null,t:"コンロの前。"},{w:null,t:"アレクが皿を取りにうしろを向く。"},{w:null,t:"フォルンが、調理台の上からそれを見ている。"},{w:null,t:"スープの皿が、エリーの前に置かれる。"},{w:null,t:"エリー、スプーンで一口。"},{w:null,t:"……止まる。"},{w:null,t:"エリー、何も言わずに立ち上がる。"},{w:null,t:"アレク、それを見てから、ヤマトを見る。"},{w:"alek",t:"おい。塩は、ちょっとしか入れてねえぞ。",v:"19_0061"},{w:"hero",t:"薄かったから、おれがあとで足したんだよ。",v:"19_0062"},{w:"alek",t:"……お前、何回ふった？",v:"19_0063"},{w:"hero",t:"三回。山のスープより、ましだろ。",v:"19_0064"},{w:"alek",t:"……あれは、素を二つ入れただけだ。",v:"19_0065"},{w:null,t:"アレク、自分で言って、黙る。"},{w:null,t:"アナ、片手で口をおさえる。"},{w:null,t:"エリー、お湯を足したスープを、最後まで飲む。"},{w:"elly",t:"お湯足したら、ちゃんとおいしいよ。",v:"19_0069"},{w:"alek",t:"（ヤマトに）お前が塩ふらなきゃ、お湯いらなかったんだよ！",v:"19_0070"},{w:null,t:"エリー、皿を置いて、アナの方を向く。"},{w:"elly",t:"お姉ちゃん、おばあちゃんは？",v:"19_0072"},{w:"ana",t:"都の研究所。国の仕事をやめさせるって、行ったきり。",v:"19_0073"},{w:"ana",t:"あんたのこと話したら、なおさら引き下がれないって。",v:"19_0074"},{w:"elly",t:"え、なんで？",v:"19_0075"},{w:"ana",t:"あんたに封を開けさせてるのも、国の仕事なんだって。",v:"19_0076"},{w:null,t:"エリー、テーブルの上の自分の手首の画面を見る。"},{w:null,t:"アナ、立ち上がる。"},{w:"ana",t:"……次は、行く前に電話しな。",v:"19_0079"},{w:"elly",f:"serious",t:"……うん。",v:"19_0080"},{w:"ana",t:"朝まで寝てな。今夜は、ひとりの部屋はなし。みんなとロビーね。",v:"19_0081"},{w:null,t:"アナ、上着のえりを立てて、裏口から出ていく。"}];
GR_SC.g19_03=[{w:null,t:"東の空が、うっすら白くなりはじめたころ。",v:"19_0086"},{w:null,t:"薄暗いロビー。"},{w:null,t:"もう一つのソファで、エリーが横になっている。"},{w:null,t:"ヤマトの左の手首。"},{w:null,t:"印の一つが、強く光っている。"},{w:null,t:"窓ガラスが、かたかたと小さく鳴る。"},{w:null,t:"エリーの手首の画面が鳴る。"},{w:"ana",t:"エリー、起きてる？　丘の上に、何か来た。",v:"19_0093"},{w:"ana",t:"研究所あとの方。黒い車と、それから……大きいのが。",v:"19_0094"},{w:"ana",t:"あんたたちは、ホテルから出ないで。",v:"19_0095"},{w:null,t:"ヤマト、目を開ける。"},{w:null,t:"三人、窓にかけ寄る。"},{w:"hero",t:"印が光ってるの、あの丘だ。",v:"19_0100"},{w:"elly",t:"お姉ちゃん、あのすぐ下にいるんだよ！",v:"19_0101"},{w:"alek",t:"……池の横の坂なら、すぐだ。",v:"19_0102"},{w:"hero",t:"行くぞ！",v:"19_0103"}];
GR_SC.g19_04=[{w:null,t:"三人が丘に駆け上がる。"},{w:null,t:"くぼみの前に、巨体が背中を丸めて座っている。"},{w:null,t:"足もとに、ヴィクター。"},{w:"victor",t:"おはよう。ゆっくり眠れたかい。",v:"19_0114"},{w:"victor",t:"ここは、この子の寝床だったんだよ。ずっと空っぽだったけどね。",v:"19_0115"},{w:null,t:"アトラードが、ゆっくり立ち上がる。"},{w:null,t:"ヴィクター、立ち上がる巨体の足もとから、ゆっくり歩いて離れ、くぼみのうしろの崩れた壁の上に上がる。"},{w:null,t:"アトラード、坂の下の池の方へ一歩出る。"},{w:null,t:"三人とフォルンたちが、アトラードの前に走りこむ。"},{w:"ana",t:"（池の向こうのはしの堰の上から、声をはり上げて）エリー！　出るなって言ったでしょ！",v:"19_0120"},{w:"hero",f:"serious",t:"……でっけえ。",v:"19_0122"},{w:"victor",t:"きのうの天馬は、いい勉強になったよ。",v:"19_0123"},{w:"victor",t:"だから今日は、先に手を打っておく。",v:"19_0124"},{w:"alek",t:"（ヤマトに）おれとお前の画面がつながらねえ。融合はできねえぞ。",v:"19_0128"}];
GR_SC.g19_08=[{w:null,t:"ヴィクター、手首の画面を空中に広げて、買い手の国々と話しはじめる。"},{w:null,t:"倒れたピリポンを抱いたエリーが、聞こえた言葉を、小さく口に出して訳す。"},{w:"elly",t:"（小さく）……あすの夜明けに見せる。今はこの国の仕事だけ。",v:"19_0188"},{w:"elly",t:"（小さく）来月からは、どの国にも貸す。",v:"19_0189"},{w:null,t:"エリーの口が、次の言葉の所で止まる。"},{w:null,t:"アレクとヤマトが、エリーの横顔を見る。"},{w:null,t:"まだ薄暗い西の稜線に、小さな星の集まりが沈んでいく。"},{w:null,t:"最後の星が、稜線に沈みきる。その瞬間、アトラードが西の空へ顔を上げ、大きく伸びをする。"},{w:null,t:"ヴィクター、画面から顔を上げて、伸びをするアトラードを見る。"},{w:"victor",t:"（古代ギリシャ語・字幕）そのまま待て。",v:"19_0195"},{w:null,t:"アトラード、腕を下ろしたまま、動かない。"},{w:"x",n:"買い手の声",t:"（字幕）今の動きは？",v:"19_0197"},{w:"victor",t:"（買い手の言葉・字幕）寝ぼけても、言葉一つで止まるよ。",v:"19_0198"},{w:"victor",t:"止めたいなら、自分でおいで。",v:"19_0202"},{w:"victor",t:"言ったよね。自分で来る所を、見せたいって。",v:"19_0203"},{w:"elly",f:"serious",t:"……お姉ちゃん。",v:"19_0219"}];
GR_SC.g19_09=[{w:null,t:"その日、アトラードは丘の上で、一日じゅう眠っていた。",v:"19_0223"},{w:null,t:"村の坂道。パン屋の前で、店の人が手を止めて丘を見上げる。"},{w:null,t:"丘の頂上で、巨体がくぼみに丸くなっている。寝息のたびに、背中が上下して、土ぼこりが少し舞う。"},{w:null,t:"遠くの空に、ニュースのドローンが何機も浮いている。"},{w:null,t:"ヴィクターの作業ロボット（四本足・オレンジの輪）が、細い柱を立てていく。"},{w:null,t:"ひもの上に、空中の文字。"},{w:null,t:"ひもの外に、国の役人が二人。"},{w:null,t:"堰の向こう半分に、ヤニスと村の人たち。"},{w:"stavros",t:"この池は村の池だぞ。いつから国のものになったんだ。",v:"19_0231"},{w:"x",n:"国の役人",t:"国の書類が、きちんとそろっていますので。",v:"19_0232"},{w:"x",n:"国の役人",t:"わたしたちは、ひもの外を見ているだけです。",v:"19_0233"},{w:"stavros",t:"見ているだけなら、畑の見張りロボットにもできる。",v:"19_0234"},{w:null,t:"堰の頭の、ひときわ大きな石（要石）。"},{w:null,t:"ホテルのロビー。"},{w:null,t:"ヤマト、フォルンの背中に手をのせる。"},{w:null,t:"アレク、ソファで古い望遠鏡をひざにのせている。"},{w:null,t:"エリーの姿は、ロビーにない。"}];
GR_SC.g19_10=[{w:null,t:"同じ昼。ホテルの二階の、エリーの部屋の窓。"},{w:null,t:"窓の外。坂の上の丘で、巨体が眠っている。寝息のたびに背中が上下して、うろこのすきまの白い光が、昼の光の中でかすかに明るくなったり暗くなったりする。"},{w:null,t:"その下のため池と堰。"},{w:null,t:"窓の内側に、エリー。"},{w:null,t:"エリー、窓ガラスに額をつけて、丘を見ている。"},{w:null,t:"エリー、左の手首の画面にふれかけて、やめる。"}];
GR_BT[19]={mid:[[{w:"hero",t:"フォルレオン、一回当てたら、すぐ下がれ！",v:"19_0138"},{w:"alek",t:"クロベク、池のふちに立て！",v:"19_0142"},{w:null,t:"エリー、声の出ない口で、短く叫ぶ（口の形は「ピリムサ！」）。"},{w:null,t:"エリーの手首の画面が光る。"},{w:"alek",t:"赤いとこから出ろ！　その壁じゃ、かげにならねえ！",v:"19_0154"}],[{w:null,t:"エリーの声が戻る。"},{w:"elly",t:"ナルカミ——！",v:"19_0159"}],[{w:"elly",t:"ナルカミ、もう一回！",v:"19_0170"},{w:"hero",t:"フォルレオン、立て！",v:"19_0173"},{w:null,t:"ヤマト、手首の画面を見る。"},{w:null,t:"ヤマト、ナルカミの前を指さす。"}]],post:[]};
GR_EP[19]={"t": "空の寝床", "sc": [["g19_01", "ホテルの裏口（夜ふけ）", 0], ["g19_02", "ホテルの台所（夜ふけ）", 0], ["g19_03", "ホテルのロビー（東が白むころ）", 0], ["g19_04", "丘の上・研究所あと（東が白むころ）", 0], ["g19_05", "勝負・全部出す", 1], ["g19_06", "勝負・ナルカミ", 1], ["g19_07", "勝負・つぶされる", 1], ["g19_08", "負けのあと・すばる（日の出前）", 0], ["g19_09", "オリーヴァ村（昼）", 0], ["g19_10", "ホテルの二階の窓（昼）", 0]]};
GR_SC.g20_01=[{w:null,t:"オリーヴァ村。負けたその日の、昼すぎ。",v:"20_0024"},{w:null,t:"そのすぐ下に、ため池。"},{w:null,t:"堰の下から坂が始まる。"},{w:null,t:"堰の手前半分から研究所あとまでを、光るひもがぐるりと囲んでいる。"},{w:null,t:"ひもの中と、ホテルの柵のまわりに、チップの子たちが立っている。目の奥に、オレンジの光。"},{w:null,t:"ひものすぐ外に、国の役人が二人。"},{w:null,t:"堰の向こう半分には、村の人たちが数人。"}];
GR_SC.g20_02=[{w:null,t:"坂の途中のテラス。"},{w:null,t:"テラスの柵の外を、チップの子が一体、ゆっくり行き来している。"},{w:null,t:"アナが、空中の画面をいくつも開いたまま、テラスに出てくる。"},{w:"hero",t:"アナさん、あの堰の上のでっかい石、なに？",v:"20_0037"},{w:"ana",t:"要石。堰でいちばん大きくて、重い石なの。",v:"20_0038"},{w:"hero",t:"じゃあ、あれが落ちたら？",v:"20_0039"},{w:"ana",t:"堰が一度に割れて、この坂ごと水の下になるの。",v:"20_0040"},{w:null,t:"ヤマト、丘の上を見る。テラスから見ると、丘の上で眠る巨体の大きな手が、坂の下の要石のちょうど真上に重なって見える。"},{w:"hero",t:"あいつ、あの石のすぐ上で寝てんじゃん。",v:"20_0042"},{w:"ana",t:"だから困ってるの。ひもの中には、入れないし。",v:"20_0043"},{w:null,t:"アナ、空中の画面の一つを指で押す。"},{w:"ana",t:"坂の下の家は、今夜、わたしたちで回って空にする。",v:"20_0045"},{w:null,t:"ひもの外の役人が、こちらをちらりと見て、また手首の画面に目を落とす。"},{w:null,t:"第20話　オリーヴァのため池",v:"20_0048"}];
GR_SC.g20_03=[{w:null,t:"食堂。エリーが、テーブルで温め直したスープを飲んでいる。髪の中からピリポンの耳が出ている。"},{w:null,t:"アレクは窓ぎわで、古い望遠鏡のレンズを布でふいている。"},{w:null,t:"アナが入ってくる。"},{w:"ana",t:"見張りの順番、決めたから。アレクは、夕方の堰ね。",v:"20_0057"},{w:"ana",t:"ヤニスさんと二人で、日が沈むまでお願いね。",v:"20_0058"},{w:"alek",t:"えっ。……あの、ほかの所じゃだめですか。",v:"20_0059"},{w:"ana",t:"ほかって、どこ？",v:"20_0060"},{w:"alek",t:"ホテルの裏とか、坂の下とか。水の近くは、ちょっと。",v:"20_0061"},{w:"elly",t:"落ちなきゃ平気だって。",v:"20_0062"},{w:null,t:"エリー、立ち上がって、アレクのうしろに回る。"},{w:"elly",t:"はい、行ってらっしゃい。",v:"20_0064"},{w:"alek",t:"押すなって！　まだ昼だろ！",v:"20_0065"},{w:null,t:"アレク、押されたまま、望遠鏡だけはしっかり胸にかかえている。"},{w:"ana",t:"それと、おばあちゃん、帰ってきたって。さっき連絡あった。",v:"20_0067"},{w:null,t:"エリーの手が、アレクの背中で止まる。"},{w:"elly",f:"surprised",t:"ほんと！？　家にいるの？",v:"20_0069"},{w:"ana",t:"いるって。顔、見せてきな。",v:"20_0070"}];
GR_SC.g20_04=[{w:null,t:"堰のわきから丘を回りこむ細い道。"},{w:null,t:"ひもの中で、チップの子が二体、同じ歩幅で行き来している。"},{w:null,t:"ヤマトの肩のフォルンが、チップの子をにらんで、毛を立てる。ヤマト、フォルンの背中に手をのせる。"},{w:null,t:"グリフォは、エリーの足に体をくっつけて歩いている。左の羽は、たたんだまま。"},{w:null,t:"丘の頂上の向こう側。"}];
GR_SC.g20_05=[{w:null,t:"エリーが戸をたたく前に、戸が開く。"},{w:"oba",t:"窓から見えてたよ。……背の高いのが、アレクだね。",v:"20_0081"},{w:"oba",t:"三人とも、入りな。",v:"20_0082"},{w:"alek",t:"……おじゃまします。",v:"20_0083"},{w:null,t:"おばあさん、エリーのあごに指をかけて、顔を右と左に向ける。"},{w:"oba",t:"顔色は、悪くないね。",v:"20_0085"},{w:"elly",t:"向こうのご飯、ほんとにおいしかったんだもん。",v:"20_0086"},{w:"oba",t:"そう。あんたのコーヒーは、牛乳入りね。",v:"20_0087"},{w:null,t:"おばあさん、台所の小さな機械に、カップを三つ並べる。"},{w:null,t:"グリフォが、戸口から部屋の中をのぞいて、入ってこない。"},{w:null,t:"おばあさん、戸口の床に、水を入れた皿を一つ置く。"},{w:"elly",t:"おばあちゃん、研究所の方、どうだったの？",v:"20_0091"},{w:"oba",t:"だめだった。書類は全部そろってたよ。",v:"20_0092"},{w:null,t:"おばあさん、牛乳入りのカップを、エリーの前に置く。"},{w:null,t:"ヤマトは窓ぎわ。"},{w:"hero",t:"おばあさん、あいつのこと、前から知ってんの？",v:"20_0095"},{w:"oba",t:"研究所にいた子だよ。ずっと昔、森の発掘場から運ばれてきた。",v:"20_0096"},{w:"hero",t:"森の発掘場って……あの、でっかい骨の型の？",v:"20_0097"},{w:"oba",t:"そう。研究所を閉めた二十年前まで、ここにいたよ。",v:"20_0098"},{w:"hero",t:"じゃあ、なんでまた、ここにいんの？",v:"20_0099"},{w:"oba",t:"……連れてこられたんだよ。",v:"20_0100"},{w:null,t:"おばあさん、コーヒーを一口飲む。"}];
GR_SC.g20_06=[{w:null,t:"夕方。堰の向こう半分。"},{w:null,t:"アレク、ヤニスから三歩はなれた、池からいちばん遠いへりに立っている。"},{w:"stavros",t:"そこじゃ、見張りにならんぞ。",v:"20_0106"},{w:"alek",t:"見えてます。ここからでも、ちゃんと見えてますから。",v:"20_0107"},{w:null,t:"ヤニス、何も言わずに、自分のとなりの石を手でたたく。"},{w:null,t:"ヤニス、筒のふたを開けて、中の麦の粒を手のひらに少し出す。"},{w:null,t:"アレク、パーカーのポケットの中で、望遠鏡の筒をいじっている。"},{w:"stavros",t:"ほんとなら、もうまいてる頃なんだがな。",v:"20_0111"},{w:"alek",t:"麦ですか。ヤニスさんのとこ、オリーブ畑ですよね。",v:"20_0112"},{w:"stavros",t:"オリーブの木の下にまくんだ。昔から、そうしてる。",v:"20_0113"},{w:"stavros",t:"すばるが朝に沈むようになったら、麦まきだ。",v:"20_0114"},{w:"stavros",t:"ここ何日か、もう沈んでる。",v:"20_0115"},{w:null,t:"アレクの手が、止まる。"},{w:"alek",t:"……それ、毎朝ですか。",v:"20_0117"},{w:"stavros",t:"秋の終わりは、毎朝だ。日が出る前に、西の山に沈む。",v:"20_0118"},{w:null,t:"アレク、西の稜線を見たまま。"},{w:null,t:"アレク、望遠鏡の入ったポケットを、上から手でおさえる。"},{w:"alek",t:"ヤニスさん、交代の時間、ちょっと早めてもらえませんか。",v:"20_0121"},{w:"stavros",t:"かまわん。",v:"20_0122"},{w:null,t:"アレク、もう望遠鏡のポケットをおさえて、坂を駆け上がっている。"}];
GR_SC.g20_07=[{w:null,t:"夜。丘の頂上の向こう側の、石の家の庭。"},{w:null,t:"アレクが、古い望遠鏡を石の塀にのせて、のぞいている。"},{w:null,t:"戸口に、おばあさん。"},{w:"alek",t:"おばあさん、庭、借りてすみません。",v:"20_0129"},{w:"oba",t:"好きに使いな。",v:"20_0130"},{w:null,t:"アレク、望遠鏡を夜空の高い所へ向ける。"},{w:null,t:"アレク、望遠鏡をゆっくり下ろしていく。"},{w:"elly",t:"何見てるの？",v:"20_0133"},{w:"alek",t:"ヤニスさんが言ってた、麦まきの星。",v:"20_0134"},{w:"alek",t:"あしたの朝、東が白むころ、あれが西の山に沈む。",v:"20_0135"},{w:"alek",t:"けさ、あれが沈みきった時、あいつ、西を向いたんだ。",v:"20_0136"},{w:null,t:"ヤマト、丘の上の巨体を見る。それから西の稜線を見る。"},{w:"hero",f:"surprised",t:"たまたまじゃねえの？",v:"20_0138"},{w:"alek",t:"ニュースの時も、けさも、同じ向きだった。",v:"20_0139"},{w:"oba",t:"研究所にいたころも、この季節の朝は西の空を見てたよ。",v:"20_0140"},{w:null,t:"三人が、ふり返る。"},{w:"oba",t:"わたしたちは、寝ぼけてるんだと思ってた。",v:"20_0142"},{w:null,t:"アレク、望遠鏡から目を離して、おばあさんを見る。"},{w:"alek",t:"……それ、毎年ですか。",v:"20_0144"},{w:"oba",t:"毎年、沈みきる時に伸びをするんだよ。",v:"20_0145"},{w:null,t:"おばあさん、丘の上の巨体から目を離して、エリーを見る。"},{w:"oba",t:"あの男、買い手に何て言ってたんだい。",v:"20_0147"},{w:"oba",t:"アナから少しは聞いたけど。",v:"20_0148"},{w:null,t:"エリー、少しだけ間をおく。笑っていない。"},{w:"elly",t:"お姉ちゃんに、言ってないのが一つあるの。",v:"20_0150"},{w:"elly",t:"「眠ってる残りも、あの娘がいれば起こせる」って。",v:"20_0151"},{w:null,t:"だれも何も言わない。"}];
GR_SC.g20_08=[{w:null,t:"ホテルの裏。"},{w:null,t:"ヤマト、手首から光の地図を出す。"},{w:"hero",t:"けさ、エリーが叫んだら、あいつの耳がこっち向いた。",v:"20_0157"},{w:"alek",t:"……で？",v:"20_0158"},{w:null,t:"ヤマト、光の地図の上に指で印をつけていく。"},{w:"hero",t:"ドローン割って、グリフォでエリーを耳もとまで運ぶ。",v:"20_0160"},{w:null,t:"フォルン、ヤマトの肩から下りる。しっぽの先で、ヤマトのポケットから落ちたオリーブを一つ焼く。"},{w:null,t:"フォルンが地面に下りた時、左の前足を、ほんの少しだけ浮かせる。"},{w:"alek",t:"グリフォ、飛べんのか？　谷からずっと歩いてたじゃねえか。",v:"20_0163"},{w:null,t:"三人の目が、エリーの足もとのグリフォに行く。"},{w:"elly",t:"グリフォ、ちょっと飛んでみて。",v:"20_0165"},{w:null,t:"グリフォ、立ち上がる。"},{w:null,t:"グリフォ、羽をたたむ。"},{w:null,t:"エリー、グリフォの首をなでる。"},{w:null,t:"フォルンが、焼いたオリーブを一つくわえて、エリーのひざの上に、ぽとっと落とす。自分の分は、もう口の中。"},{w:null,t:"エリー、オリーブをつまんで、食べる。"},{w:null,t:"エリー、ヤマトの方を向く。"},{w:"elly",t:"ヤマト。グリフォが飛べなかったら、",v:"20_0172"},{w:"elly",t:"わたしを、あいつの耳もとまで連れてって。",v:"20_0173"},{w:"hero",t:"おう。",v:"20_0174"},{w:null,t:"アレクが、一瞬だけエリーを見る。"},{w:"hero",t:"アレクとクロッコは、池のそばにいてくれ。",v:"20_0176"},{w:"alek",t:"……分かったよ。",v:"20_0177"},{w:null,t:"ヤマトの目が、もう一度だけ、フォルンの左の前足に落ちる。"},{w:"hero",t:"フォルンは、いちばんうしろな。",v:"20_0179"},{w:"ana",t:"エリー、堰に来て。ヴィクターの所の女の人が来てる。",v:"20_0185"},{w:"ana",t:"銀色の髪の人。ひもを持った子たちを、たくさん連れてる。",v:"20_0186"},{w:"elly",t:"グリフォは、ここにいて。ホテルをお願い。",v:"20_0188"}];
GR_SC.g20_13=[{w:null,t:"カシア、坂の上から下りてきて、土手のへりでヨルフクを抱き上げる。"},{w:null,t:"カシア、何も言わずに区域の奥へ下がる。"},{w:null,t:"光るひもの線は、元の所（要石の右）のまま。"},{w:null,t:"クロコディロス、泳いで戻り、堰のへりの上のアレクの前の水に首を下ろす。"},{w:null,t:"ナルカミも光が引いて、ピリポンに戻る。"},{w:null,t:"ヤニスが、熱を通さない銀色のシートをアレクの肩にかける。"},{w:"elly",t:"アレク、生きてる？",v:"20_0269"},{w:"alek",t:"……見りゃ分かんだろ。",v:"20_0270"},{w:"stavros",t:"結局、池には近づいたな。",v:"20_0272"},{w:"alek",t:"近づいたんじゃなくて、とびこんだんです！",v:"20_0273"},{w:"hero",t:"なに書いたの？",v:"20_0278"},{w:"alek",t:"なんでもねえよ。",v:"20_0279"}];
GR_SC.g20_14=[{w:null,t:"東の空の下のふちが、ほんの少しだけ白みはじめる。"},{w:null,t:"丘の上。研究所あとの前で、アトラードの大きな目が、ゆっくり開く。"},{w:null,t:"西の稜線の上に、小さな星の集まりが、まだ低く残っている。"},{w:null,t:"空のあちこちに、小さな明かりが一つ、また一つ。"},{w:null,t:"坂の下の家々は、明かりが一つもない。"},{w:null,t:"ホテルの裏口の前で、グリフォが顔を上げる。"}];
GR_BT[20]={mid:[[{w:null,t:"三人が、堰の左のはしに駆けつける。"},{w:"kasia",t:"ひもを、堰の端まで広げます。そこ、どいてください。",v:"20_0198"},{w:null,t:"アナ、ヤニス、村の人たちは、堰の左半分に並んだまま動かない。"},{w:"ana",t:"役人さん、黙って見てるんですか！",v:"20_0200"},{w:"x",n:"国の役人",t:"どこまで囲むかも、向こうが決めていいことになってます。",v:"20_0201"},{w:null,t:"カシアの足もとから、小さな光る子が一体、堰の上へ。"}],[{w:null,t:"カシア、手首の画面に指を一本ふれる。"},{w:"alek",t:"七色の方は風の子だ、雷が効くぞ！",v:"20_0213"},{w:"elly",t:"ナルカミ、あの子に雷！",v:"20_0214"}],[{w:null,t:"アレク、石だたみの奥から駆けだす。"},{w:null,t:"アレク、へりのふちで、一回だけ暗い水を見る。"},{w:null,t:"アレク、へりをけって、池にとびこむ。"},{w:null,t:"ヤマト、村の人の前から、アレクのとびこんだ堰のへりへ駆け寄って、ひざをつく。"},{w:"elly",t:"アレク！",v:"20_0230"},{w:"elly",t:"ナルカミ、その子を止めて！",v:"20_0231"},{w:"hero",t:"クロベク、起きろ！　アレク、泳げねえんだぞ！",v:"20_0234"},{w:"hero",t:"クロコディロス……！",v:"20_0243"}],[{w:"alek",t:"（せきこみながら）クロコディロス、堰から離れろ！　石に当てたら終わりだぞ！",v:"20_0250"},{w:"alek",t:"そのまま、ひもの向こうまで押し返せ！",v:"20_0254"}]],post:[{w:null,t:"波は、堰の手前で低くなって消える。"},{w:null,t:"堰の上では、ナルカミがイリュネを押さえたまま。"}]};
GR_EP[20]={"t": "オリーヴァのため池", "sc": [["g20_01", "オリーヴァ村の引き（昼すぎ）", 0], ["g20_02", "アナのホテルのテラス（昼すぎ）", 0], ["g20_03", "ホテルの食堂（昼すぎ）", 0], ["g20_04", "光るひもぞいの道（昼すぎ）", 0], ["g20_05", "おばあさんの石の家（昼すぎ）", 0], ["g20_06", "ため池の堰（夕方）", 0], ["g20_07", "おばあさんの家の庭（夜）", 0], ["g20_08", "ホテルの裏のぶどう畑（夜ふけ）", 0], ["g20_09", "ため池の堰（夜ふけ）・頭", 1], ["g20_10", "堰の上の勝負・押される", 1], ["g20_11", "池の中・初めてかむ", 1], ["g20_12", "ひもの向こうまで・決着", 1], ["g20_13", "勝負のあと（夜ふけ）", 0], ["g20_14", "丘の上（夜明け前）", 0]]};
GR_SC.g21_01=[{w:null,t:"夜明けまで、あと少し。",v:"21_0026"},{w:null,t:"東の空のふちが、白みはじめている。"},{w:null,t:"アレクが戸口で、パーカーのフードをかぶりながら、ヤマトの腕を引っぱっている。"},{w:"alek",t:"急げって！　星が沈むまで、もう時間ねえぞ！",v:"21_0029"},{w:null,t:"ヤマトは、寝ていない顔。"},{w:null,t:"エリーが、裏口へ走りながら、ジャムをぬったパンをヤマトの手に押しこむ。"},{w:"elly",t:"ほら、ご飯先。走りながらでいいから。",v:"21_0032"},{w:"hero",t:"今、食ってる場合かよ。",v:"21_0033"},{w:"elly",t:"食べないと、わたしを上まで連れてけないよ。",v:"21_0034"},{w:null,t:"ヤマト、エリーの顔を見る。それから、二歩先のフォルンを見る。"},{w:null,t:"ヤマト、走りながら、パンを二口で食べる。"}];
GR_SC.g21_02=[{w:null,t:"堰の横の、ため池より高いオリーブ畑の段。"},{w:null,t:"坂の下の家々は、明かりが一つもない。"},{w:null,t:"三人が、段の下の道を、堰の方へ上がっていく。"},{w:"elly",t:"お姉ちゃん、下のみんなは？",v:"21_0042"},{w:"ana",t:"坂の下は、ゆうべ空にした。",v:"21_0043"},{w:"elly",f:"serious",t:"……行ってくるね。",v:"21_0044"},{w:"ana",t:"うん。",v:"21_0045"},{w:null,t:"アナは、それ以上言わない。"},{w:null,t:"ひもの外に、国の役人が二人。"},{w:null,t:"光るひもの入口。"}];
GR_SC.g21_03=[{w:null,t:"エリーが光るひもをくぐる。ヴィクター、アトラードの右肩から笑顔で見下ろす。"},{w:"victor",t:"ちゃんと自分で来たね。",v:"21_0052"},{w:null,t:"ヴィクター、エリーのうしろのヤマトとアレクに、笑顔で手招き。"},{w:"victor",t:"きみたちも、見ていくといい。",v:"21_0054"},{w:null,t:"ヤマトとアレクもひもをくぐる。"},{w:null,t:"第21話　夜明けの星",v:"21_0057"}];
GR_SC.g21_04=[{w:null,t:"ヤマトの手首の画面に「接続なし」（1カット）。アレクが自分の画面を見て、小さく首を振る。"},{w:null,t:"三人の手首が光る。"},{w:"hero",t:"フォルコン、うしろにいろ。",v:"21_0066"},{w:null,t:"フォルコン、いちばんうしろの堰の上に座る。"},{w:null,t:"空の見物のドローンの一機から、買い手の言葉の声（字幕）。"},{w:"x",n:"買い手の声",t:"（字幕）残りの二体は、どうした。",v:"21_0069"},{w:"victor",t:"（買い手の言葉・字幕）今朝は、この一体で足りるよ。",v:"21_0070"},{w:null,t:"ヴィクター、東を背に、空のドローンへ向かって、買い手の言葉で話す（字幕）。"},{w:"victor",t:"言葉一つで、あの石を持たせてみせるよ。",v:"21_0073"}];
GR_SC.g21_05=[{w:null,t:"ヴィクターが古代ギリシャ語で一言。アトラード、堰の頭の大きな要石に両手をかけ、ゆっくり持ち上げる。"},{w:null,t:"アレク、西の稜線に低く残る星の集まりと、要石を持つ巨体の腕を、二度、見くらべる。顔から血の気が引く。"},{w:"alek",t:"（ヤマトにだけ）……ヤマト、星見ろ。沈んだら、腕が下りるぞ。",v:"21_0079"},{w:null,t:"ヤマト、西の低い星を見る。"},{w:null,t:"ヤマト、肩の上のヴィクターを見上げる。ヴィクター、西の星をちらりと見て、笑顔のまま、手もとの買い手の画面に戻る。"},{w:null,t:"カシア、エリーにだけ聞こえる声で。"},{w:"kasia",t:"じゃましたら、池のまわりの子たちは引かせない。",v:"21_0083"},{w:"kasia",t:"あなたが自分で来た、ってことにもならない。",v:"21_0084"},{w:null,t:"エリーの肩が一瞬止まる。顔は前を向いたまま。"}];
GR_SC.g21_06=[{w:null,t:"西の稜線に、小さな星の集まりが沈みはじめる。"},{w:null,t:"アトラードは、要石を持ち上げたまま動かない。"},{w:null,t:"ヴィクター、沈みはじめた星を一度だけ見る。笑顔のまま、目を手もとの画面と、堰の上のエリーに戻す。"},{w:null,t:"アレク、ヤマトにだけ聞こえる声で。"},{w:"alek",t:"……そろそろだぞ。",v:"21_0094"}];
GR_SC.g21_14=[{w:null,t:"日が昇る。座りこんだアトラードの肩の上で、ヴィクターが笑顔のまま、動かない。"},{w:null,t:"ヴィクターのまわりに浮かぶ買い手の画面の一つから、声（字幕）。"},{w:"x",n:"買い手の声",t:"（字幕）……言葉一つで、じゃなかったのか。",v:"21_0212"},{w:null,t:"買い手の画面が、一つ、また一つと暗くなって消えていく（1カット）。"},{w:null,t:"坂の下の、だれもいない村の屋根に、朝日が当たる。"},{w:null,t:"空の見物のドローンが、一機、また一機と、向きを変えて離れていく。"}];
GR_BT[21]={mid:[[{w:"hero",t:"今のうちだ！　ナルカミ、エリーのまわりの——",v:"21_0097"},{w:null,t:"エリー、自分のまわりを見回す。"},{w:"elly",t:"いない……ドローン、一機もいないよ！",v:"21_0099"},{w:null,t:"ヤマト、見上げる。"},{w:"hero",t:"上だ！　あいつの耳のとこ！",v:"21_0104"},{w:null,t:"エリー、耳もとへ向かって、古代ギリシャ語で叫ぶ。"},{w:"elly",t:"ナルカミ、耳のところ！",v:"21_0107"},{w:"alek",t:"雷が、下に逃げてる……！",v:"21_0110"},{w:null,t:"ヤマト、ドローンの下を見る。"},{w:"elly",t:"グリフォ、いいよ。無理しないで。",v:"21_0114"},{w:null,t:"エリー、一瞬だけヤマトを見る。"},{w:null,t:"ヤマトは、まだ細い線を見ている。線から、いちばんうしろのフォルコンへ、目が行く。"}],[{w:"hero",t:"フォルコン、下がれ！",v:"21_0126"},{w:null,t:"ヤマト、線を見る。"},{w:null,t:"ヤマト、止めかけた手を、ゆっくり開く。"},{w:"hero",f:"serious",t:"……行け、フォルン。",v:"21_0132"},{w:null,t:"カシアの肩のヨルフクが、羽を広げかける。"},{w:null,t:"カシア、一歩身を乗り出す。"},{w:"kasia",t:"狐を撃ち落とします。",v:"21_0138"},{w:null,t:"ヴィクター、手もとの画面から目を上げない。"},{w:"victor",t:"うん。撃って。",v:"21_0140"},{w:null,t:"カシア、肩のヨルフクを見る。"},{w:"victor",t:"ゼノ。",v:"21_0144"},{w:"x",n:"買い手の声",t:"（字幕）……止められないのか。",v:"21_0149"}],[{w:null,t:"ヤマト、手首の画面の字を読む。"},{w:"hero",f:"serious",t:"……ブレイグリオ。",v:"21_0163"},{w:null,t:"ヤマト、エリーを見る。"},{w:"hero",t:"エリー、乗れ。",v:"21_0166"},{w:null,t:"エリー、一度だけ、要石を持つアトラードの手と、横のカシアを見る。それから、ブレイグリオにまたがる。"},{w:null,t:"ヴィクター、西の空へ顔を向ける。"},{w:"victor",t:"（古代ギリシャ語・字幕）そのまま、持っていろ。",v:"21_0175"},{w:"alek",t:"石が落ちる！",v:"21_0180"},{w:null,t:"エリーの手首と、アレクの手首が、もう一度同時に光る。"},{w:"alek",t:"ライゼンギガス……石を止めろ！",v:"21_0185"}],[{w:null,t:"ヴィクター、上げた片手を、まだ下ろさない。"},{w:null,t:"ヴィクター、耳もとのエリーを、初めてまっすぐ見る。"},{w:"victor",t:"（古代ギリシャ語・字幕）その石を、持ち上げろ！",v:"21_0196"},{w:"elly",t:"（古代ギリシャ語・字幕）お願い。そっと、もどして。",v:"21_0198"}]],post:[]};
GR_EP[21]={"t": "夜明けの星", "sc": [["g21_01", "アナのホテルの台所から裏口へ（夜明け前）", 0], ["g21_02", "坂の上のオリーブ畑（夜明け前）", 0], ["g21_03", "光るひもの中へ", 0], ["g21_04", "接続なし・口上", 0], ["g21_05", "要石", 0], ["g21_06", "沈みはじめる", 0], ["g21_07", "作戦どおり・外れる", 1], ["g21_08", "フォルコンの逆", 1], ["g21_09", "止められない", 1], ["g21_10", "炎だけが効く", 1], ["g21_11", "ブレイグリオ", 1], ["g21_12", "要石がずり落ちる", 1], ["g21_13", "声と、命令", 1], ["g21_14", "日が昇る", 0]]};
GR_SC.g22_01=[{w:null,t:"次の朝。オリーヴァ村。",v:"22_0022"},{w:null,t:"ロビーの空中の画面に、ニュース。"},{w:null,t:"画面が変わる。"},{w:"x",n:"国の報道の係の人",t:"あの会社への仕事は、取り消しました。",v:"22_0025"},{w:null,t:"画面の前で、アナが腕を組んで見ている。"},{w:"hero",t:"取り消しって、もう向こうは何もできないってこと？",v:"22_0027"},{w:"alek",t:"もう国の仕事じゃねえってことだよ。",v:"22_0028"},{w:null,t:"窓の外。丘の上の研究所あとで、アトラードが自分の寝床に横になって眠っている。"},{w:null,t:"おばあさん、画面を閉じて、コーヒーをもう一口。"},{w:null,t:"第22話　オリーブの坂",v:"22_0033"}];
GR_SC.g22_02=[{w:null,t:"堰のわき。国の役人が二人。"},{w:null,t:"エリーが歩いてくる。"},{w:null,t:"エリー、役人の前で止まる。いつもの笑顔を作りかけて、やめる。"},{w:"elly",t:"あの、すみません。聞いてほしいことがあります。",v:"22_0042"},{w:"x",n:"国の役人",t:"どうぞ。",v:"22_0043"},{w:"elly",t:"わたしは、自分であの人の所に行ったんじゃないです。",v:"22_0044"},{w:"elly",t:"村を囲まれて、行くしかなかったんです。",v:"22_0045"},{w:null,t:"役人、ひもの中のチップの子たちを見る。"},{w:"x",n:"国の役人",t:"ご本人が自分で行ったんじゃないなら、話は別です。",v:"22_0047"},{w:"x",n:"国の役人",t:"ただ、囲まれていた証拠が要ります。",v:"22_0048"},{w:null,t:"ヤマト、すぐに前に出て、左の手首を突き出す。"},{w:"hero",t:"これ。運河の車庫で、おれが写したやつ。",v:"22_0050"},{w:null,t:"役人、ヤマトの画面を見る。"},{w:"x",n:"国の役人",t:"写しだけでは、足りません。",v:"22_0052"},{w:null,t:"ヤマトの手が、止まる。"},{w:null,t:"坂の下から、ノモスが上がってくる。息を切らしている。"},{w:"nomos",t:"運河の車庫の、元の記録です。",v:"22_0055"},{w:null,t:"ノモスの手首から、空中に記録が広がる。"},{w:null,t:"ヤマト、自分の画面を、ノモスの記録の横に並べる。"},{w:"hero",t:"ほら、同じじゃん。",v:"22_0058"},{w:null,t:"役人、記録を読む。となりの役人と、目を合わせる。"},{w:"x",n:"国の役人",t:"村を囲んで子どもを連れていくのは、悪いことです。",v:"22_0060"}];
GR_SC.g22_03=[{w:null,t:"少しうしろから、エリー、ヤマト、アレクが丘を上がってくる。"},{w:null,t:"丘の上。寝床で眠るアトラードの足もとに、白いテーブルと椅子が一つ。"},{w:null,t:"役人が近づいてくる。チップの子たちは、目の奥のオレンジを光らせたまま、動かない。"},{w:null,t:"ゼノが、先に動く。"},{w:null,t:"ゼノ、上着の内ポケットから、手のひらほどの黒い板（オレンジの輪）を出す。役人の手に、だまってのせる。"},{w:null,t:"役人、板とゼノを見くらべる。それから、いちばん近くに立っているチップの子に、板を当ててみる。"},{w:null,t:"目の奥のオレンジの光が、ふっと消える。"},{w:null,t:"ゼノ、足を止めない。"},{w:null,t:"折れ耳の子は、ゼノの背中を見たまま、動かない。"},{w:null,t:"カシアは、役人の前まで行って、自分から両手を前に出す。"},{w:null,t:"手首に、光る輪がかかる。"},{w:null,t:"カシア、役人に連れられて歩きだす。"},{w:"kasia",t:"泳げないって、本当だったのね。",v:"22_0078"},{w:null,t:"アレク、口を開けたまま、言葉が出ない。"},{w:"hero",t:"なに、今の人と知り合い？",v:"22_0080"},{w:null,t:"アレク、返事をしない。口を開けたまま、カシアの背中を見ている。"},{w:null,t:"ヤマト、アレクの顔と、カシアの背中を見くらべる。"}];
GR_SC.g22_04=[{w:null,t:"ヴィクター、紅茶のカップを置いて、立ち上がる。笑顔。"},{w:"x",n:"国の役人",t:"村を囲んで、子どもを連れていった疑いです。",v:"22_0086"},{w:"x",n:"国の役人",t:"ご同行をお願いします。",v:"22_0087"},{w:"victor",t:"いいよ。決まりの中で負けたんだ。",v:"22_0088"},{w:null,t:"ヴィクター、手首を前に出す。"},{w:null,t:"歩きだす。エリーの前で止まる。エリーの髪の中から、ピリポンの目がのぞいている。"},{w:null,t:"ヴィクター、エリーを見る。客に向けた笑顔ではない。"},{w:"victor",t:"きみ、才能あるね。",v:"22_0092"},{w:null,t:"エリーは、何も言わない。笑わない。"},{w:null,t:"ヴィクター、歩きだす。"},{w:null,t:"ヤマトの肩のフォルンが、白いスーツをにらんで、のどの奥で低くうなる。"},{w:null,t:"ヴィクター、笑顔のまま、フォルンを一度だけ見る。"},{w:null,t:"アトラードは、寝床で眠ったまま。"},{w:null,t:"エリー、眠るアトラードの顔を、少しのあいだ見上げる。"}];
GR_SC.g22_05=[{w:null,t:"丘の上に、おばあさんが上がってくる。"},{w:null,t:"おばあさん、眠るアトラードの顔の前で、少しだけ立ち止まる。"},{w:null,t:"足もとの草の上に、古い単語帳。"},{w:null,t:"開く。（手もとのアップ）細かい手書きの古代ギリシャ語の字。"},{w:null,t:"おばあさんの指が、一ページ目の字の上で止まる。"},{w:null,t:"おばあさん、単語帳を閉じる。"},{w:null,t:"顔を上げると、少しはなれた所に、エリーが立っている。"},{w:null,t:"研究所の人の一人が、おばあさんに声をかける。"},{w:"x",n:"研究所の人",t:"先生、寝床のまわりの柵は、どうしますか。",v:"22_0110"},{w:"oba",t:"柵はいらない。番は、わたしたちが交代でやる。",v:"22_0111"}];
GR_SC.g22_06=[{w:null,t:"堰のへり。アレクが、池からいちばん遠い所に座って、手首の画面を開いている。"},{w:null,t:"アレク、その横に、二文字だけ足す。"},{w:null,t:"ヤマトが、堰の上を歩いてくる。"},{w:"hero",t:"また隠した。おととい何書いたかも、教えてくんないし。",v:"22_0117"},{w:"alek",t:"教えたら、お前、村じゅうに言いふらすだろ。",v:"22_0118"},{w:"hero",t:"言わねーって。……たぶん。",v:"22_0119"},{w:null,t:"アレク、閉じた画面の上に、手のひらをのせたまま、西の山を見る。"}];
GR_SC.g22_07=[{w:null,t:"三体の古代は、どこへも運ばれなかった。",v:"22_0126"},{w:null,t:"迷宮の奥。横になって眠るミノタス。"},{w:null,t:"競技場の下の水路。座りこんだまま眠るペガライ。"},{w:null,t:"丘の上の研究所あと。"},{w:null,t:"チップの子たちは、あの黒い機械で、一体ずつ外された。",v:"22_0130"},{w:null,t:"研究所あとの広場。"},{w:null,t:"光の消えた子が、きょとんとまわりを見回す。"},{w:null,t:"放された子たちは、村と町の人が引き取った。",v:"22_0133"},{w:null,t:"アナのホテル。"},{w:null,t:"ヤニスの畑。"},{w:"hero",t:"あ、運河の町の、決まりにうるさい人じゃん。",v:"22_0138"},{w:"alek",t:"ノモスさんだろ。名前ぐらい覚えろよ。",v:"22_0139"},{w:"nomos",t:"引き取る人をさがしてるって、聞いたもので。",v:"22_0141"},{w:"nomos",t:"そうしたら、娘がこの子を離さなくて。",v:"22_0142"}];
GR_SC.g22_08=[{w:null,t:"白い都の登録の窓口。"},{w:null,t:"アナ、エリー、グリフォ。"},{w:null,t:"ヤマトの右手が、グリフォの首の毛に、軽くかかっている。"},{w:"x",n:"係の人",t:"持ち主のお名前を、どうぞ。",v:"22_0150"},{w:"ana",t:"アナです。世話は、この子がします。",v:"22_0151"},{w:"x",n:"係の人",t:"お世話の方は、十五さい未満ですね。",v:"22_0152"},{w:"elly",t:"来年の五月十二日で、十五になります。",v:"22_0153"},{w:"ana",t:"その日に、持ち主の名前をこの子に移してください。",v:"22_0154"},{w:"x",n:"係の人",t:"承りました。では、テリオンの方、前足をどうぞ。",v:"22_0155"},{w:null,t:"アナが、登録の板に手を添える。"},{w:null,t:"グリフォ、エリーを見る。"},{w:null,t:"板が光る。「登録完了」。"},{w:"ana",t:"早っ。フォルンの時と、ずいぶんちがうね。",v:"22_0159"},{w:null,t:"ヤマトの頭の上で、フォルンがぷいとそっぽを向く。"}];
GR_SC.g22_10=[{w:null,t:"空港の待合。"},{w:null,t:"「テリオン同伴」の窓口。"},{w:null,t:"バジリク、もぐれない床の上を、のそのそ歩いてレンの足もとへもどる。"},{w:null,t:"少しはなれた所に、ヤマト、エリー、アレク。"},{w:null,t:"ヤマト、天井の近くの空中の案内を見上げる。"},{w:null,t:"ヤマト、肩のフォルンを見る。"},{w:null,t:"ヤマト、少しだけ笑う。"},{w:null,t:"ヤマト、ふり向かずに、日本行きの案内とは反対の方へ歩いていく。"},{w:null,t:"フォルン、床に座ったまま、ヤマトの背中を見る。"},{w:null,t:"ヤマト、前を見たまま、少しだけ笑う（12話の窓口と同じ形・台詞なし）。"},{w:null,t:"長い椅子の端に、レンが座っている。"},{w:null,t:"レン、手首の画面を開く。"},{w:null,t:"レンの口のはしが、少しだけ上がる。"},{w:null,t:"案内の声。「中国行き、ご搭乗を開始します」。"},{w:null,t:"搭乗口の手前で、レンが足を止める。"},{w:null,t:"ヤマト、手を一回だけ上げる。"},{w:null,t:"レン、前を向いて、搭乗口へ入っていく。"}];
GR_SC.g22_11=[{w:null,t:"テラス。エリーがグリフォの羽をブラシでとかしている。"},{w:null,t:"アレクは手すりにもたれて、ジェムコインのカードの残高をにらんでいる。"},{w:null,t:"ヤマト、テラスのはしで、手首の画面を開く。"},{w:null,t:"ヤマト、少しだけ指を止める。……送る。"},{w:null,t:"字の横に、小さく「既読」。"},{w:null,t:"ヤマト、画面を見たまま、少しのあいだ動かない。"},{w:null,t:"アナが、空中の画面を開いたまま、テラスに出てくる。"},{w:"ana",t:"おじいさんから、また宿代がひと月分、振りこまれてたよ。",v:"22_0228"},{w:"hero",f:"serious",t:"……じいちゃん、なんか書いてた？",v:"22_0229"},{w:"ana",t:"振りこみだけ。",v:"22_0230"},{w:null,t:"ヤマト、手首の画面の「既読」の字を見る。肩の上のフォルンが、しっぽを一回ふる。"},{w:null,t:"その時、画面が鳴る。"},{w:null,t:"写真。竹の森の奥の、苔むした大きな岩。"},{w:null,t:"字。「ハオ：竹の森の奥で見つけました。"},{w:"hero",f:"serious",t:"……竜タイプじゃん。",v:"22_0235"},{w:"elly",t:"竜って、図鑑でも絵しか見たことないよ。",v:"22_0236"},{w:"alek",t:"中国だぞ。金、めちゃくちゃかかるぞ。",v:"22_0237"},{w:"elly",t:"賞金、まだ残ってるでしょ？",v:"22_0238"},{w:"alek",t:"残ってるけど、それはおれの研究の——",v:"22_0239"},{w:"elly",t:"残ってるんだね。",v:"22_0240"},{w:"alek",t:"聞けよ！",v:"22_0241"},{w:null,t:"ヤマト、二人を見ないで、ハオの写真の横に、手首から光の地図を出す。"},{w:"hero",t:"アレク。金、数えといて。",v:"22_0249"},{w:"alek",t:"なんでおれが……",v:"22_0250"}];
GR_SC.g22_12=[{w:null,t:"坂の上から、ヤマトが下りてくる。"},{w:null,t:"ヤマト、自分の肩に手をやる。"},{w:null,t:"オリーブの屋台のおばさんが、ヤマトに気づく。"},{w:"x",n:"屋台のおばさん",t:"あら、あんた。日本から来た子だね。まだいたのかい。",v:"22_0261"},{w:"hero",t:"うん。おばちゃん、オリーブ一個ちょうだい。",v:"22_0262"},{w:null,t:"その時、屋台の下から、狐が飛び出してくる。"},{w:"x",n:"屋台のおばさん",t:"あっ、また、あの泥棒！　こらー！",v:"22_0264"},{w:null,t:"フォルン、ヤマトの足もとに着地する。口のオリーブを一つだけ地面に落とし、しっぽの火で、じゅっと焼く。"},{w:null,t:"焼いたオリーブをくわえて、ヤマトの手のひらに、自分から置く。"},{w:null,t:"ヤマト、開いた手のひらの上のオリーブを見る。"},{w:null,t:"フォルン、ヤマトの腕をかけ上がって、肩に乗る。"},{w:null,t:"アレクが、だまって屋台の読み取りの板にカードを当てる。"},{w:null,t:"ヤマト、オリーブを口に入れる。"},{w:"hero",f:"hurt",t:"あちっ。",v:"22_0271"},{w:null,t:"エリーが笑う。"},{w:null,t:"ヤマト、坂の下の海の、そのずっと東の空を見る。"},{w:null,t:"手首の画面のすみで、印④が、小さく光っている。"}];
GR_BT[22]={mid:[[{w:null,t:"ヤマトが歩いてくる。"},{w:"dimi",t:"一回だけ。",v:"22_0178"},{w:"hero",t:"おう。",v:"22_0179"},{w:null,t:"ヤマトの手首が光り、フォルンがフォルレオンに戻る（その場で光って約3秒）。"}]],post:[{w:null,t:"ヤマトの手のひらは、上がったまま。"},{w:null,t:"ほこりの壁を割って、バジリクが顔を出す。"},{w:null,t:"芝のふるえが止まる。"},{w:"dimi",f:"serious",t:"……次も、やる。",v:"22_0198"}]};
GR_EP[22]={"t": "オリーブの坂", "sc": [["g22_01", "ホテルのロビー（次の朝）", 0], ["g22_02", "光るひもの前（朝）", 0], ["g22_03", "研究所あとの前（朝）", 0], ["g22_04", "きみ、才能あるね", 0], ["g22_05", "単語帳", 0], ["g22_06", "堰のへり（朝）", 0], ["g22_07", "後始末（数日）", 0], ["g22_08", "白い都の登録の窓口（数日あと）", 0], ["g22_09", "空港の前の芝生（昼）", 1], ["g22_10", "空港（昼）", 0], ["g22_11", "ホテルのテラス（村に戻った日の夕方）", 0], ["g22_12", "オリーヴァ村・市場の坂（数日あと・昼）", 0]]};
